/* Puzzle data and day numbering, shared by the game (src/App.jsx) and the
   server-rendered content pages (lib/site.js). Puzzle n is PUZZLES[n - 1]:
   never reorder entries that have already been played. */

export const PUZZLES = [
  { answer: "Ohm's Law", discipline: "Electrical Engineering", accept: ["ohms law", "ohm law"], clues: ["Three variables, one triangle every student draws.", "It only holds for a certain class of materials and components.", "Rearranged, it gives you the value of the resistor you need.", "V, I and R.", "Named after a German physicist whose surname became a unit."], reveal: "V = IR — voltage across an ohmic conductor is proportional to the current through it. The constant of proportionality, resistance, is a property of the material and geometry rather than the applied voltage, which is exactly what makes the relationship linear." },
  { answer: "Newton's Third Law", discipline: "Dynamics", accept: ["newtons third law", "newton third law", "action reaction", "third law of motion"], clues: ["One of three laws written down in a single work in 1687.", "It concerns pairs, not single objects.", "Push on a wall and the wall pushes back exactly as hard.", "It's why a rocket moves forward by throwing exhaust backward.", "For every action, there is an equal and opposite reaction."], reveal: "Every force one body exerts on a second body is matched by an equal and opposite force the second exerts back on the first. The two forces act on different objects, which is why they never cancel out despite being equal and opposite." },
  { answer: "Bernoulli's Principle", discipline: "Fluid Mechanics", accept: ["bernoulli", "bernoullis principle", "bernoulli equation"], clues: ["It links two properties of a moving fluid that most people assume are unrelated.", "It falls out of conservation of energy applied along a streamline.", "Speed the flow up and something else must come down to compensate.", "It explains why a shower curtain pulls inward and how a carburettor draws fuel.", "Named after a Swiss mathematician from a famously argumentative family of mathematicians."], reveal: "Along a streamline in steady, incompressible, inviscid flow, increased velocity produces decreased static pressure. It falls directly out of conservation of energy, and explains everything from aircraft lift to why a shower curtain billows inward." },
  { answer: "First Law of Thermodynamics", discipline: "Thermodynamics", accept: ["first law of thermodynamics", "1st law of thermodynamics", "conservation of energy", "first law"], clues: ["It's really just an old idea from mechanics, dressed up for heat and work.", "Energy entering a system has to show up somewhere.", "It can change form, but the books must always balance.", "Add heat, do work, and internal energy is whatever's left over.", "ΔU = Q − W."], reveal: "Energy can neither be created nor destroyed, only converted between forms — heat added to a system minus work done by it equals the change in its internal energy. It's the same conservation-of-energy principle from mechanics, simply extended to account for heat as well as work." },
  { answer: "Binary Search", discipline: "Computer Science", accept: ["binary search"], clues: ["A search strategy that only works if you've done something first.", "That prerequisite is a sorted list.", "Each step throws away half of what's left to search.", "It's the strategy behind guessing a number between 1 and 100 in at most seven tries.", "An O(log n) search algorithm that repeatedly halves a sorted list until the target is found."], reveal: "A search algorithm that repeatedly checks the middle element of a sorted list and discards the half that can't contain the target, running in O(log n) time. It's exactly the strategy behind efficiently guessing a number between 1 and 100 — never more than seven guesses, no matter how the number was chosen." },
  { answer: "Torque", discipline: "Statics", accept: ["torque", "moment", "turning moment"], clues: ["A rotational effect, not a straight-line one.", "It depends on both a force and a distance.", "Push the same force further from the pivot and it grows.", "Its SI unit looks identical to that of energy, though the quantities are different.", "It's what a wrench applies to loosen a bolt: force times lever arm."], reveal: "The rotational equivalent of force, equal to the applied force multiplied by the perpendicular distance from the pivot to its line of action. It's measured in newton-metres — dimensionally identical to energy, though the two are conceptually distinct and never interchanged." },
  { answer: "Capacitor", discipline: "Electrical Engineering", accept: ["capacitor", "capacitance"], clues: ["A component that stores energy in an electric field, not a magnetic one.", "Two conductive plates, separated by an insulator.", "It opposes sudden changes in voltage across itself.", "It blocks steady DC once fully charged, but passes AC readily.", "A component storing electrical energy as an electric field between two conductive plates, C = Q/V."], reveal: "A component that stores electrical energy as an electric field between two conductive plates separated by an insulator, with capacitance defined as charge stored per volt applied. It opposes sudden changes in voltage across itself, which is why it blocks steady DC once fully charged but passes AC signals readily." },
  { answer: "Archimedes' Principle", discipline: "Fluid Mechanics", accept: ["archimedes principle", "archimedes law", "buoyancy"], clues: ["Supposedly discovered in a bathtub, followed by a famous shout of 'Eureka'.", "It explains why a steel ship floats despite steel being denser than water.", "The key isn't the material — it's the shape of the hull displacing water.", "A submerged object feels an upward push equal to something specific.", "The buoyant force on a submerged object equals the weight of fluid it displaces."], reveal: "The buoyant force acting on an object submerged in a fluid equals the weight of the fluid the object displaces. A steel ship floats not because steel is light, but because its hollow hull displaces a volume of water heavy enough to equal the ship's total weight." },
  { answer: "Specific Heat Capacity", discipline: "Thermodynamics", accept: ["specific heat capacity", "specific heat", "heat capacity"], clues: ["A property that decides how 'stubborn' a material is about changing temperature.", "Water has an unusually high value, which is why oceans moderate climate.", "Metals generally have low values — they heat up and cool down quickly.", "It's quoted per unit mass, in joules per kilogram-kelvin.", "The amount of heat needed to raise the temperature of one unit of mass by one degree."], reveal: "The amount of heat energy required to raise the temperature of a unit mass of a substance by one degree. Water's value is unusually high compared to most materials, which is why large bodies of water heat and cool far more slowly than land and moderate the climate around them." },
  { answer: "Neural Network", discipline: "Machine Learning", accept: ["neural network", "artificial neural network", "ann"], clues: ["A computing model loosely inspired by biology, though the inspiration is now mostly historical.", "It's built from layers of simple units, each doing very little on its own.", "Every connection between units carries an adjustable weight.", "Stack enough layers and the model is described as 'deep'.", "A model of interconnected layers of weighted nodes, trained by adjusting those weights to fit data."], reveal: "A computing model built from layers of simple, interconnected units — loosely inspired by biological neurons — where every connection carries an adjustable weight that training tunes to fit data. Stack enough of these layers together and the model earns the label 'deep', giving deep learning its name." },
  { answer: "Hooke's Law", discipline: "Solid Mechanics", accept: ["hookes law", "hooke law"], clues: ["First published as an anagram, to claim priority without revealing the result.", "It holds only in the elastic region, up to the proportional limit.", "It's the basis of every spring constant you've ever used.", "Stress is proportional to strain via Young's modulus.", "Named after the 17th-century English polymath who feuded with Newton."], reveal: "Within the elastic limit, deformation is directly proportional to applied load: σ = Eε. Push past the proportional limit and the relationship breaks down as the material begins to deform permanently instead of springing back." },
  { answer: "Voltage Divider", discipline: "Electrical Engineering", accept: ["voltage divider", "potential divider"], clues: ["One of the first circuits every electronics student builds.", "Two resistors in series, and a voltage tapped off the middle.", "The split is set purely by the ratio of the two resistances.", "Load it with something that draws current and the simple formula stops being exact.", "A circuit of series resistors that produces an output voltage as a fraction of the input, set by resistance ratio."], reveal: "A simple circuit of two or more resistors in series that produces an output voltage equal to a fraction of the input, set purely by the ratio of resistances. The neat formula only holds exactly when nothing downstream draws current — connect a real load and it starts pulling the output away from the ideal value." },
  { answer: "Pascal's Law", discipline: "Fluid Mechanics", accept: ["pascals law", "pascal law"], clues: ["It's the reason a small push can lift a car.", "Pressure applied at one point in a confined fluid doesn't stay local.", "It transmits equally in every direction, undiminished.", "A hydraulic jack multiplies force using exactly this principle.", "Pressure applied to an enclosed fluid is transmitted equally throughout the fluid in all directions."], reveal: "A statement that pressure applied anywhere to a confined, incompressible fluid is transmitted equally and undiminished to every point within it. It's the working principle behind hydraulic jacks and brakes, where a small force on a small piston becomes a much larger force on a larger one." },
  { answer: "Latent Heat", discipline: "Thermodynamics", accept: ["latent heat", "latent heat of fusion", "latent heat of vaporisation", "latent heat of vaporization"], clues: ["Heat that goes in without raising the temperature at all.", "It's absorbed or released during a change of phase, not a change of state within one phase.", "It's why a pot of boiling water stays at 100°C no matter how high you turn the flame.", "Melting and vaporising each require a different amount of it.", "The energy absorbed or released during a phase change at constant temperature."], reveal: "The energy absorbed or released when a substance changes phase — melting, freezing, boiling or condensing — without any change in temperature. It's why boiling water stubbornly stays at 100°C no matter how hard it's heated: every joule going in converts liquid to vapour instead of raising the temperature further." },
  { answer: "Recursion", discipline: "Computer Science", accept: ["recursion"], clues: ["A function that solves a problem by calling a smaller version of itself.", "Without one specific safeguard, it never actually finishes.", "That safeguard is called a base case.", "Each call adds a new frame to the call stack, which is finite.", "A technique where a function calls itself to break a problem into smaller instances of the same problem."], reveal: "A technique in which a function solves a problem by calling itself on a smaller instance of that same problem, until it reaches a base case that stops the chain. Every call adds a new frame to the finite call stack, which is exactly why a recursive function missing its base case eventually crashes with a stack overflow." },
  { answer: "Center of Mass", discipline: "Dynamics", accept: ["center of mass", "centre of mass", "center of gravity", "centre of gravity"], clues: ["A single point that represents where an object's mass seems to concentrate.", "Balance an irregular shape on your fingertip and you've found it by trial and error.", "For a uniform object it coincides with the geometric centre.", "A tightrope walker's pole works by shifting it lower and wider.", "It's the point about which an object's mass is evenly distributed in every direction."], reveal: "The point at which an object's entire mass can be considered concentrated for the purposes of analysing motion or balance. Its location depends only on how mass is distributed, not on the local gravitational field, which is why it's distinct from, though often confused with, centre of gravity." },
  { answer: "Short Circuit", discipline: "Electrical Engineering", accept: ["short circuit", "electrical short"], clues: ["An electrical fault defined by what current isn't doing, not what it is.", "Current takes a path it was never intended to take.", "That unintended path usually offers far less resistance than the intended one.", "The result is often a sudden, dangerous surge in current.", "An unintended low-resistance connection in a circuit that causes excessive current to flow."], reveal: "An unintended, low-resistance path in a circuit that lets current flow somewhere it was never designed to go, bypassing the intended load entirely. Because that unintended path usually offers far less resistance than the circuit was designed for, current can surge dramatically — which is exactly why fuses and circuit breakers exist to cut it off before real damage occurs." },
  { answer: "Doppler Effect", discipline: "Physics", accept: ["doppler effect"], clues: ["A shift you've almost certainly heard, even if you never knew its name.", "An ambulance siren sounds higher-pitched approaching than it does receding.", "The effect applies just as well to light as it does to sound.", "Astronomers use its light-based version to tell whether distant galaxies are approaching or receding.", "The change in observed frequency of a wave caused by relative motion between the source and the observer."], reveal: "The change in observed frequency of a wave caused by relative motion between its source and an observer — compressed and higher-pitched when approaching, stretched and lower-pitched when receding. It applies to any wave, which is why astronomers use its light-based version to measure whether distant galaxies are moving toward us or away." },
  { answer: "Angle of Attack", discipline: "Aerodynamics", accept: ["angle of attack", "aoa"], clues: ["An angle measured between two things, neither of which is the horizon.", "One reference is the wing's chord line; the other is the oncoming airflow.", "Increase it and lift generally increases too — up to a point.", "Push it too far and the flow separates entirely from the upper surface.", "The angle between an airfoil's chord line and the direction of the oncoming relative wind."], reveal: "The angle between an airfoil's chord line and the direction of the oncoming relative wind, one of the primary variables a pilot controls to generate lift. Increase it and lift climbs steadily — until the flow can no longer follow the upper surface and separates abruptly, the moment of aerodynamic stall." },
  { answer: "Application Programming Interface", discipline: "Software Engineering", accept: ["api", "application programming interface"], clues: ["A contract that lets two pieces of software talk without knowing each other's internals.", "It defines what you can ask for, not how the answer gets computed.", "Change what's behind it and, ideally, nothing on the other side even notices.", "A web version of it typically speaks over HTTP, often exchanging JSON.", "A defined set of rules and endpoints that lets separate software components communicate without exposing internal implementation."], reveal: "A defined set of rules, functions or endpoints that lets one piece of software request services or data from another without needing to know how the other side implements them internally. That separation is the whole point — the implementation behind an API can be rewritten entirely, and as long as the interface itself stays the same, nothing on the other side needs to notice." },
  { answer: "Coefficient of Friction", discipline: "Dynamics", accept: ["coefficient of friction", "friction coefficient", "mu"], clues: ["A dimensionless number with the symbol μ.", "It comes in a static value and a slightly smaller kinetic one.", "Multiply it by the normal force and you get the friction force.", "Rubber on dry asphalt gives a much higher value than steel on ice.", "F = μN."], reveal: "A dimensionless ratio relating the friction force between two surfaces to the normal force pressing them together. Static friction is always slightly higher than kinetic, which is why it takes more force to start an object sliding than to keep it sliding." },
  { answer: "Inductor", discipline: "Electrical Engineering", accept: ["inductor", "inductance"], clues: ["A component that stores energy in a magnetic field, not an electric one.", "Usually nothing more exotic than a coil of wire.", "It opposes sudden changes in current through itself.", "Break its current path suddenly and it will fight back with a voltage spike.", "A component storing electrical energy as a magnetic field, opposing changes in the current through it: V = L(dI/dt)."], reveal: "A component, typically a coil of wire, that stores electrical energy as a magnetic field and opposes any sudden change in the current flowing through it. Break that current path abruptly and the collapsing field fights back with a voltage spike, which is exactly the mechanism behind old ignition coils and modern switching power supplies." },
  { answer: "Escape Velocity", discipline: "Aerospace Engineering", accept: ["escape velocity"], clues: ["The speed needed to leave somewhere for good, ignoring any further propulsion.", "It's the point at which kinetic energy exactly cancels gravitational potential energy.", "From Earth's surface, it works out to roughly 11.2 km/s.", "It doesn't depend on the direction you're travelling, only on your distance from the centre of mass.", "The minimum speed needed for an object to break free of a gravitational field without further propulsion."], reveal: "The minimum speed an object needs to break completely free of a gravitational field without any further propulsion, the point at which its kinetic energy exactly cancels the gravitational potential energy holding it back. From Earth's surface that works out to roughly 11.2 km/s — regardless of which direction you're travelling, only distance from the centre of mass matters." },
  { answer: "Lever", discipline: "Statics", accept: ["lever", "simple machine lever"], clues: ["One of the oldest machines ever devised, older than recorded history itself.", "It trades force for distance, or distance for force — never both at once for free.", "A rigid bar pivots around a fixed point.", "Move the pivot closer to the load and less effort is needed to lift it.", "A rigid bar pivoting about a fixed point, used to multiply an applied force."], reveal: "A rigid bar pivoting about a fixed point, or fulcrum, used to multiply an applied force at the cost of moving through a greater distance. Moving the fulcrum closer to the load reduces the effort needed to lift it — the same tradeoff behind everything from a crowbar to a simple seesaw." },
  { answer: "Object-Oriented Programming", discipline: "Software Engineering", accept: ["object oriented programming", "oop"], clues: ["A programming paradigm organised around a particular kind of bundle.", "That bundle packages data together with the functions that operate on it.", "Four pillars are usually taught alongside it: encapsulation, inheritance, polymorphism, abstraction.", "A class is the blueprint; an instance of it is the real thing.", "A programming paradigm organising code around objects that bundle state and behaviour together."], reveal: "A programming paradigm that organises code around objects — bundles combining data and the functions that operate on that data — built from reusable blueprints called classes. It's usually taught alongside four core ideas: encapsulation, inheritance, polymorphism and abstraction, each addressing a different way of managing complexity as software grows." },
  { answer: "Photovoltaic Effect", discipline: "Electrical Engineering", accept: ["photovoltaic effect", "solar cell"], clues: ["An effect that converts one form of energy directly into another, with no moving parts.", "Light striking a specific kind of material knocks electrons loose.", "A built-in electric field then sweeps those freed electrons in one consistent direction.", "It's the working principle behind every solar panel ever made.", "The generation of a voltage or current in a semiconductor material when it's exposed to light."], reveal: "The generation of a voltage when light strikes a semiconductor material, knocking electrons loose and sweeping them in a consistent direction using a built-in electric field at a junction. It converts light directly into electricity with no moving parts at all, and it's the working principle behind every solar panel in existence." },
  { answer: "Wind Turbine", discipline: "Renewable Energy", accept: ["wind turbine"], clues: ["A machine that runs the same basic energy conversion as a windmill, just electrified.", "Its blades are shaped much like an aircraft wing, not a simple flat paddle.", "No design, however good, could ever capture more than about 59% of the wind's energy.", "That theoretical ceiling has a name, after the German physicist who calculated it.", "A machine that converts the kinetic energy of wind into electrical energy via rotating blades and a generator."], reveal: "A machine that converts the kinetic energy of moving air into electrical energy, using blades shaped much like an aircraft wing to spin a generator. No design can ever capture more than about 59% of the wind's available energy — a theoretical ceiling called the Betz limit, set purely by the physics of extracting energy from a moving fluid." },
  { answer: "Pulley System", discipline: "Statics", accept: ["pulley system", "block and tackle", "pulley"], clues: ["A machine built from wheels, grooves, and a single continuous rope.", "A single fixed one only changes the direction of a pull, not its magnitude.", "Add a moving one and suddenly the force required actually drops.", "A block and tackle can stack several together for a dramatic mechanical advantage.", "A system of wheels and rope used to change the direction of a force or multiply it via mechanical advantage."], reveal: "A system of wheels and a continuous rope used to redirect an applied force, and — once a moving pulley is added — to multiply it through mechanical advantage. A block and tackle stacks several pulleys together, letting one person lift a load many times heavier than they could manage unaided." },
  { answer: "Electrical Insulator", discipline: "Electrical Engineering", accept: ["electrical insulator", "insulator"], clues: ["A material chosen specifically for what it refuses to do.", "Its electrons are tightly bound, with essentially nowhere to wander.", "Rubber, glass and most plastics all qualify.", "It's what keeps a live wire from becoming a shock hazard to the touch.", "A material that strongly resists the flow of electric current, due to its tightly bound electrons."], reveal: "A material whose electrons are so tightly bound to their atoms that it strongly resists the flow of electric current, unlike a conductor's free-roaming electrons. Rubber, glass and most plastics all qualify, which is exactly why they're used to coat wires and keep a live conductor from being a shock hazard to the touch." },
  { answer: "Water Treatment", discipline: "Environmental Engineering", accept: ["water treatment", "water treatment plant"], clues: ["A multi-stage process turning something unfit to drink into something safe.", "Large particles settle out first, before anything more sophisticated happens.", "Filtration removes what settling alone leaves behind.", "A final disinfection step, often chlorine, kills off anything still remaining.", "The multi-stage process of removing contaminants from water to make it safe for drinking or discharge."], reveal: "The multi-stage process of removing contaminants from water — typically settling out large particles, filtering the rest, and disinfecting with chlorine or UV light — to make it safe for drinking or environmental discharge. Skipping or under-designing any one stage can leave contaminants that the later stages were never intended to handle alone." },
  { answer: "Non-Newtonian Fluid", discipline: "Fluid Mechanics", accept: ["non newtonian fluid"], clues: ["A fluid that breaks the tidy rule its more famous cousin obeys.", "Its apparent viscosity changes depending on how hard it's sheared.", "A cornstarch-and-water mixture is the classic kitchen demonstration.", "Stir it gently and it flows; punch it and it behaves almost like a solid.", "A fluid whose viscosity depends on the applied shear rate, rather than staying constant."], reveal: "A fluid whose apparent viscosity changes with the rate at which it's sheared, unlike the simple linear behaviour of a Newtonian fluid. A cornstarch-and-water mixture is the classic demonstration — it flows like a liquid when stirred gently, but resists almost like a solid when struck suddenly." },
  { answer: "Skin Effect", discipline: "Electrical Engineering", accept: ["skin effect", "skin depth"], clues: ["It gets worse as frequency rises.", "It makes the effective resistance of a conductor higher than its DC value.", "It's why high-frequency conductors are sometimes hollow or specially stranded.", "Litz wire exists to defeat it.", "Current crowds toward the outer surface of the conductor."], reveal: "The tendency of alternating current to concentrate near a conductor's surface, raising effective resistance with frequency. At high enough frequencies current barely penetrates the core at all, which is why RF conductors are sometimes hollow or stranded as fine Litz wire." },
  { answer: "Laplace Transform", discipline: "Control Systems", accept: ["laplace transform", "laplace"], clues: ["It turns calculus into algebra.", "Differentiation becomes multiplication by a variable.", "Its variable is complex, usually written s.", "Transfer functions live in the domain it creates.", "Named after a French mathematician and astronomer."], reveal: "An integral transform mapping time-domain differential equations into algebraic equations in the complex s-domain. Differentiation in time becomes simple multiplication by s, which is exactly what makes transfer functions and block-diagram algebra possible." },
  { answer: "Adiabatic Process", discipline: "Thermodynamics", accept: ["adiabatic process", "adiabatic"], clues: ["A process with one specific thing forbidden from crossing its boundary.", "That forbidden thing is heat, not work.", "Compress a gas fast enough and it behaves almost exactly like this.", "A bicycle pump gets warm to the touch because of it.", "A process in which no heat is transferred into or out of the system."], reveal: "A process in which the system exchanges no heat with its surroundings, whether because it's well insulated or simply happens too fast for heat to transfer. A bicycle pump warming up as you compress it is adiabatic compression in action — the work done on the gas goes entirely into raising its internal energy." },
  { answer: "Moment Distribution Method", discipline: "Structural Engineering", accept: ["moment distribution method", "moment distribution", "hardy cross method"], clues: ["A hand-calculation technique from an era before computers did the work.", "It solves an indeterminate frame by an iterative process of balancing.", "Fixed-end moments get released a joint at a time and redistributed.", "Each iteration gets you closer to the true answer, without ever solving simultaneous equations directly.", "Developed by Hardy Cross in 1930 to analyse indeterminate beams and frames without solving simultaneous equations."], reveal: "An iterative hand-calculation method, developed by Hardy Cross in 1930, that solves indeterminate beams and frames by repeatedly balancing and redistributing moments at each joint until the structure converges toward equilibrium. It let engineers analyse complex frames accurately decades before computers made direct matrix solutions routine." },
  { answer: "Newtonian Fluid", discipline: "Fluid Mechanics", accept: ["newtonian fluid"], clues: ["The 'well-behaved' category that most basic fluid mechanics assumes.", "Its viscosity doesn't care how hard you're shearing it.", "Water and air both belong to this tidy category.", "Its stress-strain-rate relationship is a simple straight line through the origin.", "A fluid whose shear stress is directly proportional to shear rate, with constant viscosity."], reveal: "A fluid whose shear stress is directly proportional to the rate of shear, with a viscosity that stays constant no matter how fast or slow it's deformed. Water and air are both classic examples, which is why most introductory fluid mechanics gets to assume this simple, linear behaviour." },
  { answer: "LC Resonant Circuit", discipline: "Electrical Engineering", accept: ["lc resonant circuit", "lc circuit", "lc resonance", "tank circuit"], clues: ["Two energy-storing components, taking turns.", "Energy sloshes back and forth between a magnetic field and an electric field.", "Left undriven and lossless, it would oscillate forever at one specific frequency.", "Radio tuners once relied entirely on one to select a station.", "f = 1/(2π√LC) — the natural resonant frequency of an inductor and capacitor connected together."], reveal: "A circuit built from an inductor and a capacitor together, in which energy oscillates back and forth between the inductor's magnetic field and the capacitor's electric field at a natural resonant frequency. In an ideal, lossless circuit that oscillation would continue forever; real circuits always have some resistance that eventually damps it out." },
  { answer: "Phase Margin", discipline: "Control Systems", accept: ["phase margin"], clues: ["Gain margin's partner, measuring a different kind of safety buffer.", "It's measured at the frequency where gain has dropped to exactly 0 dB.", "It quantifies how much extra phase lag the loop could absorb before going unstable.", "A healthy design usually targets somewhere around 45 to 60 degrees of it.", "The amount of additional phase lag, at the gain crossover frequency, that would push a stable system to instability."], reveal: "The amount of additional phase lag, measured at the frequency where open-loop gain crosses 0 dB, that a stable feedback system could absorb before being pushed to instability. Together with gain margin it forms the standard pair of frequency-domain stability checks, with designers typically targeting 45–60 degrees for a well-damped response." },
  { answer: "Entropy", discipline: "Thermodynamics", accept: ["entropy"], clues: ["A measure that quantifies disorder, though 'disorder' undersells it.", "It never decreases for an isolated system, only stays the same or grows.", "A reversible process leaves it unchanged; a real one always creates more.", "It's what makes some processes only run one way in time.", "A thermodynamic property measuring the unavailability of a system's energy to do useful work."], reveal: "A thermodynamic property quantifying how much of a system's energy is no longer available to do useful work, often loosely described as a measure of disorder. Every real, irreversible process generates additional entropy, which is why energy inevitably degrades in quality even though the total amount is always conserved." },
  { answer: "Slenderness Ratio", discipline: "Structural Engineering", accept: ["slenderness ratio"], clues: ["A single number that decides whether a column will crush or buckle.", "It compares a column's length against a property of its cross-section.", "A high value means buckling governs; a low value means crushing does.", "It's the effective length divided by the radius of gyration.", "KL/r — the ratio that determines whether Euler buckling or material yielding controls a column's failure."], reveal: "The ratio of a column's effective length to the radius of gyration of its cross-section, which determines whether it fails by Euler buckling or by simply crushing under compressive stress. Long, thin columns with a high slenderness ratio buckle well before the material itself would ever yield." },
  { answer: "Reynolds Number", discipline: "Fluid Mechanics", accept: ["reynolds number", "reynolds"], clues: ["A dimensionless group — no units at all.", "It compares two competing forces inside a flow.", "Below roughly 2300 in a pipe you get one regime; above 4000, another entirely.", "It is the ratio of inertial to viscous forces.", "Named after the British engineer who ran the famous dye-in-a-pipe experiment."], reveal: "Re = ρVL/μ — the ratio of inertial to viscous forces, predicting laminar versus turbulent flow. A low value means viscosity dominates and the flow stays smooth; a high value means inertia wins and the flow tends toward chaotic mixing." },
  { answer: "Norton's Theorem", discipline: "Electrical Engineering", accept: ["nortons theorem", "norton equivalent", "norton"], clues: ["Thévenin's theorem has a mirror-image twin, and this is it.", "It replaces a whole network with just two components instead of many.", "Where Thévenin uses a voltage source, this one uses a current source.", "The two are related by a single, simple conversion formula.", "Any linear two-terminal network can be replaced by a current source in parallel with a resistance."], reveal: "Any linear two-terminal network can be reduced to a single current source in parallel with a resistance, mirroring Thévenin's voltage-source-plus-series-resistance equivalent. The two representations are always interchangeable via a simple source transformation, and the resistance value is identical in both." },
  { answer: "Overshoot", discipline: "Control Systems", accept: ["overshoot", "percent overshoot", "peak overshoot"], clues: ["A step response's tendency to go too far before coming back.", "It's reported as a percentage above the final steady-state value.", "A more heavily damped system shows less of it, or none at all.", "Push a controller's gain too high and it tends to grow.", "The amount by which a system's step response exceeds its final steady-state value before settling."], reveal: "The amount by which a system's response peaks above its final steady-state value before settling back down, usually reported as a percentage of that final value. It's closely tied to damping ratio — an underdamped system overshoots noticeably, and pushing controller gain higher tends to make the overshoot grow further still." },
  { answer: "Isentropic Process", discipline: "Thermodynamics", accept: ["isentropic process", "isentropic"], clues: ["An idealisation that's both adiabatic and something else at once.", "That second condition is reversibility.", "No real process ever quite achieves it — friction and turbulence see to that.", "Turbine and compressor efficiency are both measured against this ideal baseline.", "A reversible adiabatic process, along which entropy stays exactly constant."], reveal: "A reversible, adiabatic process along which entropy stays exactly constant — the idealised, frictionless limit that no real machine ever quite reaches. Turbine and compressor efficiencies are defined by comparing actual performance against this ideal isentropic baseline." },
  { answer: "Creep", discipline: "Materials", accept: ["creep", "creep deformation"], clues: ["It happens under a constant load, given enough time.", "It matters above roughly 0.4 of the melting temperature.", "Its curve has primary, secondary and tertiary stages.", "It's the life-limiting mechanism for turbine blades.", "Time-dependent plastic deformation below the yield stress."], reveal: "Slow, time-dependent plastic deformation of a material under sustained stress, accelerated by temperature. It becomes significant above roughly 0.4 of a material's absolute melting temperature — exactly the regime turbine blades operate in." },
  { answer: "Viscosity", discipline: "Fluid Mechanics", accept: ["viscosity"], clues: ["A fluid's internal resistance to being deformed or sheared.", "Honey has plenty of it; water has comparatively little.", "It generally drops as a liquid warms up, and rises as a gas warms up.", "It's the μ that shows up throughout the Navier-Stokes equations.", "A measure of a fluid's resistance to flow, relating shear stress to shear rate."], reveal: "A measure of a fluid's internal resistance to flow, relating the shear stress within it to the rate at which it's being sheared. Curiously, it works in opposite directions with temperature — liquids thin out as they warm, while gases thicken slightly, because their viscosity comes from different molecular mechanisms." },
  { answer: "RMS Voltage", discipline: "Electrical Engineering", accept: ["rms voltage", "root mean square voltage", "rms"], clues: ["The number on an AC voltmeter isn't the peak — it's this.", "It's the value that would deliver the same heating power as an equivalent DC source.", "For a sine wave, it's the peak divided by root two.", "Household mains being quoted as 120V or 230V refers to this value, not the peak.", "The square root of the average of the squared instantaneous voltage over one cycle."], reveal: "The effective value of an AC voltage — the square root of the average of the squared instantaneous voltage over a full cycle — chosen because it delivers the same heating power as a DC voltage of the same numerical value. Household mains ratings like 120V or 230V are always this RMS figure, not the higher instantaneous peak." },
  { answer: "Ziegler-Nichols Method", discipline: "Control Systems", accept: ["ziegler nichols method", "ziegler nichols tuning", "ziegler nichols"], clues: ["A recipe for tuning a controller without needing a full mathematical model first.", "It starts by pushing the system to the very edge of instability, deliberately.", "From that edge, you read off one gain value and one oscillation period.", "Simple formulas then convert those two numbers into PID gains.", "A classic empirical method for tuning PID controller gains from a system's ultimate gain and oscillation period."], reveal: "A classic empirical method for tuning PID controller gains, starting by increasing proportional gain until the closed loop oscillates continuously at its 'ultimate' gain and period, then converting those two measured values into PID gains through simple published formulas. It gets a working controller running quickly without needing a full mathematical model of the plant." },
  { answer: "Neutral Axis", discipline: "Structural Engineering", accept: ["neutral axis", "neutral plane"], clues: ["A line where nothing much happens.", "On one side of it fibres stretch; on the other they compress.", "For a symmetric elastic section it passes through the centroid.", "For reinforced concrete its position shifts as the section cracks.", "It's where bending stress is zero."], reveal: "The line in a bent section where longitudinal stress and strain are zero, separating tension from compression. For a symmetric elastic cross-section it sits at the centroid, but in reinforced concrete its position shifts once the section starts to crack." },
  { answer: "Venturi Effect", discipline: "Fluid Mechanics", accept: ["venturi effect", "venturi", "venturi meter"], clues: ["It relies on a deliberate constriction.", "It's a direct consequence of continuity plus Bernoulli.", "It's used to measure flow rate without any moving parts.", "It's how a paint sprayer and an aspirator draw fluid.", "Named after an 18th-century Italian physicist."], reveal: "The pressure drop that occurs when a fluid accelerates through a constricted section of pipe. It's a direct consequence of pairing continuity with Bernoulli's principle, exploited whenever a device needs to draw in fluid with no moving parts at all." },
  { answer: "Resistor", discipline: "Electronics", accept: ["resistor"], clues: ["A component whose value is often readable from a series of colored bands, not printed digits.", "Its entire job is to oppose current by a known, fixed amount.", "Pair it with Ohm's Law and you can predict exactly how it'll behave in a circuit.", "It protects an LED from drawing more current than the LED can survive.", "The basic electronic component that limits current flow by a fixed amount, often marked with colored bands."], reveal: "A basic electronic component that provides a fixed, known opposition to current flow, most often identified by a series of colored bands printed on its body rather than a numeric label. It's the component that keeps an LED from burning itself out." },
  { answer: "Triple Point", discipline: "Thermodynamics", accept: ["triple point"], clues: ["A single, very specific combination of conditions on a phase diagram.", "Solid, liquid and gas coexist there simultaneously, in equilibrium.", "Water's version sits at a famously precise 0.01°C.", "It's so reproducible that it once anchored the definition of the kelvin.", "The unique temperature and pressure at which three phases of a substance coexist in equilibrium."], reveal: "The single, precise temperature and pressure at which a substance's solid, liquid and vapour phases all coexist simultaneously in equilibrium. Water's triple point is so exactly reproducible — at 0.01°C and a fixed pressure — that it was used for decades to formally define the kelvin." },
  { answer: "Ball Bearing", discipline: "Mechanical Design", accept: ["ball bearing", "bearing"], clues: ["A component that replaces one kind of friction with a much smaller kind.", "Small hardened spheres roll between two rings, carrying the load between them.", "A cage keeps them evenly spaced so they never grind against each other.", "Skateboard wheels spin as freely and long as they do largely because of one inside each wheel.", "The component with rolling spheres between two rings that lets a shaft spin with minimal friction."], reveal: "A component with hardened steel spheres rolling between an inner and outer ring, replacing high-friction sliding contact with much lower rolling friction, letting a shaft spin smoothly under load." },
  { answer: "Screwdriver", discipline: "Manufacturing", accept: ["screwdriver", "flathead screwdriver", "phillips screwdriver"], clues: ["A hand tool defined entirely by the shape it needs to fit.", "Its tip comes in two dominant shapes, one flat and one cross-shaped.", "Using the wrong size on a stripped head is a classic workshop frustration.", "It turns a fastener by converting your wrist's rotation into torque on the slot.", "The everyday tool you reach for to drive a screw in or out."], reveal: "A hand tool with a shaped tip — commonly flat-blade or cross-head — that engages the matching slot in a screw to turn it. Match the tip to the screw or you risk stripping either one." },
  { answer: "Young's Modulus", discipline: "Materials", accept: ["youngs modulus", "elastic modulus", "modulus of elasticity"], clues: ["A material property, not a structural one — it doesn't depend on shape.", "It's the slope of the straight part of a stress-strain curve.", "Steel's value is roughly three times that of aluminium.", "Rubber sits near the bottom of the scale; diamond near the top.", "It's the constant of proportionality in Hooke's law: σ = Eε."], reveal: "A measure of a material's stiffness — how much stress is required to produce a given elastic strain. It's an intrinsic material property independent of the part's geometry, which is why a steel rod and a steel I-beam share the same Young's modulus despite behaving very differently under load." },
  { answer: "Amdahl's Law", discipline: "Computer Engineering", accept: ["amdahls law", "amdahl law", "amdahl"], clues: ["A sobering law about diminishing returns.", "It applies when you throw more hardware at a problem.", "The serial fraction of the work sets a hard ceiling.", "Even with infinite processors, speedup converges to a finite number.", "Named after the architect of the IBM System/360."], reveal: "Speedup from parallelisation is limited by the fraction of a task that must remain sequential. Even with an infinite number of processors, a task that's 10% inherently sequential can never speed up by more than a factor of ten." },
  { answer: "Wind Load", discipline: "Structural Engineering", accept: ["wind load", "wind loading"], clues: ["A load that pushes sideways as often as it pushes down.", "It can also pull upward on a roof, not just push against a wall.", "It scales with the square of wind speed, not linearly.", "Tall, slender buildings are checked for how it makes them sway, not just how it stresses them.", "The lateral and uplift forces a structure must resist due to wind pressure on its surfaces."], reveal: "The lateral and, on roofs, uplift forces a structure must be designed to resist from wind pressure acting on its exposed surfaces. Because that pressure scales with the square of wind speed, it grows dramatically in a storm, and for tall, slender buildings the resulting sway can matter as much as the raw stress it induces." },
  { answer: "Kirchhoff's Current Law", discipline: "Electrical Engineering", accept: ["kirchhoffs current law", "kcl", "kirchhoffs first law"], clues: ["One of two laws by the same person that underpin all circuit analysis.", "It is really conservation of charge in disguise.", "It applies at a node, not around a loop.", "What flows in must flow out; the algebraic sum is zero.", "Abbreviated with three letters, the middle one being C."], reveal: "The algebraic sum of currents entering and leaving any node in a circuit is zero. It holds regardless of what sits at the node — resistors, sources or plain wire — simply because charge has nowhere else to go." },
  { answer: "Hydrostatic Pressure", discipline: "Fluid Mechanics", accept: ["hydrostatic pressure", "hydrostatics"], clues: ["Pressure that exists even when nothing is moving at all.", "It builds with depth, not with distance sideways.", "Your ears feel it increase as you dive to the bottom of a pool.", "A dam has to be built thicker at the base for exactly this reason.", "P = ρgh — pressure increases linearly with depth in a static fluid."], reveal: "The pressure exerted by a fluid at rest, which increases linearly with depth due to the weight of fluid above. It's why a dam must be built far thicker at its base than at its crest — the pressure the structure has to resist is far greater down at the bottom." },
  { answer: "Transfer Function", discipline: "Control Systems", accept: ["transfer function"], clues: ["A single expression that captures how a whole system responds.", "It's a ratio, taken in the Laplace domain.", "Output divided by input, with all initial conditions assumed zero.", "Its poles tell you almost everything about stability.", "G(s) = Output(s)/Input(s) — the s-domain ratio describing a linear system's input-output behaviour."], reveal: "The ratio of a linear system's output to its input in the Laplace domain, assuming zero initial conditions, condensing an entire differential equation into a single algebraic expression. Where its poles sit in the complex plane determines almost everything about the system's stability and dynamic response." },
  { answer: "Strain Gauge", discipline: "Instrumentation", accept: ["strain gauge", "strain gage"], clues: ["A thin foil pattern bonded to a surface.", "Stretch it and its electrical resistance changes.", "Its sensitivity is quoted as a gauge factor, typically around 2.", "You usually need temperature compensation and a bridge circuit to read it.", "It's the sensing element inside almost every load cell."], reveal: "A sensor whose resistance changes with mechanical deformation, used to measure strain and hence stress or load. The resistance change is tiny, so it's almost always read through a Wheatstone bridge to turn microscopic strain into a usable voltage." },
  { answer: "Dial Indicator", discipline: "Metrology", accept: ["dial indicator", "dial gauge"], clues: ["An instrument that turns a tiny linear motion into an easily readable rotation of a needle.", "Its plunger, pressed against a surface, moves a needle around a dial as the surface shifts.", "Machinists use it to check whether a rotating part is running perfectly true.", "It can detect a deviation far too small for the naked eye to ever notice.", "The precision instrument with a needle and dial used to measure tiny linear displacements."], reveal: "A precision measuring instrument that converts a tiny linear movement of its plunger into a magnified, easily read rotation of a needle on a dial — sensitive enough to catch deviations invisible to the naked eye, like a shaft running slightly out of true." },
  { answer: "Boiling Point", discipline: "Chemistry", accept: ["boiling point"], clues: ["A temperature that isn't fixed — it shifts with the surrounding pressure.", "Climb a tall mountain and this temperature for water actually drops.", "It's the temperature at which a liquid's vapor pressure matches the pressure around it.", "For water at sea level, everyone learns it's 100°C.", "The temperature at which a liquid turns to vapor throughout its whole volume, not just at the surface."], reveal: "The temperature at which a liquid's vapor pressure equals the surrounding pressure, so it turns to vapor throughout its volume rather than just evaporating at the surface. Lower the surrounding pressure — like at altitude — and it drops." },
  { answer: "Overfitting", discipline: "Machine Learning", accept: ["overfitting"], clues: ["A model's tendency to memorise instead of actually learn.", "It performs beautifully on data it's already seen, and poorly on data it hasn't.", "It often shows up as a model that's grown needlessly complex for the problem at hand.", "Regularisation and more training data are two classic countermeasures.", "A model fitting training data so closely, including its noise, that it fails to generalise to new data."], reveal: "The failure mode where a model fits its training data so closely — including the noise and quirks specific to that data — that it fails to generalise to new, unseen examples. It's usually a sign the model has grown needlessly complex for the underlying problem, which is exactly what regularisation and more training data both work to counteract." },
  { answer: "Antenna", discipline: "Electromagnetics", accept: ["antenna", "aerial"], clues: ["A component that converts between two forms of energy: electrical signals and radio waves.", "Its physical length is often tuned to match the wavelength it's meant to send or receive.", "Cut a car's roof-mounted one off, and reception noticeably suffers.", "Every radio, phone, and Wi-Fi router relies on one, even if it's hidden inside the case.", "The device that converts electrical signals into radio waves, or radio waves back into electrical signals."], reveal: "A device that converts an electrical signal into radio waves for transmission, or radio waves back into an electrical signal on reception. Its physical length is typically tuned to the wavelength of the signal it's built to handle." },
  { answer: "Fourier's Law of Heat Conduction", discipline: "Heat Transfer", accept: ["fouriers law", "fourier law", "fouriers law of heat conduction", "law of heat conduction"], clues: ["Same mathematical shape as Fick's and Ohm's laws.", "Flux is proportional to a gradient, with a minus sign.", "The constant of proportionality is a material property in W/mK.", "Heat flows down the gradient, never up it unaided.", "The gradient here is temperature."], reveal: "q = −k dT/dx — conductive heat flux is proportional to the negative temperature gradient. It has the exact same mathematical shape as Ohm's law and Fick's law, and it's the starting point for essentially every steady-state conduction problem in engineering." },
  { answer: "Denavit-Hartenberg Parameters", discipline: "Robotics", accept: ["denavit hartenberg parameters", "denavit hartenberg", "dh parameters"], clues: ["A standardised way of describing something that could otherwise be described a dozen different ways.", "It reduces the geometry of a robotic link to exactly four numbers.", "Every serial-link robot arm can be fully described using a table built from it.", "It was introduced in a 1955 paper by two mechanical engineers.", "A standardised convention using four parameters per joint to systematically describe a robot arm's link geometry."], reveal: "A standardised convention, introduced in a 1955 paper, that reduces the geometry of each link in a serial robot arm to exactly four parameters. Building a table of these parameters for every joint gives a completely systematic, unambiguous way to describe — and compute the kinematics of — a robot arm of essentially any configuration." },
  { answer: "Pile Foundation", discipline: "Geotechnical Engineering", accept: ["pile foundation", "piling", "deep foundation"], clues: ["A foundation type used when the ground right underneath a structure simply isn't good enough.", "It transfers load down to stronger soil or rock, far below the surface.", "It carries load two ways at once: friction along its length, and bearing at its tip.", "Driven, bored and screw varieties are all common installation methods.", "A deep foundation that transfers structural load down to stronger soil or rock through friction and end bearing."], reveal: "A deep foundation, driven or bored down through weak surface soil, that transfers structural load to stronger soil or rock far below through a combination of skin friction along its length and end bearing at its tip. It's the go-to solution whenever the soil directly beneath a structure simply isn't strong enough to support a shallow footing." },
  { answer: "Pliers", discipline: "Manufacturing", accept: ["pliers", "plyers"], clues: ["A hinged hand tool built around a simple lever at its pivot.", "One jaw squeezes against the other when you close your grip.", "Some variants add a wire-cutting edge near the pivot.", "You reach for a pair, never a single one — the name is always plural.", "The hand tool you grip and squeeze to hold, bend or pull small objects."], reveal: "A hinged hand tool that multiplies grip force at its jaws through leverage about a central pivot. Different jaw shapes trade off grip, cutting, and reach for different jobs — needle-nose for tight spots, slip-joint for adjustable width." },
  { answer: "Frequency Modulation", discipline: "Signal Processing", accept: ["frequency modulation", "fm"], clues: ["The rival scheme to a simpler, older modulation method.", "Here, the carrier's amplitude stays fixed the entire time.", "Instead, the information is encoded in how the carrier's frequency wanders.", "It's considerably more resistant to noise, which mostly just adds amplitude, not frequency shift.", "A modulation scheme where a signal is encoded by varying the frequency of a constant-amplitude carrier wave."], reveal: "A modulation scheme that encodes a signal by varying the frequency of a carrier wave while keeping its amplitude constant. Because most noise sources mainly disturb amplitude rather than frequency, this scheme is considerably more resistant to interference than amplitude modulation — exactly why FM radio sounds so much cleaner than AM." },
  { answer: "Magnus Effect", discipline: "Aerodynamics", accept: ["magnus effect", "magnus"], clues: ["Every sports commentator has described it without naming it.", "It requires both translation and rotation.", "It's why a topspin tennis ball dives and a curveball curves.", "Flettner built ships with spinning cylinders to exploit it.", "Spin creates a pressure difference and hence a side force."], reveal: "The lateral force generated on a spinning body moving through a fluid. Spin drags the surrounding fluid around with it, speeding flow on one side and slowing it on the other, which is why a topspin ball dives and a curveball curves." },
  { answer: "Reverse Osmosis", discipline: "Chemical Engineering", accept: ["reverse osmosis", "ro"], clues: ["A separation process that runs directly against a natural tendency.", "It forces a solvent through a membrane from the concentrated side to the dilute side.", "That's backward from how osmosis would normally proceed on its own.", "High pressure is what makes it happen against the natural gradient.", "A separation process using pressure to force solvent through a semi-permeable membrane, against the natural osmotic gradient."], reveal: "A separation process that uses applied pressure to force solvent through a semi-permeable membrane from the concentrated side to the dilute side — the reverse of how osmosis would proceed naturally on its own. It's the working principle behind most modern desalination and water purification, filtering out salts and contaminants that can't pass through the membrane." },
  { answer: "Velocity", discipline: "Dynamics", accept: ["velocity"], clues: ["A quantity that includes information a simple speedometer reading leaves out entirely.", "It's speed with a direction attached, making it a vector rather than just a number.", "Two cars going the same speed in opposite directions have different values of this.", "It's the rate of change of position with respect to time.", "Speed in a specific direction — how fast something is moving and which way."], reveal: "Speed combined with a direction, making it a vector rather than a plain number. Two cars traveling at the same speed but opposite directions have identical speeds but opposite values of this." },
  { answer: "Ultrasonic Distance Sensor", discipline: "Sensors", accept: ["ultrasonic distance sensor", "ultrasonic sensor"], clues: ["A ranging sensor working entirely above the range of human hearing.", "It measures distance the same basic way a bat does.", "A short pulse is sent out, and the sensor waits for its echo to return.", "Distance comes from multiplying that time delay by the speed of sound and halving the result.", "A sensor that measures distance by timing how long a high-frequency sound pulse takes to echo back."], reveal: "A sensor that measures distance by emitting a short pulse of sound above the range of human hearing and timing how long its echo takes to return, the same basic principle a bat uses to navigate in the dark. Multiplying that round-trip time by the speed of sound and halving it gives the distance to whatever reflected the pulse." },
  { answer: "Multiplexer", discipline: "Digital Logic", accept: ["multiplexer", "mux"], clues: ["A digital switch with many inputs but only one output.", "Select lines decide which input actually gets through.", "It's the hardware equivalent of an if-else chain.", "Its opposite, a demultiplexer, does the reverse job.", "A circuit that selects one of several input signals and forwards it to a single output, based on select lines."], reveal: "A circuit that selects one of several input signals, based on the value of its select lines, and routes it through to a single output. It's effectively an if-else chain built in hardware, and its mirror-image counterpart, the demultiplexer, routes one input out to one of several outputs instead." },
  { answer: "Six Sigma", discipline: "Quality Engineering", accept: ["six sigma"], clues: ["A quality methodology named after a statistical measure of spread.", "Its goal, in its purest form, is fewer than 3.4 defects per million opportunities.", "DMAIC is the five-letter acronym structuring most of its projects.", "Practitioners earn martial-arts-style belts as they progress through it.", "A data-driven methodology aiming to reduce process variation and defects to near-zero levels."], reveal: "A data-driven quality methodology aiming to reduce process variation until defects fall to near-zero levels — in its strictest definition, fewer than 3.4 per million opportunities. Projects typically follow the five-phase DMAIC structure — Define, Measure, Analyse, Improve, Control — with practitioners earning martial-arts-style belts as they advance." },
  { answer: "Retaining Wall", discipline: "Civil Engineering", accept: ["retaining wall"], clues: ["Its whole job is to hold something back from moving forward.", "It resists lateral earth pressure, not just vertical weight.", "Drainage behind it matters as much as the wall's own strength.", "Gravity, cantilever and anchored are all named varieties of it.", "A structure designed to hold back soil at an elevation change greater than the soil's natural angle of repose."], reveal: "A structure built to hold back soil at a slope steeper than the soil could naturally sustain on its own, resisting the lateral earth pressure pushing against it. Drainage behind the wall matters as much as its structural strength, since water building up in the retained soil can add pressure the wall was never designed to resist." },
  { answer: "O-Ring", discipline: "Fluid Machinery", accept: ["o-ring", "o ring"], clues: ["A seal shaped like a simple donut, doing a surprisingly critical job for something so simple.", "Squeezed into a groove between two mating parts, it deforms slightly to block a leak.", "A failure of one, on a cold morning in 1986, was implicated in the Challenger disaster.", "It seals equally well whether the pressure inside is pushing outward or being drawn inward.", "The donut-shaped rubber seal, compressed into a groove, used to prevent leaks between two mating parts."], reveal: "A donut-shaped elastomer seal, compressed into a groove between two mating parts to block a leak. A single failed one, stiffened by cold temperatures, was a key factor in the 1986 Space Shuttle Challenger disaster." },
  { answer: "Battery", discipline: "Electrical Power", accept: ["battery"], clues: ["A device that stores energy chemically, then releases it as electricity on demand.", "Inside, a chemical reaction at two different electrodes drives electrons around an external circuit.", "Some versions can be recharged by driving that internal chemical reaction backwards.", "Flip it around backwards in a device and, usually, nothing works.", "The device that stores chemical energy and converts it to electrical energy on demand."], reveal: "A device that stores energy chemically and releases it as electric current on demand, via a reaction between two different electrode materials. Rechargeable versions simply run that chemical reaction in reverse to restore the stored charge." },
  { answer: "Stress Concentration Factor", discipline: "Solid Mechanics", accept: ["stress concentration", "kt", "stress raiser"], clues: ["It explains why parts break at holes, fillets and sharp corners.", "It's why you drill a hole at the tip of a crack to arrest it.", "Peterson wrote the standard chart book for it.", "For a circular hole in a wide plate, its value is three.", "It multiplies nominal stress to give local peak stress."], reveal: "K_t — the ratio of peak local stress at a geometric discontinuity to the nominal applied stress. A sharp corner or small hole can multiply local stress several times over, which is exactly why fillets are rounded and crack tips are sometimes deliberately drilled." },
  { answer: "Pacemaker", discipline: "Biomedical Engineering", accept: ["pacemaker", "cardiac pacemaker"], clues: ["A device that steps in when a natural rhythm becomes unreliable.", "It delivers small, precisely timed electrical pulses.", "Those pulses target one specific organ's own natural pacing system.", "Modern versions can sense the heart's own activity and only fire when actually needed.", "A medical device delivering electrical impulses to regulate an abnormal or unreliable heart rhythm."], reveal: "A medical device that delivers small, precisely timed electrical impulses to regulate a heart rhythm that's become too slow or irregular on its own. Modern versions sense the heart's natural electrical activity continuously and only fire a pulse when one is actually needed, rather than pacing constantly regardless of the heart's own rhythm." },
  { answer: "Pulse Width Modulation", discipline: "Electronics", accept: ["pulse width modulation", "pwm"], clues: ["The output is only ever fully on or fully off.", "That's precisely why it's so efficient — no linear dissipation.", "The duty cycle carries the information.", "It's how you dim an LED and drive a motor from a microcontroller.", "Three letters, ending in M."], reveal: "Encoding an analogue level as the duty cycle of a fixed-frequency switching waveform. Because the output is always fully on or fully off, almost no power is wasted as heat in the switch, which is what makes it so efficient for dimming LEDs and driving motors." },
  { answer: "Injection Molding", discipline: "Manufacturing", accept: ["injection molding", "injection moulding"], clues: ["A process built to make thousands, or millions, of identical parts cheaply.", "Molten material is forced under high pressure into a precisely machined cavity.", "The tooling cost upfront is steep; the cost per part afterward is tiny.", "Plastic is the most common material, though metal versions exist too.", "A manufacturing process that forces molten material into a mold cavity under pressure to form parts."], reveal: "A manufacturing process that forces molten material — most often plastic — into a precisely machined mold cavity under high pressure, where it cools and solidifies into the finished part shape. The upfront tooling cost is substantial, but once that mold exists, the cost of each additional part is remarkably small, which is exactly why it dominates high-volume production." },
  { answer: "Ablative Heat Shield", discipline: "Aerospace Engineering", accept: ["ablative heat shield", "ablative shielding", "ablation"], clues: ["A heat shield engineered to fail, gradually and on purpose.", "It protects a spacecraft during one of the most punishing parts of a mission.", "Its outer material chars and vaporises, carrying heat away as it goes.", "It gets thinner throughout re-entry, by design, not by accident.", "A thermal protection method that sacrificially burns away material to carry heat away from a spacecraft during re-entry."], reveal: "A thermal protection method in which a spacecraft's outer material is deliberately allowed to char and vaporise during atmospheric re-entry, carrying enormous heat away with it as it burns off. It gets measurably thinner over the course of re-entry by design — a sacrificial shield engineered to fail exactly the way it's supposed to." },
  { answer: "Hash Function", discipline: "Computer Science", accept: ["hash function", "cryptographic hash function", "hashing"], clues: ["It takes input of any size and always hands back output of one fixed size.", "The tiniest change to the input scrambles the output completely.", "A good one makes it computationally infeasible to reverse the process.", "It's how a password can be checked without ever being stored in plain text.", "A function mapping input of arbitrary size to a fixed-size output, ideally unique and non-reversible."], reveal: "A function that maps input of any size down to a fixed-size output, designed so even the tiniest change in input scrambles the result completely and unpredictably. A good cryptographic hash is computationally infeasible to reverse, which is exactly why systems can verify a password by hashing it and comparing, without ever storing the original in plain text." },
  { answer: "Bolt Preload", discipline: "Mechanical Design", accept: ["bolt preload", "bolt tension", "fastener preload", "preload"], clues: ["It exists in a joint before any external load is even applied.", "Get it too low and the joint can separate under vibration.", "Get it too high and the fastener can yield before it's even in service.", "A torque wrench is a crude way of controlling it.", "The tension deliberately built into a bolt when it's tightened, clamping the joint together."], reveal: "The tension deliberately built into a fastener by tightening it, which clamps the joint members together before any external load is applied. Too little and the joint can separate or work loose under vibration; too much and the bolt can yield during assembly, before the structure ever sees service." },
  { answer: "Fuse", discipline: "Electrical Engineering", accept: ["fuse"], clues: ["A safety device engineered to fail on purpose, before something else does.", "A thin internal wire is sized to melt at a specific current.", "Once it's done its job, it can't be reset — only replaced.", "It protects a circuit by sacrificing itself before the wiring overheats.", "The safety device with a thin wire that melts to break a circuit when current gets too high."], reveal: "A safety device containing a thin conductor sized to melt and break the circuit once current exceeds a set threshold, protecting the wiring and components behind it. Unlike a circuit breaker, once it blows it must be replaced, not reset." },
  { answer: "Refraction", discipline: "Optics", accept: ["refraction"], clues: ["A bending of direction that only happens when light crosses into a new medium.", "It happens because light's speed changes as it moves from one material into another.", "It's why a straw in a glass of water looks visibly bent at the surface.", "Lenses in eyeglasses and cameras rely entirely on this effect to focus light.", "The bending of light as it passes from one transparent medium into another."], reveal: "The bending of light as it crosses from one transparent medium into another, caused by light changing speed at the boundary. It's why a straw looks bent at the waterline, and the entire operating principle behind every lens." },
  { answer: "Von Mises Yield Criterion", discipline: "Materials", accept: ["von mises", "von mises stress", "vonmises", "mises"], clues: ["Every FEA colour plot you've ever shown a manager uses it.", "It reduces a full 3D stress state to a single scalar number.", "It's based on distortion energy, not hydrostatic pressure.", "Ductile metals under pure hydrostatic compression won't fail by it.", "Compare that scalar against yield strength and you have your safety factor."], reveal: "A ductile-failure criterion: yielding begins when distortion energy reaches the level seen at yield in uniaxial tension. By ignoring hydrostatic stress and focusing purely on shape-changing energy, it matches how ductile metals actually fail far better than a simple maximum-stress rule." },
  { answer: "Nuclear Fission", discipline: "Nuclear Engineering", accept: ["nuclear fission", "fission"], clues: ["A process that splits something apart to release energy, rather than joining things together.", "A heavy atomic nucleus breaks into two lighter ones.", "A stray neutron is usually what triggers it.", "Each split releases more neutrons, capable of triggering further splits.", "The splitting of a heavy atomic nucleus into two lighter nuclei, releasing energy and additional neutrons."], reveal: "The splitting of a heavy atomic nucleus, typically uranium or plutonium, into two lighter nuclei after being struck by a neutron, releasing a burst of energy along with additional free neutrons. Those newly released neutrons are what make a self-sustaining chain reaction possible, given enough fissile material." },
  { answer: "Multimeter", discipline: "Instrumentation", accept: ["multimeter", "multi-meter"], clues: ["A single handheld tool that replaces three or more separate single-purpose meters.", "A rotary dial or set of buttons switches it between totally different measurement modes.", "Touch its two probes across a battery and it'll tell you exactly how much voltage remains.", "It's the first tool any electronics hobbyist is told to buy.", "The handheld electronics tool that measures voltage, current and resistance, among other things."], reveal: "A handheld instrument that combines several measurement functions — typically voltage, current, and resistance — into one tool, selected with a dial or buttons. Two probes touched across a circuit give the reading in whichever mode is selected." },
  { answer: "Chisel", discipline: "Manufacturing", accept: ["chisel"], clues: ["A tool that relies on a wedge, not a blade alone, to do its work.", "You typically drive it forward with a mallet rather than by hand pressure alone.", "Woodworking and stonework versions share the same basic shape but different edge angles.", "Michelangelo's tool of choice for freeing a figure from a block of marble.", "A flat-edged hand tool struck or pushed to cut and shape wood, stone or metal."], reveal: "A hand tool with a flat, wedge-shaped cutting edge, driven by hand pressure or a mallet blow to pare away material. The edge angle is tuned to the material — shallow for wood, steeper for stone or metal." },
  { answer: "Settling Time", discipline: "Control Systems", accept: ["settling time"], clues: ["One of the standard numbers used to grade a step response.", "It's measured from the moment the input changes, not from the peak.", "It ends once the response stays within a defined band around its final value.", "That band is commonly set at 2% or 5% of the final value.", "The time required for a system's step response to settle permanently within a specified tolerance band of its final value."], reveal: "The time required, measured from a step input, for a system's response to settle permanently within a specified tolerance band — commonly 2% or 5% — around its final steady-state value. Along with rise time and overshoot, it's one of the standard figures used to grade how well a control system performs." },
  { answer: "Transformer Architecture", discipline: "Deep Learning", accept: ["transformer architecture", "transformer model", "transformer"], clues: ["The architecture behind essentially every modern large language model.", "It processes an entire sequence at once, rather than one step at a time.", "Its key innovation lets every element weigh how relevant every other element is.", "That mechanism is called self-attention.", "A neural network architecture relying on self-attention to weigh the relevance of every element in a sequence to every other."], reveal: "A neural network architecture that processes an entire input sequence in parallel, using a self-attention mechanism to let every element weigh how relevant every other element in the sequence is to it. Introduced in 2017, it's the architecture underlying essentially every modern large language model." },
  { answer: "Lenz's Law", discipline: "Electromagnetics", accept: ["lenzs law", "lenz law", "lenz"], clues: ["It is essentially a statement about nature being contrary.", "It supplies a minus sign to another well-known law.", "Drop a magnet down a copper tube and watch it fall slowly.", "It's the operating principle of eddy current braking.", "The induced current opposes the change that created it."], reveal: "An induced current flows in the direction that opposes the change in magnetic flux producing it. It's the minus sign in Faraday's law made physical, and it's exactly what makes a magnet fall slowly through a copper tube instead of dropping freely." },
  { answer: "Laminar Flow", discipline: "Fluid Mechanics", accept: ["laminar flow"], clues: ["Flow that moves in smooth, orderly layers.", "Picture parallel sheets sliding past each other with no mixing between them.", "It happens at low values of a certain dimensionless number.", "Dye injected into it forms a thin, unbroken streak.", "Smooth, orderly fluid motion in parallel layers, with no chaotic mixing between them."], reveal: "Fluid motion in smooth, orderly layers that slide past one another with essentially no mixing between them. It occurs at low Reynolds number, where viscous forces dominate over inertia and keep any disturbance from growing into chaos." },
  { answer: "Kanban", discipline: "Lean Manufacturing", accept: ["kanban"], clues: ["A visual signalling system, originally built from physical cards.", "It pulls work forward rather than pushing it.", "A downstream station signals upstream only when it's actually ready for more.", "Modern software teams borrowed the same visual board concept for tracking tasks.", "A visual scheduling system that signals when more materials or work should be pulled into a process."], reveal: "A visual scheduling system, originally built from physical cards, that signals when more materials or work should be pulled into a process — only once a downstream station is actually ready for it. That 'pull' rather than 'push' logic is exactly what modern software teams borrowed when they adopted Kanban boards for tracking tasks." },
  { answer: "Friction", discipline: "Physics", accept: ["friction", "frictional force"], clues: ["A force you fight every time you try to slide something across a floor.", "It always acts opposite to the direction of motion, or attempted motion.", "Rougher surfaces generally produce more of it than smooth ones.", "Rub your hands together on a cold day and you'll feel it turn into heat.", "It's why a ball rolling across grass eventually stops, and why car tires grip the road."], reveal: "The force that resists the relative sliding (or attempted sliding) of two surfaces in contact, acting opposite to the direction of motion. It's what lets tires grip a road and shoes grip a floor, but also what generates heat and wastes energy in every moving mechanical system, from bearings to brake pads." },
  { answer: "Gear", discipline: "Mechanical Design", accept: ["gear", "cog", "gear wheel"], clues: ["A toothed wheel whose whole purpose is to trade one quantity for its inverse.", "Mesh it with another one and you can change speed, direction, or torque.", "A bicycle's derailleur exists purely to switch between different sizes of it.", "The teeth of two meshing versions must match in size, or they simply won't turn together.", "A toothed wheel that meshes with another to transmit rotational motion and change speed or torque."], reveal: "A toothed wheel that meshes with another to transmit rotational motion, trading speed for torque (or vice versa) depending on the ratio of teeth between them." },
  { answer: "Nyquist-Shannon Sampling Theorem", discipline: "Signal Processing", accept: ["nyquist", "nyquist shannon", "sampling theorem", "nyquist theorem"], clues: ["It tells you how often is often enough.", "Violate it and you get aliasing — wagon wheels spinning backwards.", "It sets the lower bound at twice the highest frequency present.", "It's why CD audio is sampled at 44.1 kHz.", "Named for a Swedish-American engineer and the father of information theory."], reveal: "A bandlimited signal can be perfectly reconstructed if sampled at more than twice its highest frequency component. Sample any slower and higher frequencies fold back down into the signal as aliases, corrupting it in a way that can't be undone afterward." },
  { answer: "Iron-Carbon Phase Diagram", discipline: "Metallurgy", accept: ["iron carbon phase diagram", "iron carbon diagram", "fe c diagram", "iron iron carbide diagram"], clues: ["A map with temperature up the side and composition along the bottom.", "It contains a eutectoid point at 0.76% and 727°C.", "Regions are labelled austenite, ferrite, cementite and pearlite.", "Beyond about 2.1% carbon you are talking about cast iron, not steel.", "It's the foundational chart of ferrous metallurgy."], reveal: "The equilibrium diagram mapping phases of iron and carbon against composition and temperature. Nearly everything a metallurgist needs to know about heat-treating steel — where austenite forms, where pearlite appears, where cast iron begins — comes off this one chart." },
  { answer: "Vapor-Compression Refrigeration Cycle", discipline: "Thermodynamics", accept: ["vapor compression refrigeration cycle", "vapour compression cycle", "refrigeration cycle", "vapor compression cycle"], clues: ["It moves heat in the opposite direction it would go on its own.", "Four components, run in a loop: compressor, condenser, expansion device, evaporator.", "The working fluid boils at low pressure and condenses at high pressure, again and again.", "It's what's running behind the wall of every household refrigerator and air conditioner.", "A closed-loop cycle that pumps heat from a cold space to a warmer one using a phase-changing refrigerant."], reveal: "A closed-loop cycle that moves heat from a cold space to a warmer one by cycling a refrigerant through compression, condensation, expansion and evaporation. Because it pumps heat uphill against its natural direction, the cycle always requires an input of work — supplied by the compressor — to keep running." },
  { answer: "LED", discipline: "Electronics", accept: ["led", "light emitting diode", "light-emitting diode"], clues: ["A component that only lets current flow in one direction, and glows because of it.", "It converts electrical energy directly into light, with very little wasted as heat.", "Get its polarity backwards in a circuit and it simply won't light up.", "It's largely replaced the incandescent bulb in homes because it wastes so little energy as heat.", "The small semiconductor component that lights up when current flows through it in the right direction."], reveal: "A semiconductor diode that emits light when current flows through it in the forward direction, converting electrical energy directly to light with very little wasted as heat. Reverse its polarity and it simply stays dark." },
  { answer: "Hardware Interrupt", discipline: "Computer Engineering", accept: ["hardware interrupt", "interrupt", "interrupt request", "irq"], clues: ["A signal that lets a slow device get a fast processor's attention.", "It suspends whatever the processor is currently doing.", "The processor saves its state, handles the request, then picks up exactly where it left off.", "Without it, a processor would have to constantly poll every device asking 'anything yet?'", "A signal from hardware that pauses normal program execution to run a dedicated handler routine."], reveal: "A signal from a hardware device that pauses whatever a processor is currently executing, saves its state, and jumps to a dedicated handler routine before resuming exactly where it left off. It exists so a fast processor doesn't have to waste cycles constantly polling slow devices asking whether anything has happened yet." },
  { answer: "Tension", discipline: "Statics", accept: ["tension"], clues: ["A pulling force transmitted along the length of a flexible object like a rope or cable.", "It always acts to pull the ends of an object inward, never to push them apart.", "A tug-of-war rope has this internal force running through it in both directions at once.", "A suspension bridge's main cables carry almost entirely this kind of force.", "The pulling force transmitted through a rope, cable or string when it's stretched taut."], reveal: "The pulling force transmitted along a rope, cable, or other flexible member when it's pulled taut — always acting to pull inward along its length, exactly the kind of force a suspension bridge's main cables are built to carry." },
  { answer: "Center Punch", discipline: "Manufacturing", accept: ["center punch", "centre punch", "centerpunch"], clues: ["A small tool whose entire job is to stop a drill bit from wandering.", "You strike its blunt end with a hammer before you ever pick up a drill.", "It leaves a small conical dimple exactly where you want to start.", "Machinists tap one lightly to mark a layout point before drilling.", "A pointed hand tool used to mark a starting dent for a drill bit."], reveal: "A pointed steel tool struck with a hammer to dent a starting mark before drilling. The dimple keeps the drill bit's tip from skating sideways across the surface when the hole is started." },
  { answer: "Bunsen Burner", discipline: "Chemistry", accept: ["bunsen burner"], clues: ["A lab device whose flame color you control with a simple air valve, not the gas valve.", "Named after a German chemist, though he didn't invent the exact design himself.", "Open its air hole and a lazy yellow flame turns into a hot blue one.", "Every school chemistry lab has rows of them, fed by a gas line.", "The gas-fed lab burner with an adjustable flame, a fixture of every school chemistry class."], reveal: "A gas-fueled lab burner with an adjustable air intake: closing it gives a cooler, luminous yellow flame; opening it mixes in more oxygen for a hotter, near-invisible blue one. Named for Robert Bunsen, whose lab popularized the design." },
  { answer: "Quadrature Encoder", discipline: "Sensors", accept: ["quadrature encoder", "incremental encoder", "encoder"], clues: ["It produces two square-wave outputs.", "They are deliberately offset by 90 degrees.", "That offset is what gives you direction, not just count.", "An index pulse provides a once-per-revolution reference.", "Counting all four edges gives you 4x resolution."], reveal: "A position sensor producing two 90°-offset pulse trains, giving both incremental count and direction of travel. The offset between channels is what lets the electronics tell forward from reverse, and counting all four edges per cycle gives four times the raw resolution." },
  { answer: "Log Mean Temperature Difference", discipline: "Heat Transfer", accept: ["log mean temperature difference", "lmtd", "log mean temp difference"], clues: ["It exists because a simple average would be wrong.", "It applies across a device with two streams.", "Counterflow and parallel flow give different values from the same terminals.", "A correction factor F is applied for shell-and-tube geometries.", "It's the driving temperature difference in heat exchanger sizing."], reveal: "The logarithmically averaged temperature difference between two streams, used in Q = UA·ΔT_lm. A simple arithmetic average of the inlet and outlet differences would overstate the driving force, since the gap between streams shrinks nonlinearly along the exchanger's length." },
  { answer: "Live Load", discipline: "Structural Engineering", accept: ["live load", "live loads"], clues: ["One half of the basic pairing every structural code starts with.", "Unlike its counterpart, it isn't fixed in place or in magnitude.", "People, furniture and vehicles are all examples of it.", "It's specified in a building code as a value per unit area for a given occupancy type.", "The variable, movable loading a structure must be designed to carry, distinct from its own permanent weight."], reveal: "The variable, movable loading a structure must be designed to carry — people, furniture, vehicles, stored goods — as opposed to its own permanent weight. Building codes specify a minimum design value per unit floor area for each occupancy type, since a library floor and a residential floor face very different real-world loading." },
  { answer: "Digital Twin", discipline: "Systems Engineering", accept: ["digital twin"], clues: ["The term became fashionable in the last decade, though the idea is older.", "It is not merely a CAD model — it's fed live data.", "It exists in parallel with a physical asset throughout its life.", "It's used for predictive maintenance and what-if simulation.", "The name is a metaphor about identical siblings."], reveal: "A live, data-connected virtual model of a physical asset, updated continuously through its operational life. Unlike a static CAD model, it stays synchronised with real sensor data throughout the asset's life, which is what makes predictive maintenance and what-if simulation possible." },
  { answer: "Decibel", discipline: "Electrical Engineering", accept: ["decibel", "db"], clues: ["A unit that's logarithmic, not linear, by design.", "It compresses an enormous range of ratios into manageable numbers.", "Doubling power corresponds to a fixed, memorable jump of about 3 of these.", "It's named, in part, after the inventor of the telephone.", "A logarithmic unit expressing the ratio between two power or amplitude levels."], reveal: "A logarithmic unit expressing the ratio between two power or amplitude levels, chosen because it compresses the enormous dynamic ranges common in audio and RF engineering into small, workable numbers. A doubling of power always corresponds to a fixed jump of about 3 dB, no matter what the absolute power levels actually are." },
  { answer: "Derating", discipline: "Reliability Engineering", accept: ["derating", "de rating"], clues: ["A deliberate decision to under-use something.", "It buys margin against temperature, voltage and current.", "A capacitor run at half its rated voltage lasts far longer.", "Military and space standards specify it explicitly.", "Operating a component below its maximum rating to improve reliability."], reveal: "Deliberately operating a component below its rated limits to extend life and increase reliability margin. Running a capacitor at half its rated voltage can extend its working life dramatically, which is why aerospace standards specify derating factors explicitly." },
  { answer: "Density", discipline: "Fluid Mechanics", accept: ["density"], clues: ["A property that explains why one object sinks and another, same size, floats.", "It's mass divided by volume, nothing more exotic than that.", "Oil floats on water because its value of this is lower.", "Lead feels heavy for its size because this is high; styrofoam feels light because it's low.", "How much mass is packed into a given volume of a material."], reveal: "Mass divided by volume — how tightly packed a material's mass is into the space it occupies. Compare two objects' values and you can predict which one floats on the other." },
  { answer: "Bias-Variance Tradeoff", discipline: "Machine Learning", accept: ["bias variance tradeoff"], clues: ["A fundamental tension that every model, no matter how sophisticated, has to navigate.", "One side of it describes a model that's too simple to capture the real pattern.", "The other side describes a model that's captured the pattern and all its noise besides.", "Push down one side and, without more data, the other side tends to rise.", "The tradeoff between a model being too simple to fit the data (underfitting) and too sensitive to it (overfitting)."], reveal: "The fundamental tension between a model being too simple to capture the real underlying pattern — high bias, or underfitting — and being too sensitive to the specific training data, noise included — high variance, or overfitting. Without more data, pushing one down tends to push the other up, which is exactly why finding the right model complexity matters so much." },
  { answer: "Corrosion", discipline: "Materials", accept: ["corrosion"], clues: ["A gradual process that converts a refined metal back toward its original, more stable ore-like form.", "It's fundamentally an electrochemical reaction, not just a physical one.", "Moisture and oxygen together are almost always required to get it started.", "Protective coatings, paints and sacrificial metals all exist mainly to slow it down.", "The gradual chemical or electrochemical deterioration of a material, especially a metal, by its environment."], reveal: "The gradual electrochemical deterioration of a material, most often a metal, as it reacts with its environment — usually moisture and oxygen — and reverts toward a more chemically stable, lower-energy state, much like the original ore." },
  { answer: "Wheatstone Bridge", discipline: "Instrumentation", accept: ["wheatstone bridge", "wheatstone"], clues: ["A circuit arrangement over 180 years old, still used daily.", "Four elements arranged in a diamond.", "You look for a null reading in the middle.", "It's how a strain gauge turns deformation into millivolts.", "Named after the English scientist who popularised it, though he didn't invent it."], reveal: "A four-arm bridge circuit that measures unknown resistance precisely by balancing to a null output. Because the measurement happens right at balance, where no current flows through the detector, it sidesteps the accuracy limits of the meter itself." },
  { answer: "Pendulum", discipline: "Vibrations", accept: ["pendulum"], clues: ["A weight suspended so it swings back and forth under a single restoring force.", "For small swings, the time it takes to complete one cycle barely depends on how wide the swing is.", "Its period depends heavily on the length of its string, but not on the mass of its weight.", "Old mechanical clocks relied on one swinging at a steady, known rate to keep accurate time.", "A weight hung from a fixed point that swings back and forth under gravity."], reveal: "A weight suspended from a fixed point, swinging back and forth under gravity's restoring pull. For small swings, its period depends on its length but, surprisingly, not on the weight's mass — the steady rhythm old clocks were built around." },
  { answer: "Angle of Repose", discipline: "Geotechnical Engineering", accept: ["angle of repose"], clues: ["The steepest slope a loose granular pile can hold, unaided.", "Pour dry sand onto a table and watch the pile settle into exactly this shape.", "It depends on particle shape, size and friction, not on the pile's overall size.", "Exceed it and the material simply slides until it's no longer exceeded.", "The maximum angle from horizontal at which a granular material can be piled without slumping."], reveal: "The maximum angle from horizontal at which a loose granular material can be piled without slumping further, set by the friction and interlocking between individual particles rather than the size of the pile itself. Pour dry sand onto a table and it naturally settles into exactly this angle, sliding until the slope no longer exceeds it." },
  { answer: "Hammer", discipline: "Manufacturing", accept: ["hammer"], clues: ["One of the oldest tools humans have used, essentially unchanged in principle for millennia.", "Most of its usefulness comes from concentrating momentum into a small striking face.", "One end often drives fasteners in; the claw on the other end can pull them back out.", "A single hard swing beats a long, slow push for driving a nail.", "The tool you swing to drive a nail into wood."], reveal: "A tool with a weighted head on a handle, used to deliver a concentrated impact — driving nails, shaping metal, or breaking things apart. Its effectiveness comes from converting the swing's momentum into a brief, powerful force at a small contact point." },
  { answer: "Aerodynamic Stall", discipline: "Aerodynamics", accept: ["aerodynamic stall", "stall", "wing stall"], clues: ["A sudden, dramatic loss of something a wing was providing just moments before.", "It has nothing directly to do with the engine, despite the name's implication.", "It happens past a critical angle of attack, not at a particular speed.", "Airflow over the upper surface separates instead of staying smoothly attached.", "The sudden loss of lift that occurs when a wing exceeds its critical angle of attack and airflow separates."], reveal: "The sudden loss of lift that occurs when a wing's angle of attack exceeds a critical value and airflow can no longer stay smoothly attached to the upper surface, separating into turbulent, lift-destroying eddies. Despite the name, it has nothing directly to do with engine power — it's purely a function of angle of attack, and can happen at any airspeed." },
  { answer: "Solenoid", discipline: "Electromagnetics", accept: ["solenoid", "electromagnetic solenoid"], clues: ["A coil of wire whose shape alone lets it behave like a bar magnet, but only when energized.", "A ferromagnetic core, called a plunger, is pulled inside it when current flows.", "It converts electrical current directly into a linear pushing or pulling motion.", "A car's door lock actuator and its starter motor's engagement both rely on one.", "A coil of wire that generates a magnetic field, often used to pull a metal plunger when energized."], reveal: "A coil of wire that generates a uniform magnetic field along its axis when current flows through it, commonly used to pull a ferromagnetic plunger inward — converting electrical current directly into linear mechanical motion." },
  { answer: "Chemical Equilibrium Constant", discipline: "Chemical Engineering", accept: ["chemical equilibrium constant", "equilibrium constant", "keq"], clues: ["A single number that tells you where a reaction settles, not how fast it gets there.", "It's a ratio of product concentrations to reactant concentrations, at equilibrium.", "A large value means the reaction favours products heavily.", "It's fixed for a given reaction at a given temperature, regardless of starting amounts.", "K_eq — the ratio of product to reactant concentrations, each raised to its stoichiometric coefficient, at equilibrium."], reveal: "A fixed ratio, for a given reaction at a given temperature, of product concentrations to reactant concentrations at equilibrium, each raised to its stoichiometric coefficient. It says nothing about how fast a reaction reaches that point — only where it ultimately settles, regardless of the starting amounts of reactants." },
  { answer: "Roller Chain", discipline: "Mechanical Design", accept: ["roller chain", "bicycle chain", "drive chain"], clues: ["A component made of hundreds of identical small links, none of them useful alone.", "It transmits rotation between two toothed wheels without ever touching them directly except at the teeth.", "It needs regular lubrication, or friction between its many links quickly wears it out.", "A bicycle's pedals turn its rear wheel through exactly this kind of connection.", "The linked metal chain that meshes with toothed sprockets to transmit rotational power, as on a bicycle."], reveal: "A chain of linked plates and rollers that meshes with toothed sprockets to transmit rotational power over a distance — most familiar as the chain connecting a bicycle's pedals to its rear wheel." },
  { answer: "Bipolar Junction Transistor", discipline: "Electronics", accept: ["bipolar junction transistor", "bjt", "transistor"], clues: ["A three-terminal device that can act as either a switch or an amplifier.", "A small current at one terminal controls a much larger current between the other two.", "It comes in two complementary flavours, mirror images of each other.", "Those flavours are called NPN and PNP.", "A semiconductor device in which a small base current controls a much larger collector current."], reveal: "A three-terminal semiconductor device in which a small current flowing into the base terminal controls a much larger current flowing between the collector and emitter. It comes in two complementary types, NPN and PNP, and its ability to amplify or switch that larger current made it the component that launched the entire solid-state electronics era." },
  { answer: "Watchdog Timer", discipline: "Embedded Systems", accept: ["watchdog timer", "watchdog", "wdt"], clues: ["It's a counter that you must keep interrupting.", "The firmware has to 'kick' or 'feed' it periodically.", "If the main loop hangs, it stops being fed.", "The consequence is a hardware reset.", "Safety-critical embedded systems mandate it."], reveal: "A hardware timer that resets the system if software fails to service it, recovering from lockups. Firmware has to actively 'kick' it on a schedule; if the main loop hangs, the kicks stop, the timer expires, and the hardware forces a reset without human intervention." },
  { answer: "Net Positive Suction Head", discipline: "Fluid Machinery", accept: ["net positive suction head", "npsh"], clues: ["A margin that exists purely to keep something bad from happening at a pump's inlet.", "Run it too low and cavitation shows up uninvited.", "It compares the available suction pressure against the fluid's vapour pressure.", "Raising the fluid temperature shrinks this margin, even with no other change.", "The margin of pressure above a liquid's vapour pressure available at a pump's suction inlet."], reveal: "The margin of absolute pressure above a liquid's vapour pressure that's available at a pump's suction inlet, expressed as a head. Keeping the available margin comfortably above the pump's required minimum is what keeps cavitation from forming right where the pump can least tolerate it." },
  { answer: "HAZOP", discipline: "Safety Engineering", accept: ["hazop", "hazard and operability study"], clues: ["A structured, facilitated team review of a process design.", "It works through the plant node by node.", "It uses guide words applied to parameters.", "Guide words include NO, MORE, LESS, REVERSE and AS WELL AS.", "Developed by ICI in the 1960s for chemical plants."], reveal: "A systematic team review applying guide words to process parameters to identify hazards and operability problems. Working through the plant node by node with guide words like NO, MORE, LESS and REVERSE forces a team to surface hazards a less structured review would likely miss." },
  { answer: "Wavelength", discipline: "Signal Processing", accept: ["wavelength"], clues: ["A distance, not a time, even though it's closely tied to both.", "It's the distance between two identical points on consecutive repeats of a wave.", "Multiply it by frequency and you get the wave's speed.", "Red light has a longer one of these than blue light does.", "The distance between two corresponding points, like consecutive peaks, on a repeating wave."], reveal: "The distance between two corresponding points on consecutive cycles of a wave, such as one peak to the next. Multiplied by frequency, it gives the wave's speed — which is why red light's longer value corresponds to a lower frequency than blue." },
  { answer: "Hydraulic Jump", discipline: "Civil Engineering", accept: ["hydraulic jump"], clues: ["An abrupt, turbulent, visible transition in an open channel.", "You can see a small one in your kitchen sink.", "It dissipates a great deal of energy, which is often the point.", "Stilling basins below spillways are designed around it.", "Flow goes from supercritical to subcritical."], reveal: "The sudden rise in water depth as open-channel flow transitions from supercritical to subcritical, dissipating energy. You can watch a small one form in a kitchen sink, and engineers deliberately trigger larger versions in stilling basins to burn off energy below spillways." },
  { answer: "Gain Margin", discipline: "Control Systems", accept: ["gain margin"], clues: ["A safety buffer, read straight off a frequency-response plot.", "It's measured at the frequency where phase has dropped to exactly −180°.", "It tells you how much extra gain the loop could tolerate before going unstable.", "A negative value is bad news — the system is already unstable.", "The amount of additional open-loop gain, in decibels, that would push a stable system to the brink of instability."], reveal: "The amount of additional open-loop gain, measured in decibels at the frequency where phase has dropped to exactly −180°, that a stable feedback system could tolerate before being pushed to the edge of instability. It's read straight off a Bode or Nyquist plot as one of the two standard stability safety margins." },
  { answer: "Second Law of Thermodynamics", discipline: "Thermodynamics", accept: ["second law of thermodynamics", "2nd law of thermodynamics", "second law"], clues: ["It gives time a direction.", "It's the reason perpetual motion machines of the second kind are impossible.", "It concerns a quantity that never decreases in an isolated system.", "Clausius and Kelvin each wrote their own statement of it.", "The quantity in question is entropy."], reveal: "The total entropy of an isolated system can never decrease; heat cannot spontaneously flow from cold to hot. It's the reason every real process loses some useful energy as waste heat, and why perpetual motion machines are physically impossible, not just impractical." },
  { answer: "Poisson's Ratio", discipline: "Materials", accept: ["poissons ratio", "poisson ratio", "poisson"], clues: ["A dimensionless material property, usually between 0 and 0.5.", "Rubber sits near the top of that range; cork sits near zero.", "It describes what happens in one direction when you pull in another.", "A few exotic auxetic materials have a negative value.", "It's the negative ratio of transverse strain to axial strain."], reveal: "ν = −ε_transverse / ε_axial — how much a material contracts laterally when stretched. Most engineering materials sit around 0.3, but a rare class of auxetic structures actually gets fatter when stretched, giving a negative value." },
  { answer: "Switch", discipline: "Electrical Engineering", accept: ["switch", "electrical switch"], clues: ["A device with exactly two useful states, and nothing in between.", "It works by physically making or breaking a conductive path.", "The simplest version is just a mechanical contact you flip by hand.", "You use one every time you walk into a room and want the light on.", "A device that opens or closes an electrical circuit to turn something on or off."], reveal: "A device that makes or breaks a conductive path in a circuit, switching current on or off. The mechanism ranges from a simple mechanical contact you flip by hand to a transistor switching millions of times a second." },
  { answer: "Socket Wrench", discipline: "Manufacturing", accept: ["socket wrench", "socket set", "ratchet"], clues: ["A tool built around a ratcheting mechanism that lets you keep turning without resetting your grip.", "Interchangeable heads let one handle fit many different bolt sizes.", "An internal spring and pawl mechanism let it turn one way freely and grip the other.", "You swap its socket to match the bolt, then just keep clicking it back and forth.", "The tool with swappable heads and a ratcheting handle used to tighten or loosen bolts."], reveal: "A ratcheting handle paired with interchangeable sockets, letting one tool drive many bolt sizes without lifting off the fastener between strokes. A pawl inside the ratchet lets it spin freely in one direction and grip in the other." },
  { answer: "Full Adder", discipline: "Digital Logic", accept: ["full adder"], clues: ["A building block for arithmetic, made entirely of logic gates.", "It handles three input bits at once, not just two.", "That third input is a carry coming in from a previous stage.", "Chain enough of them together and you can add numbers of any size.", "A digital circuit that adds three binary bits — two operands and a carry-in — producing a sum and a carry-out."], reveal: "A digital circuit that adds three binary bits at once — two operands plus a carry-in from the previous stage — producing a sum bit and a carry-out. Chaining full adders together, each feeding its carry into the next, is exactly how a processor adds numbers far larger than a single bit." },
  { answer: "Servo Motor", discipline: "Robotics", accept: ["servo motor", "servo"], clues: ["A motor that doesn't just spin — it knows exactly where it's pointing.", "Position feedback is built directly into the package.", "A built-in controller constantly compares actual position against a commanded one.", "It's the standard actuator in hobby robotics and precision industrial positioning alike.", "A motor combined with a position feedback sensor and controller, enabling precise control of angular or linear position."], reveal: "A motor paired with a built-in position feedback sensor and controller, letting it be commanded to a precise angular or linear position rather than simply spinning at a set speed. That closed-loop feedback is exactly what makes it the standard actuator choice from hobby robotics all the way up to precision industrial positioning systems." },
  { answer: "Photodiode", discipline: "Sensors", accept: ["photodiode", "photo diode"], clues: ["A component that runs the usual job of a diode almost entirely in reverse.", "It generates a small current when light strikes its light-sensitive junction.", "The brighter the light hitting it, the larger the current it produces.", "TV remotes rely on a receiver built around one to catch an infrared signal.", "The semiconductor component that converts light falling on it into an electric current."], reveal: "A semiconductor component that converts light falling on its junction into a small electric current, with output current rising as the light gets brighter — the sensing element behind everything from light meters to infrared remote receivers." },
  { answer: "Froude Number", discipline: "Fluid Mechanics", accept: ["froude number", "froude"], clues: ["Named after a naval engineer who studied ship resistance.", "It compares inertial force against gravitational force.", "It decides whether open-channel flow is racing ahead of its own waves or not.", "Below one, a disturbance can travel upstream; above one, it can't.", "Fr = V/√(gL) — the ratio of flow inertia to gravitational wave speed."], reveal: "A dimensionless ratio comparing a flow's inertia to the force of gravity, most often used to characterise open-channel and free-surface flows. Below one the flow is subcritical and a surface disturbance can propagate upstream against it; above one the flow is supercritical and outruns its own waves entirely." },
  { answer: "Shear Wall", discipline: "Structural Engineering", accept: ["shear wall"], clues: ["A wall whose job has nothing to do with holding up a roof alone.", "It's designed specifically to resist lateral forces, not just gravity load.", "Wind and earthquakes are the loads it's really there to fight.", "Placed strategically, it stiffens a building against swaying sideways.", "A structural wall designed to resist lateral loads like wind and seismic forces through in-plane stiffness."], reveal: "A structural wall specifically designed to resist lateral loads — wind or seismic forces — by acting stiffly in its own plane, rather than simply carrying gravity load like an ordinary wall. Placed strategically through a building's floor plan, shear walls dramatically reduce how much a structure sways under lateral load." },
  { answer: "Feeler Gauge", discipline: "Metrology", accept: ["feeler gauge", "feeler gage"], clues: ["A measuring tool that's really just a set of thin metal blades, each a precise thickness.", "You judge a gap's size by which blade slides through snugly and which doesn't fit at all.", "Mechanics use it to check the exact clearance between an engine's valve and its rocker arm.", "Its whole set typically fans out like a pocketknife's collection of blades.", "The set of thin metal blades of precise thickness used to measure small gaps."], reveal: "A set of thin metal blades, each a precisely known thickness, used to measure a small gap by finding which blade fits through snugly. Mechanics use it constantly to check clearances like an engine's valve gap." },
  { answer: "Breadboard", discipline: "Electronics", accept: ["breadboard", "prototyping board"], clues: ["A prototyping tool that lets you build a circuit without a single solder joint.", "Rows of internally connected holes let components share a connection just by being plugged into the same row.", "Its name comes from a literal wooden board hobbyists once used to mount early radio components.", "Every electronics beginner's first circuit is almost always built on one.", "The reusable prototyping board with rows of holes used to build circuits without soldering."], reveal: "A reusable prototyping board with rows of internally connected holes, letting components be wired together temporarily just by plugging them in — no soldering required. The name is a holdover from hobbyists once literally using a wooden bread board." },
  { answer: "Test Tube", discipline: "Chemistry", accept: ["test tube"], clues: ["A piece of labware defined mostly by what it isn't shaped like — no flat base.", "Its round bottom means it needs a rack just to stand upright.", "You'd heat a small sample in it by holding it at an angle over a flame.", "The small glass tube every chemistry-class stereotype pictures held up to the light.", "The small, narrow glass tube with a rounded bottom used to hold and mix small samples."], reveal: "A small, narrow cylindrical piece of glassware with a rounded, open-top bottom, used to hold, mix, or gently heat small liquid samples. The rounded base is why it needs a rack to stand upright." },
  { answer: "Acceleration", discipline: "Dynamics", accept: ["acceleration"], clues: ["A quantity that isn't just about speeding up — slowing down counts too, and so does turning.", "It's the rate at which velocity itself is changing, over time.", "You feel it pressed into your seat whenever a car speeds up quickly.", "Newton's second law links it directly to force and mass: F = ma.", "The rate at which an object's velocity changes over time."], reveal: "The rate at which velocity changes over time — covering speeding up, slowing down, and even changing direction at constant speed. Newton's second law ties it directly to the net force applied and the object's mass." },
  { answer: "Hohmann Transfer Orbit", discipline: "Aerospace Engineering", accept: ["hohmann transfer", "hohmann transfer orbit", "hohmann"], clues: ["It uses exactly two engine burns.", "The path between them is an ellipse.", "It's the most propellant-efficient two-impulse route between circular orbits.", "Its cost is time — it is also the slowest.", "Named after a German engineer who published it in 1925."], reveal: "A two-burn elliptical transfer between coplanar circular orbits, minimising propellant at the cost of time. One burn kicks the spacecraft onto an elliptical path between the two orbits, and a second burn at the far end circularises it — the most propellant-efficient route, if you're not in a hurry." },
  { answer: "Branch Prediction", discipline: "Computer Engineering", accept: ["branch prediction"], clues: ["A processor's educated guess about something it can't yet know for certain.", "It exists to keep a pipeline full instead of sitting idle.", "Guess wrong and the pipeline has to be flushed and restarted.", "Modern processors keep a history of past outcomes to improve their guesses.", "Hardware that predicts which way a conditional branch will go, before the condition is actually evaluated."], reveal: "Hardware that predicts which way a conditional branch will go before the condition has actually been evaluated, so a pipelined processor can keep fetching and executing instructions speculatively instead of stalling. Guess wrong and the speculative work has to be discarded and the pipeline restarted — the cost that makes prediction accuracy such a critical performance factor." },
  { answer: "Oscilloscope", discipline: "Instrumentation", accept: ["oscilloscope", "scope"], clues: ["An instrument that turns an invisible electrical signal into a shape you can actually see.", "Its screen plots voltage against time, tracing the waveform as it happens.", "It can reveal a signal's noise or distortion that a simple numeric meter would never show.", "Engineers use one to check whether a square wave actually looks square.", "The instrument that displays a graph of a changing voltage signal over time."], reveal: "An instrument that plots a voltage signal against time on a screen, tracing out its waveform live. Where a multimeter gives one number, this shows the signal's actual shape — revealing noise, distortion, or timing a single reading can't." },
  { answer: "Bench Grinder", discipline: "Manufacturing", accept: ["bench grinder"], clues: ["A stationary shop tool built around two spinning abrasive wheels.", "It's normally bolted straight to a workbench, never carried around the shop.", "One wheel is often coarser than the other, for rough work and finishing.", "You hold the workpiece against the spinning wheel, not the other way around.", "The shop machine used to sharpen tools and grind down metal edges."], reveal: "A stationary machine with two spinning abrasive wheels, bolted to a bench and used to sharpen edges, remove burrs, or shape metal. One wheel is typically coarser for stock removal and the other finer for finishing." },
  { answer: "Heat Sink", discipline: "Heat Transfer", accept: ["heat sink", "heatsink"], clues: ["A component with one job: move heat away from something else as fast as possible.", "Its many thin metal fins exist purely to maximize surface area exposed to the air.", "A layer of thermal paste often bridges the tiny gap between it and the chip it protects.", "Open up a computer case and you'll find one clamped directly onto the processor.", "The finned metal component that draws heat away from a hot component and dissipates it into the air."], reveal: "A finned metal component, usually aluminum or copper, that draws heat away from a hot component like a processor and dissipates it into the surrounding air. The fins exist purely to maximize surface area for that heat exchange." },
  { answer: "Rolling-Element Bearing", discipline: "Mechanical Design", accept: ["rolling element bearing", "ball bearing", "roller bearing"], clues: ["It replaces sliding friction with a much smaller kind of friction.", "Small hardened spheres or cylinders sit between two rings.", "A cage keeps them evenly spaced so they don't collide with each other.", "One variety handles radial load well; another is built for axial thrust.", "It supports a rotating shaft by letting rolling elements carry the load instead of a sliding surface."], reveal: "A bearing that supports a rotating shaft using hardened balls or rollers trapped between an inner and outer ring, replacing sliding friction with much lower rolling friction. A cage keeps the rolling elements evenly spaced, and different geometries are optimised for radial load, axial thrust, or a combination of both." },
  { answer: "Bar Magnet", discipline: "Electromagnetics", accept: ["bar magnet"], clues: ["An object whose two ends never quite agree with each other, magnetically.", "One end always points roughly toward Earth's north, the other toward its south.", "Cut it in half and, surprisingly, you get two smaller magnets, not two separate poles.", "Sprinkle iron filings near it and you can literally see the shape of its invisible field.", "The classic rectangular magnet with a north and south pole, used to demonstrate magnetic fields in class."], reveal: "A permanent magnet in a simple rectangular shape, with a north pole at one end and a south pole at the other. Cut it in half and, rather than isolating one pole, you get two smaller magnets, each with its own north and south." },
  { answer: "Polymerization", discipline: "Chemical Engineering", accept: ["polymerization", "polymerisation"], clues: ["A process that builds enormous molecules from small, repeating building blocks.", "Those small building blocks are called monomers.", "Chain the same monomer together thousands of times and you get a polymer.", "Nearly every plastic in existence starts life as this reaction.", "The chemical process of linking many small monomer molecules together into a long-chain polymer."], reveal: "The chemical process of linking many small monomer molecules together, one after another, into a long-chain polymer. Nearly every plastic in existence begins life exactly this way — a single small molecule repeated thousands or millions of times over into one enormous chain." },
  { answer: "Reflection", discipline: "Optics", accept: ["reflection"], clues: ["A phenomenon where a wave bounces back rather than passing through or bending.", "On a smooth surface, the angle it leaves at exactly matches the angle it arrived at.", "A mirror is essentially a surface engineered to maximize this effect while minimizing everything else.", "A rough surface still does this to light, just scattered in every direction at once.", "The bouncing of light, or another wave, off a surface rather than passing through it."], reveal: "The bouncing of a wave, like light, off a surface rather than passing through or being absorbed by it. On a smooth surface the outgoing angle exactly mirrors the incoming one — the principle a mirror is built to exploit." },
  { answer: "Three-Phase Power", discipline: "Electrical Power", accept: ["three phase power", "three phase electricity", "3 phase power"], clues: ["The standard way electricity is generated and transmitted at scale.", "Three voltage waveforms, each shifted from the others by the same fixed angle.", "That shift is 120 degrees.", "Combine them right and the instantaneous power delivered is perfectly constant, not pulsing.", "A power system using three AC voltages, each phase-shifted 120° from the others."], reveal: "An AC power system using three voltage waveforms, each shifted by 120° from the others, used almost universally for generation, transmission and industrial power. Combined correctly, the total instantaneous power delivered by the three phases together is constant, unlike the pulsing power delivered by a single-phase source." },
  { answer: "Compiler", discipline: "Computer Science", accept: ["compiler"], clues: ["A translator that works ahead of time, not on the fly.", "It converts source code into something a machine can execute directly.", "Its interpreted cousin instead translates and runs code line by line.", "It passes through stages: lexical analysis, parsing, optimisation, code generation.", "A program that translates source code written in one language into executable machine code, ahead of runtime."], reveal: "A program that translates source code into executable machine code entirely ahead of runtime, passing it through stages like lexical analysis, parsing, optimisation and code generation along the way. Its counterpart, an interpreter, instead translates and executes code line by line as the program runs, trading upfront translation time for execution speed." },
  { answer: "Neutron", discipline: "Nuclear Engineering", accept: ["neutron"], clues: ["A particle that carries mass into an atom's nucleus without adding any charge.", "It sits in the nucleus alongside the proton, but unlike it, has no charge at all.", "Fire one into a heavy nucleus like uranium-235, and you can trigger a chain reaction.", "Its number can vary between atoms of the same element, defining different isotopes.", "The electrically neutral particle found in an atom's nucleus alongside the proton."], reveal: "An electrically neutral particle found in an atom's nucleus alongside the positively charged proton. Firing one into a heavy nucleus like uranium-235 is exactly what triggers the chain reaction behind nuclear fission." },
  { answer: "Design for Manufacturability", discipline: "Manufacturing", accept: ["design for manufacturability", "dfm"], clues: ["A design philosophy focused on a question engineers sometimes forget to ask.", "That question is simply: can this actually be built easily and cheaply?", "It pushes decisions about production earlier, back into the design phase itself.", "Reducing part count is one of its most common, most effective strategies.", "The practice of designing a product specifically to be easy, reliable and cost-effective to manufacture."], reveal: "The practice of designing a product specifically to be easy, reliable and cost-effective to manufacture, rather than treating production as someone else's problem to solve later. Reducing part count, simplifying tolerances and choosing manufacturing-friendly geometry early in design are among its most common and most effective strategies." },
  { answer: "Spring", discipline: "Solid Mechanics", accept: ["spring", "coil spring"], clues: ["A component engineered to store energy temporarily and then give it right back.", "Stretch or compress it, and it pushes or pulls back roughly in proportion to how far you moved it.", "A pogo stick's bounce and a ballpoint pen's click both rely on one.", "Hooke's Law was written specifically to describe how this component behaves.", "The coiled component that stores energy when deformed and releases it as it returns to shape."], reveal: "A component, usually coiled, that stores mechanical energy when stretched or compressed and releases it as it returns to its natural shape, pushing or pulling back roughly in proportion to how far it's displaced — the behavior Hooke's Law describes." },
  { answer: "Window Function", discipline: "Signal Processing", accept: ["window function", "windowing"], clues: ["A function applied before you ever take a Fourier transform of real data.", "It tapers a signal's edges down toward zero instead of cutting them off sharply.", "Without it, spectral leakage smears energy across frequencies that were never really there.", "Hann and Hamming are two of the most common named varieties.", "A weighting function applied to a finite signal segment to reduce spectral leakage before frequency analysis."], reveal: "A weighting function applied to a finite chunk of signal before frequency analysis, tapering its edges smoothly down to zero instead of cutting them off abruptly. Without one, that abrupt cutoff smears energy across the spectrum as leakage, corrupting frequencies that were never actually present in the original signal." },
  { answer: "S-N Curve", discipline: "Materials", accept: ["sn curve", "s n curve", "wohler curve", "stress life curve"], clues: ["Plotted on log axes, sloping downward to the right.", "It concerns failure at stresses below the yield point.", "Steels show a flat asymptote; aluminium alloys do not.", "That flat asymptote is called the endurance limit.", "It's the fundamental design tool for fatigue life."], reveal: "A plot of cyclic stress amplitude against cycles to failure — the basis of stress-life fatigue design. Steels typically show a flat endurance limit below which fatigue failure effectively never occurs, while non-ferrous alloys like aluminium keep declining indefinitely." },
  { answer: "Hydraulic Conductivity", discipline: "Geotechnical Engineering", accept: ["hydraulic conductivity", "soil permeability", "permeability"], clues: ["A property that decides how easily water moves through a porous material.", "Gravel sits at one extreme of the scale; clay sits at the other.", "It's the constant of proportionality in a groundwater-flow law named after a 19th-century French engineer.", "It spans an enormous range of values, more than most other engineering properties.", "A soil property quantifying how readily water flows through it under a given hydraulic gradient."], reveal: "A soil property quantifying how readily water flows through it under a given hydraulic gradient, spanning an enormous range from gravel, which drains almost instantly, to clay, which can take years to drain the same distance. It's the constant of proportionality in Darcy's law, the fundamental equation of groundwater flow." },
  { answer: "Carnot Cycle", discipline: "Thermodynamics", accept: ["carnot cycle", "carnot"], clues: ["A theoretical construct nobody has ever built.", "It consists of four reversible processes.", "Two isothermal steps and two adiabatic steps.", "Its efficiency depends only on two absolute temperatures.", "It sets the upper limit no real heat engine can beat."], reveal: "The idealised reversible cycle setting maximum possible heat-engine efficiency: η = 1 − T_cold/T_hot. No real engine reaches it, since real processes involve friction and finite-rate heat transfer, but it defines the ceiling every practical design is measured against." },
  { answer: "Steady-State Error", discipline: "Control Systems", accept: ["steady state error"], clues: ["The gap that's left over after all the transient excitement has died down.", "It's measured once the system has settled, not during the initial response.", "Adding integral action to a controller is the classic way to drive it to zero.", "A simple proportional-only controller almost always leaves some of it behind.", "The persistent difference between a system's actual output and its desired setpoint once transients have decayed."], reveal: "The persistent difference between a system's actual output and its desired setpoint that remains after all transient response has died away. A pure proportional controller almost always leaves some behind, which is exactly why integral control action exists — to drive that lingering error down to zero." },
  { answer: "Maximum Power Transfer Theorem", discipline: "Electrical Engineering", accept: ["maximum power transfer theorem", "maximum power transfer", "impedance matching theorem"], clues: ["It is about power delivered, not efficiency — those two conflict here.", "At the optimum you only achieve 50% efficiency.", "It's why RF systems care about 50 ohms.", "It applies to the load relative to the source.", "The load should equal the source resistance."], reveal: "Maximum power is delivered to a load when load resistance equals the source's internal resistance. It's about power delivered, not efficiency — at that matched point only half the source's total power actually reaches the load, the rest dissipates internally." },
  { answer: "Gauge R&R", discipline: "Quality Engineering", accept: ["gauge r and r", "gauge rr", "gage rr", "grr", "gauge repeatability and reproducibility"], clues: ["A study you run before you trust any of your measurements.", "It separates variation in the process from variation in the measuring.", "Multiple operators measure multiple parts multiple times.", "Below 10% of tolerance is generally acceptable.", "The two Rs stand for repeatability and reproducibility."], reveal: "A measurement systems analysis quantifying how much observed variation comes from the gauge and its operators. If the measurement system itself accounts for too much of the observed spread, no amount of process improvement will show up reliably in the data." },
  { answer: "Activation Function", discipline: "Machine Learning", accept: ["activation function", "relu"], clues: ["Without it, a stack of neural network layers would collapse into nothing more than one big linear equation.", "It's applied to a neuron's output before passing it to the next layer.", "One especially popular modern choice simply zeroes out anything negative.", "That simple, popular choice is called ReLU.", "A nonlinear function applied to a neuron's output, letting a network learn nonlinear relationships in data."], reveal: "A nonlinear function applied to each neuron's output before it's passed to the next layer, which is what lets a stack of layers learn genuinely nonlinear relationships instead of collapsing into one giant linear equation. ReLU — simply zeroing out any negative value — is one of the most widely used choices for its simplicity and training speed." },
  { answer: "Miller Effect", discipline: "Electronics", accept: ["miller effect"], clues: ["It makes a small capacitor behave as if it were much, much larger.", "It only shows up around an inverting amplifier stage.", "It's a major factor limiting how fast a common-emitter or common-source stage can switch.", "The apparent capacitance is multiplied by roughly one plus the stage's gain.", "The apparent multiplication of a feedback capacitance across an inverting, high-gain amplifier stage."], reveal: "The apparent multiplication of a small feedback capacitance, bridging the input and output of an inverting amplifier stage, into a much larger effective input capacitance — roughly the actual capacitance times one plus the stage's gain. It's one of the dominant effects limiting high-frequency performance in transistor amplifier stages." },
  { answer: "Darcy-Weisbach Equation", discipline: "Fluid Mechanics", accept: ["darcy weisbach", "darcy weisbach equation", "darcy friction factor"], clues: ["It answers a question every pipework designer asks.", "It needs a dimensionless factor that depends on roughness and Reynolds number.", "You usually look that factor up on a chart, or solve Colebrook iteratively.", "Head loss goes with the square of velocity.", "It calculates friction pressure loss along a pipe."], reveal: "h_f = f (L/D)(v²/2g) — the friction head loss for flow through a pipe. The friction factor itself has to be found separately, usually from the Moody chart or by solving the Colebrook equation iteratively." },
  { answer: "Controlled-Release Drug Delivery", discipline: "Biomedical Engineering", accept: ["controlled release drug delivery", "drug delivery system", "controlled release"], clues: ["A system designed to release medication on a schedule, not all at once.", "It aims to keep a drug's concentration in the body inside a narrow, effective window.", "A single daily pill can sometimes do the job that would otherwise need many doses.", "Biodegradable polymer coatings are one common way of engineering the release rate.", "A drug delivery system engineered to release medication gradually over time, maintaining a steady therapeutic concentration."], reveal: "A drug delivery system engineered to release medication gradually and predictably over time, keeping its concentration in the body inside a narrow therapeutic window rather than spiking and crashing after a single dose. Biodegradable polymer coatings are a common way to engineer that release rate, letting a single dose do the work that would otherwise take several." },
  { answer: "Drive Belt", discipline: "Mechanical Design", accept: ["drive belt", "fan belt", "timing belt"], clues: ["A flexible loop that transmits power without any teeth, in its simplest form.", "It relies on friction gripping two or more pulleys to keep from slipping.", "Under an engine's hood, one commonly powers the alternator and water pump at once.", "A worn, cracked or squealing one is a classic warning sign under the hood.", "The flexible loop that wraps around pulleys to transmit rotational power between shafts."], reveal: "A flexible loop, usually rubber, wrapped around two or more pulleys to transmit rotational power between shafts using friction (or teeth, in a toothed version). Under a car's hood, one often drives several accessories from a single pulley." },
  { answer: "Band Saw", discipline: "Manufacturing", accept: ["band saw", "bandsaw"], clues: ["Its cutting tool is a single continuous loop, not a blade with two ends.", "The loop runs over two or more wheels, like a very sharp conveyor belt.", "It can cut curves that a straight reciprocating blade never could.", "Unlike a table saw, its blade moves in one continuous direction, not back and forth.", "The shop saw with a looped blade running around wheels, good for curved cuts."], reveal: "A saw whose blade is a continuous toothed loop stretched around two or more wheels, moving in one constant direction. That continuous motion, plus a narrow blade, lets it follow curves that a rigid, reciprocating blade can't." },
  { answer: "Accelerometer", discipline: "Sensors", accept: ["accelerometer"], clues: ["A sensor that, at rest on a table, still reports a nonzero reading.", "It measures proper acceleration, not velocity or position directly.", "A tiny suspended mass shifts slightly whenever the sensor accelerates.", "Every modern smartphone contains several, used for screen rotation among other things.", "A device that measures acceleration forces, typically via the displacement of a small internal mass."], reveal: "A device that measures proper acceleration by sensing the tiny displacement of a small internal mass suspended on flexible supports, converted into an electrical signal. Even sitting perfectly still on a table it reports a nonzero reading — 1g straight up — because it's actually measuring the force needed to hold that mass against gravity." },
  { answer: "Euler-Bernoulli Beam Theory", discipline: "Structural Engineering", accept: ["euler bernoulli beam theory", "euler bernoulli", "beam theory"], clues: ["A simplification that ignores one effect entirely.", "It assumes plane sections remain plane and perpendicular to the neutral axis.", "It breaks down for short stubby members, where Timoshenko's version is needed.", "It gives the classic σ = My/I relationship.", "Named after two mathematicians, one Swiss, one blind for his final years."], reveal: "The classical bending theory relating load, shear, moment and deflection while neglecting shear deformation. That assumption holds well for long slender beams, but short, deep members need Timoshenko theory instead, where shear deformation becomes significant." },
  { answer: "NTU Method", discipline: "Heat Transfer", accept: ["ntu method", "effectiveness ntu method", "heat exchanger effectiveness", "e ntu method"], clues: ["An alternative to LMTD when you don't yet know the outlet temperatures.", "It expresses performance as a ratio bounded between zero and one.", "That ratio compares actual heat transfer against the theoretical maximum possible.", "A dimensionless size parameter — number of transfer units — drives the whole calculation.", "The effectiveness-NTU method rates a heat exchanger by comparing actual to maximum possible heat transfer."], reveal: "A heat exchanger design method that expresses performance as effectiveness — the ratio of actual heat transfer to the theoretical maximum possible — as a function of a dimensionless size parameter called the number of transfer units. It's especially useful over the LMTD method when outlet temperatures aren't already known." },
  { answer: "Big O Notation", discipline: "Software Engineering", accept: ["big o notation", "big o", "asymptotic complexity", "time complexity"], clues: ["It deliberately throws away constants.", "It describes behaviour as the input grows without bound.", "Binary search is log n; bubble sort is n squared.", "It's an upper bound, not an exact count.", "Written with a capital letter and a pair of brackets."], reveal: "Asymptotic notation describing an upper bound on how an algorithm's cost grows with input size. It deliberately throws away constant factors to focus on growth trend, which is why an O(n log n) algorithm eventually beats an O(n²) one no matter how it starts out." },
  { answer: "Thermistor", discipline: "Instrumentation", accept: ["thermistor"], clues: ["A temperature sensor that's really just a resistor with an attitude.", "Its resistance swings dramatically with even small temperature changes.", "Most common types get less resistive as temperature rises, not more.", "It's far more sensitive than a platinum RTD, but far less linear.", "A temperature-sensitive resistor whose resistance changes sharply and predictably with temperature."], reveal: "A temperature-sensitive resistor whose resistance changes sharply and predictably with temperature, far more sensitively than a standard RTD. Most common types are negative-temperature-coefficient, growing less resistive as they warm up — a strong, if nonlinear, response that's ideal for precise measurement over a narrow temperature range." },
  { answer: "Inverse Kinematics", discipline: "Robotics", accept: ["inverse kinematics"], clues: ["The much harder companion problem to a more straightforward calculation.", "You know where you want the hand to end up; you need the joint angles that get it there.", "Multiple different joint configurations can sometimes reach the exact same point.", "Some target points can't be reached by any configuration at all.", "Computing the joint angles needed to place a robot's end effector at a desired position and orientation."], reveal: "The calculation of the joint angles needed to place a robot's end effector at a specific desired position and orientation — the reverse of forward kinematics, and considerably harder to solve. Multiple joint configurations can sometimes reach the very same point, while other points may be entirely unreachable no matter how the joints are arranged." },
  { answer: "Exothermic Reaction", discipline: "Chemistry", accept: ["exothermic reaction", "exothermic"], clues: ["A reaction that gives something away as it proceeds.", "What it releases is energy, in the form of heat.", "Products end up at a lower energy state than the reactants started at.", "Combustion is the most familiar everyday example.", "A chemical reaction that releases heat energy to its surroundings as it proceeds."], reveal: "A chemical reaction that releases heat energy to its surroundings, ending with products at a lower energy state than the reactants it started from. Combustion is the most familiar everyday example, and industrial reactors running strongly exothermic reactions need careful cooling to keep that released heat from running away — the mechanism behind thermal runaway." },
  { answer: "Pipe Wrench", discipline: "Manufacturing", accept: ["pipe wrench", "monkey wrench"], clues: ["A wrench whose jaws bite harder the more force you apply.", "Its teeth are angled so they self-tighten as you pull.", "It's built to grip round stock, not the flat faces of a hex bolt.", "Plumbers reach for it whenever a fitting needs serious twisting force.", "The heavy adjustable wrench with serrated jaws used to turn pipes and fittings."], reveal: "An adjustable wrench with angled, serrated jaws that bite down harder the more torque you apply, designed to grip round pipe rather than flat bolt heads. That self-tightening action is what lets it hold onto smooth, cylindrical stock." },
  { answer: "Compass", discipline: "Electromagnetics", accept: ["compass", "magnetic compass"], clues: ["A navigation tool that works because the whole planet is, in effect, one giant magnet.", "Its needle is really just a small, freely pivoting bar magnet.", "Hold a strong magnet nearby and its reading becomes completely unreliable.", "Sailors relied on it for centuries before satellite navigation ever existed.", "The needle-and-dial instrument that points toward magnetic north using Earth's own magnetic field."], reveal: "A navigation instrument with a freely pivoting magnetized needle that aligns itself with Earth's magnetic field, pointing toward magnetic north. Any nearby magnetic field — including a strong magnet — can throw its reading off." },
  { answer: "Mach Number", discipline: "Aerodynamics", accept: ["mach number", "mach"], clues: ["Another dimensionless ratio.", "Below 0.3 you can usually pretend the fluid is incompressible.", "Near 1 the drag rises sharply — the so-called barrier.", "Above 5 the regime gets a new name entirely.", "Speed divided by local speed of sound."], reveal: "M = v/a — the ratio of flow speed to the local speed of sound, governing compressibility effects. Below about 0.3 the flow can be treated as incompressible, but as it approaches one, compressibility effects and wave drag rise sharply." },
  { answer: "PID Controller", discipline: "Control Systems", accept: ["pid", "pid controller", "proportional integral derivative"], clues: ["Three terms, three tuning knobs, still the workhorse of industry.", "One term reacts to the present, one to the past, one predicts the future.", "Ziegler and Nichols wrote the classic tuning method for it.", "Too much of the second term and you get windup.", "The letters stand for proportional, integral and derivative."], reveal: "A feedback controller acting on the error signal's present value, accumulated history and rate of change. The three gains trade off against each other — push the integral term too hard chasing zero steady-state error and the system starts to oscillate." },
  { answer: "Plumb Bob", discipline: "Civil Engineering", accept: ["plumb bob", "plumb line"], clues: ["A tool that relies on nothing but gravity to define a perfectly straight reference.", "A weighted point hangs freely on a string, always settling into the same orientation.", "Builders have used a version of it, essentially unchanged, for thousands of years.", "It defines a perfectly vertical line, the opposite of what a level checks.", "The weighted tool hung from a string to establish a true vertical line."], reveal: "A pointed weight hung from a string, which gravity pulls into a perfectly vertical line every time. Builders have used the same simple principle for millennia to check or establish true vertical alignment." },
  { answer: "Relay", discipline: "Electrical Engineering", accept: ["relay", "electromechanical relay"], clues: ["A switch that's flipped by electricity instead of by a human hand.", "A small coil, energized, pulls a mechanical contact closed.", "It lets a weak control signal switch a much higher-power circuit safely.", "A car's starter motor is switched on through one of these, not directly by the key.", "An electrically controlled switch that uses a small current to switch a larger one."], reveal: "An electromagnetically operated switch: a small coil, energized by a control signal, pulls a mechanical contact closed to switch a separate, often much higher-power circuit. It lets a weak signal safely control a strong one." },
  { answer: "Ribbon Cable", discipline: "Computer Engineering", accept: ["ribbon cable", "flat cable"], clues: ["A cable whose individual wires are bonded flat, side by side, instead of bundled round.", "Its flat shape makes it easy to route through tight, folded spaces inside a case.", "Older computer hard drives were commonly connected to the motherboard using one.", "You could once count its individual conductors just by looking at the visible colored stripes.", "The flat cable with multiple parallel conductors bonded side by side, once common inside computer cases."], reveal: "A cable with multiple parallel conductors bonded flat, side by side, instead of bundled into a round cable. The flat profile made it easy to fold and route through tight spaces — a common sight connecting older computer drives to their motherboard." },
  { answer: "Takt Time", discipline: "Lean Manufacturing", accept: ["takt time", "takt"], clues: ["A German word borrowed into Japanese, then into English.", "It is set by the customer, not by the factory.", "It is not the same thing as cycle time.", "Line balancing aims to bring every station under it.", "Available production time divided by customer demand."], reveal: "The rate at which units must be produced to meet customer demand: available time divided by demand. It's set entirely by the customer's pace, not the factory's, and line balancing exists specifically to bring every station's cycle time in under it." },
  { answer: "Ductility", discipline: "Materials", accept: ["ductility"], clues: ["A measure of how far a material will go before it snaps.", "It's usually quoted as a percentage elongation at fracture.", "Gold and copper have it in abundance; glass has almost none.", "It's what lets a material be drawn into wire.", "A material's ability to undergo large plastic deformation before fracture."], reveal: "A material's capacity to deform plastically — stretch, bend, or be drawn into wire — before it fractures. It's usually reported as percentage elongation at break, and it tends to trade off against strength: the hardest, strongest alloys are often the least ductile." },
  { answer: "Hydraulic Cylinder", discipline: "Fluid Machinery", accept: ["hydraulic cylinder", "hydraulic ram"], clues: ["A component that turns pressurized fluid into powerful, straight-line motion.", "It relies on a liquid, not a gas, to push its internal piston along.", "It can generate an enormous force from a comparatively modest fluid pressure, given enough piston area.", "An excavator's arm and bucket are both moved by several of these.", "The device that uses pressurized liquid pushing on a piston to produce a powerful linear force."], reveal: "A device that uses pressurized liquid pushing against a piston inside a cylinder to produce a powerful, precisely controlled linear force — because liquids barely compress, it can move an excavator's multi-ton bucket with smooth, direct control." },
  { answer: "Soldering Iron", discipline: "Electronics", accept: ["soldering iron"], clues: ["A tool that joins metal parts by melting a third material, not the parts themselves.", "Its heated tip melts a low-melting-point alloy that bonds two surfaces as it cools.", "Hold it steady on a joint for a second or two, then feed in the wire that melts.", "Every home electronics repair kit eventually needs one plugged in and heating up.", "The heated hand tool used to melt solder and join electronic components together."], reveal: "A heated hand tool that melts solder — a low-melting-point metal alloy — onto a joint, bonding two components electrically and mechanically as it cools. Unlike welding, the parts themselves never melt, only the solder between them." },
  { answer: "Cam", discipline: "Mechanical Design", accept: ["cam", "camshaft lobe"], clues: ["A component whose irregular, non-circular shape is entirely the point.", "As it rotates, a follower riding on its surface rises and falls in a precisely repeating pattern.", "It converts smooth rotary motion into a very specific, controlled up-and-down motion.", "An engine's camshaft uses a row of these to open and close each valve at exactly the right moment.", "A rotating, non-circular component that converts rotary motion into a specific pattern of linear motion."], reveal: "A rotating component with a deliberately non-circular profile, so a follower riding along its surface rises and falls in a precise, repeating pattern as it turns — converting smooth rotation into carefully timed linear motion, as in an engine's valvetrain." },
  { answer: "Choked Flow", discipline: "Fluid Mechanics", accept: ["choked flow", "choking", "critical flow"], clues: ["Lower the downstream pressure further and nothing happens.", "It occurs at a specific area in the passage.", "It is why relief valve sizing has a sonic case.", "At the throat, Mach number reaches exactly one.", "Mass flow becomes independent of downstream conditions."], reveal: "The condition where flow reaches sonic velocity at the throat and mass flow rate no longer increases with reduced back pressure. Once the throat hits Mach one, lowering downstream pressure further does nothing — the flow can't accelerate past the local speed of sound to relieve it." },
  { answer: "Tap and Die", discipline: "Manufacturing", accept: ["tap and die", "tap and die set", "thread tap"], clues: ["A pair of tools that do opposite jobs on opposite kinds of surface.", "One cuts threads inside a hole; the other cuts them onto a rod.", "You'd reach for the first before installing a bolt into a hole that has none.", "Together they let a machinist manufacture their own custom nuts and bolts.", "The tool set used to cut internal and external screw threads by hand."], reveal: "A matched pair of hand tools for cutting screw threads: a tap cuts internal threads inside a drilled hole, and a die cuts matching external threads onto a rod. Together they let a shop create custom-threaded fasteners from plain stock." },
  { answer: "Spectrogram", discipline: "Signal Processing", accept: ["spectrogram"], clues: ["A visualisation that refuses to give up either of two things a plain spectrum sacrifices.", "It shows how frequency content changes over time, not just an average.", "Its two axes are time and frequency; a third dimension is shown as colour or intensity.", "Speech and music analysis both rely on it heavily.", "A visual representation of a signal's frequency content as it changes over time."], reveal: "A visual representation of how a signal's frequency content evolves over time, built by computing short-time Fourier transforms over successive windows and stacking the results with time and frequency as axes and intensity as colour. Unlike a single static spectrum, it captures exactly when each frequency appears and disappears — essential for analysing speech and music." },
  { answer: "Gravity", discipline: "Physics", accept: ["gravity", "gravitational force"], clues: ["A force that acts across empty space, needing no physical contact at all.", "Every object with mass pulls on every other object with mass, however faintly.", "It's the reason a dropped object accelerates downward instead of just sitting still.", "It's what keeps the Moon orbiting Earth instead of drifting off in a straight line.", "The force of attraction that pulls any two masses toward each other."], reveal: "The attractive force between any two masses, growing stronger with more mass and weaker with distance. It's what pulls a dropped object to the ground, and what keeps the Moon curving around Earth instead of flying off in a straight line." },
  { answer: "Distillation", discipline: "Chemical Engineering", accept: ["distillation"], clues: ["A separation method that exploits one simple difference between components.", "That difference is boiling point.", "Heat a mixture and the more volatile component vaporises preferentially.", "Crude oil refineries run entire towers dedicated to it.", "A separation process exploiting differences in volatility to separate components of a liquid mixture."], reveal: "A separation process that exploits differences in volatility between components of a liquid mixture — heat it, and the more volatile component vaporises preferentially, leaving the less volatile behind. Crude oil refineries run entire towers built around exactly this principle, splitting one input into everything from light gases to heavy asphalt." },
  { answer: "Momentum", discipline: "Dynamics", accept: ["momentum"], clues: ["A quantity that's always conserved in a closed system, no exceptions.", "It's simply the product of an object's mass and its velocity.", "A heavy truck moving slowly can have just as much of it as a light car moving fast.", "It's what makes a moving object genuinely hard to stop, beyond just its weight.", "Mass times velocity — a measure of how hard it is to stop a moving object."], reveal: "The product of an object's mass and velocity, conserved overall in any closed system with no external forces. It's why a slow, heavy truck can be just as hard to stop as a fast, light car — the mass compensates for the speed." },
  { answer: "Flip-Flop", discipline: "Digital Logic", accept: ["flip flop", "d flip flop", "bistable latch"], clues: ["A circuit with exactly two stable states, and nothing in between.", "It's the basic unit of memory in digital hardware.", "It only changes state on the edge of a clock signal.", "Chain enough of them together and you get a register.", "A bistable digital circuit that stores one bit, changing state only on a clock edge."], reveal: "A bistable digital circuit that stores a single bit of information, holding its state until a clock edge tells it to update. Chaining flip-flops together is literally how registers, counters and every other piece of digital memory are built." },
  { answer: "Solar Cell", discipline: "Renewable Energy", accept: ["solar cell", "photovoltaic cell"], clues: ["A component that converts light directly into electricity, with no moving parts at all.", "It relies on the same underlying physical effect used to name a related phenomenon in electrical engineering.", "Wire many of them together on a panel and their small individual voltages add up usefully.", "It generates power only while light is actually striking its surface.", "The semiconductor device that directly converts sunlight into electrical current."], reveal: "A semiconductor device that converts sunlight directly into electrical current via the photovoltaic effect, with no moving parts. Individually it produces only a small voltage, which is why panels wire many of them together." },
  { answer: "Coefficient of Performance", discipline: "Thermodynamics", accept: ["coefficient of performance", "cop"], clues: ["A refrigerator's answer to efficiency, though it can exceed 100%.", "It's a ratio, but not one bounded by one like a heat engine's efficiency.", "A higher value means more cooling for the same electrical input.", "It compares heat moved against work supplied to move it.", "Desired heating or cooling effect divided by the work input required to achieve it."], reveal: "The ratio of useful heating or cooling delivered to the work input required to achieve it, used to rate refrigerators, air conditioners and heat pumps. Unlike a heat engine's efficiency, it can exceed one — even one hundred percent — because it's counting heat moved, not heat created." },
  { answer: "Failure Mode and Effects Analysis", discipline: "Reliability Engineering", accept: ["fmea", "failure mode and effects analysis", "failure modes and effects analysis"], clues: ["A structured, bottom-up workshop exercise.", "It's proactive: you do it before anything has failed.", "Three ratings get multiplied together.", "Those are severity, occurrence and detection.", "The product is called a risk priority number."], reveal: "A systematic method identifying potential failure modes, their effects, and prioritising them by risk priority number. Severity, occurrence and detection ratings are each scored and multiplied together, giving a team a ranked list of what to fix first — before anything fails." },
  { answer: "LIDAR", discipline: "Sensors", accept: ["lidar", "light detection and ranging"], clues: ["A ranging technology using pulses of light instead of sound or radio.", "It measures distance from the time a pulse takes to bounce back.", "Spin the emitter and detector together and you get a full 360-degree map.", "Self-driving cars rely on it heavily to build a 3D picture of their surroundings.", "A remote sensing method that measures distance by timing the return of reflected laser pulses."], reveal: "A remote sensing method that measures distance by timing how long a laser pulse takes to reflect off a target and return, converting that time-of-flight directly into range. Spinning the emitter and detector together builds a dense 3D point cloud of the surroundings, which is exactly why it's central to how self-driving cars and robots perceive the world around them." },
  { answer: "Fracture Toughness", discipline: "Solid Mechanics", accept: ["fracture toughness", "kic", "k1c"], clues: ["It has slightly odd units: MPa times root metres.", "It is a material property, unlike stress intensity itself.", "Thicker specimens give lower values until plane strain is reached.", "Compare it against K to decide whether a crack will run.", "Its plane-strain symbol is K_IC."], reveal: "The critical stress intensity at which an existing crack propagates unstably — a material's resistance to fracture. Compare it against the stress intensity a crack actually experiences and you get a direct go/no-go answer on whether that crack will run." },
  { answer: "Endurance Limit", discipline: "Materials", accept: ["endurance limit", "fatigue limit"], clues: ["A stress level below which something essentially never happens.", "Steel has one; most aluminium alloys do not.", "It's read as the flat asymptote at the right side of an S-N curve.", "Design for infinite life means staying beneath it.", "Below this cyclic stress amplitude, a part can theoretically survive infinite load cycles."], reveal: "The cyclic stress amplitude below which a material can theoretically sustain an infinite number of load cycles without fatigue failure. Not every material has one — steels typically show a clear endurance limit, while aluminium alloys keep gradually weakening no matter how low the stress, so their fatigue life is always finite." },
  { answer: "Orbital Velocity", discipline: "Aerospace Engineering", accept: ["orbital velocity", "orbital speed"], clues: ["The speed at which falling and curving away from the ground balance perfectly.", "Fall short of it and you come back down; exceed it enough and you leave entirely.", "It's lower for a higher orbit, not higher.", "The International Space Station manages roughly 7.66 km/s to maintain it.", "The speed at which a body's forward motion balances gravitational pull, maintaining a stable circular orbit."], reveal: "The speed at which an object's forward motion curves it around a body at exactly the same rate gravity pulls it downward, maintaining a stable circular orbit rather than falling back or flying away. Counterintuitively, it's lower for higher orbits — gravity's pull is weaker further out, so less speed is needed to balance it." },
  { answer: "Composite Beam", discipline: "Structural Engineering", accept: ["composite beam", "composite steel concrete beam", "steel concrete composite"], clues: ["Two different structural materials, connected to act as one.", "A steel section and a concrete slab are the classic pairing.", "Shear studs are what make the two actually work together, not just sit stacked.", "Without that connection, the two layers would slip past each other under load.", "A beam combining a steel section and a concrete slab, mechanically connected to act as a single structural unit."], reveal: "A beam combining a steel section and a concrete slab, mechanically connected — typically by shear studs welded to the steel — so the two act together as a single, stiffer structural unit rather than two independent layers. Without that connection the slab and beam would simply slip past each other under load, each carrying far less than the combined section can." },
  { answer: "Microscope", discipline: "Instrumentation", accept: ["microscope"], clues: ["An instrument that makes something too small to see, briefly, the biggest thing in the room.", "Multiple lenses stack together to multiply the magnification of a single lens alone.", "It's how the cell was first ever observed, back in the 17th century.", "You'd use one to examine a thin slice on a glass slide, not a distant object.", "The instrument with lenses used to magnify objects too small to see with the naked eye."], reveal: "An instrument that uses one or more lenses to magnify objects far too small to see with the naked eye. Stacking lenses multiplies their individual magnification, which is how early microscopes first revealed the existence of cells." },
  { answer: "Gradient Descent", discipline: "Machine Learning", accept: ["gradient descent"], clues: ["An optimisation method used to train nearly every modern machine learning model.", "It repeatedly nudges parameters in the direction that reduces error the fastest.", "That direction is found from the slope, or gradient, of a loss function.", "Set its step size too large and it can overshoot and never converge.", "An iterative optimisation algorithm that adjusts parameters in the direction of steepest decrease of a loss function."], reveal: "An iterative optimisation algorithm that repeatedly adjusts a model's parameters in the direction of steepest decrease of its loss function, gradually working its way toward a minimum. The step size, or learning rate, is critical — set it too large and the process can overshoot and diverge instead of converging." },
  { answer: "Countersink", discipline: "Manufacturing", accept: ["countersink", "countersink bit"], clues: ["A tool that cuts a cone, not a cylinder.", "It makes room for a screw head to sit flush with the surface.", "Skip it and a flat-headed screw will stick up proud of the material.", "Run it before driving in a screw with an angled underside.", "The conical cutting bit used to recess a screw head flush with the surface."], reveal: "A conical cutting tool that widens the top of a drilled hole into a cone-shaped recess, letting a flat or oval screw head sit flush with — or below — the surface instead of standing proud." },
  { answer: "Crankshaft", discipline: "Mechanical Design", accept: ["crankshaft", "crank shaft"], clues: ["A shaft with offset sections that make it possible to convert between two very different kinds of motion.", "It turns a piston's straight back-and-forth push into smooth, continuous rotation.", "A connecting rod links each piston to one of its offset throws.", "It's the component that ultimately spins to send power out of a piston engine.", "The shaft with offset throws that converts a piston's back-and-forth motion into rotary motion."], reveal: "A shaft with offset sections, called throws, connected to each piston by a connecting rod, converting the piston's linear back-and-forth motion into the crankshaft's continuous rotation — the final mechanical output of a piston engine." },
  { answer: "Eddy Currents", discipline: "Electromagnetics", accept: ["eddy currents", "eddy current"], clues: ["They circulate in loops inside the material itself.", "They are a loss mechanism in transformers and motors.", "Laminating the core and adding silicon reduces them.", "They also make useful non-contact brakes and metal detectors.", "Induced by a changing magnetic field in a conductor."], reveal: "Circulating currents induced within a conductor by a changing magnetic field, causing resistive heating losses. In transformer cores they're pure loss, countered by lamination and silicon alloying, but the same effect is put to deliberate use in non-contact brakes and metal detectors." },
  { answer: "Critical Mass", discipline: "Nuclear Engineering", accept: ["critical mass"], clues: ["A threshold quantity, below which a certain process simply can't sustain itself.", "It's the minimum amount of fissile material needed for a chain reaction to become self-sustaining.", "Below it, too many neutrons escape before triggering a further split.", "Shape and surrounding material both affect the exact threshold, not just raw quantity.", "The minimum amount of fissile material required to sustain a self-propagating nuclear chain reaction."], reveal: "The minimum amount of fissile material required for a nuclear chain reaction to become self-sustaining, where each fission event reliably triggers at least one more. Below that threshold, too many free neutrons escape the material entirely before they can strike another nucleus, and the reaction simply fizzles out rather than sustaining itself." },
  { answer: "Beaker", discipline: "Chemistry", accept: ["beaker"], clues: ["Lab glassware whose printed markings are approximate, not precise.", "Its flat base and wide mouth make it good for stirring and pouring, not exact measurement.", "A small spout molded into its rim makes pouring liquid out easier.", "If you need an exact volume, you'd reach for a graduated cylinder instead.", "The wide, flat-bottomed glass container with a pouring spout used to mix and hold lab liquids."], reveal: "A wide, flat-bottomed glass container with a pouring spout, used to hold, mix, and heat liquids. Its volume markings are approximate — for a precise measurement, chemists reach for a graduated cylinder instead." },
  { answer: "Atterberg Limits", discipline: "Geotechnical Engineering", accept: ["atterberg limits"], clues: ["A set of moisture-content boundaries that describe how a fine-grained soil behaves.", "They mark the transitions between solid, plastic and liquid states.", "Two of the limits, subtracted from each other, give a soil's plasticity index.", "A Swedish agricultural scientist developed them, originally for a completely different purpose.", "The water contents marking the boundaries between solid, plastic and liquid behaviour in fine-grained soil."], reveal: "The specific water contents marking the boundaries between solid, plastic and liquid behaviour in a fine-grained soil, most commonly clay. The gap between two of these limits — the liquid limit and the plastic limit — defines the plasticity index, a key number geotechnical engineers use to classify how a soil will behave under load." },
  { answer: "Moore's Law", discipline: "Electronics", accept: ["moores law", "moore law"], clues: ["It is an observation and a business target, not a law of physics.", "First stated in a magazine article in 1965.", "The doubling period was later revised to about two years.", "It concerns transistor density on an integrated circuit.", "Named after a co-founder of Intel."], reveal: "The observation that the number of transistors on a chip doubles roughly every two years. It was never a physical law but a self-fulfilling industry roadmap, and its pace has visibly slowed as transistor features approach atomic scales." },
  { answer: "Nyquist Stability Criterion", discipline: "Control Systems", accept: ["nyquist stability criterion", "nyquist criterion", "nyquist plot"], clues: ["It answers a yes/no question by drawing a picture.", "The picture is a contour plotted in the complex plane.", "You count encirclements of one specific point.", "That point sits at minus one on the real axis.", "It tells you whether a closed-loop system will be stable."], reveal: "A graphical test using encirclements of −1 in the complex plane to determine closed-loop stability. It works even for systems whose open-loop transfer function has right-half-plane poles, a case simpler frequency-response checks can't handle." },
  { answer: "Vernier Calipers", discipline: "Metrology", accept: ["vernier calipers", "calipers", "caliper"], clues: ["A measuring tool with two separate scales that work together for extra precision.", "A secondary sliding scale lets you read a fraction of the smallest mark on the main scale.", "Its jaws can measure a diameter from the outside, or a hole's diameter from the inside.", "It reads to a level of precision a simple ruler could never match.", "The precision tool with sliding jaws and a secondary scale, used to measure outside, inside, or depth dimensions."], reveal: "A precision measuring tool with sliding jaws and a secondary sliding scale that lets a reading be taken to a fraction of the main scale's smallest division. It can measure an outside diameter, an inside diameter, or a depth, all with one tool." },
  { answer: "Harvard Architecture", discipline: "Computer Engineering", accept: ["harvard architecture"], clues: ["A design philosophy usually introduced as the alternative to a more famous one.", "It keeps two things separate that its rival keeps together.", "Instructions and data get their own dedicated memory and their own dedicated bus.", "Many microcontrollers and digital signal processors use exactly this arrangement.", "A computer architecture with physically separate memory and buses for instructions and data."], reveal: "A computer architecture that keeps program instructions and data in physically separate memories, each with its own dedicated bus, unlike the shared arrangement of a Von Neumann machine. Because a processor can fetch an instruction and a piece of data at the same instant, it's commonly used in microcontrollers and digital signal processors where predictable, fast access matters." },
  { answer: "Navier-Stokes Equations", discipline: "Fluid Mechanics", accept: ["navier stokes", "navierstokes"], clues: ["A set of coupled nonlinear partial differential equations.", "They are essentially Newton's second law written for a fluid element.", "Every CFD solver on the planet is trying to approximate them.", "Proving smooth solutions always exist in three dimensions is a Millennium Prize Problem.", "Named for a French engineer and an Irish-born British physicist."], reveal: "The governing equations of viscous fluid motion, expressing momentum conservation for a continuum fluid. They combine pressure, viscous and inertial forces into one nonlinear system that, outside a handful of simplified cases, can only be solved numerically." },
  { answer: "RC Time Constant", discipline: "Electrical Engineering", accept: ["rc time constant", "time constant", "rc circuit"], clues: ["A single number that characterises how fast a circuit responds.", "It's simply a resistance multiplied by a capacitance.", "After one of these, a charging capacitor reaches about 63% of its final value.", "After five of these, the circuit is considered essentially settled.", "τ = RC — the time it takes a capacitor's voltage to rise or fall by roughly 63% toward its final value."], reveal: "The characteristic time τ = RC that governs how quickly voltage across a charging or discharging capacitor approaches its final value, rising or falling about 63% of the remaining distance every τ. After roughly five time constants the circuit is considered to have essentially settled." },
  { answer: "Biocompatibility", discipline: "Biomedical Engineering", accept: ["biocompatibility"], clues: ["A property that decides whether the body accepts or attacks something foreign inside it.", "It's not one fixed quality — it depends heavily on where in the body a material ends up.", "Titanium is prized in implants largely because of how well it satisfies this requirement.", "A poor showing here can trigger inflammation, rejection or worse.", "The ability of a material to perform its intended function inside the body without triggering an adverse immune response."], reveal: "The ability of a material to perform its intended function inside a living body without triggering an adverse immune response, inflammation, or rejection. It's highly context-dependent — a material perfectly safe on skin can be entirely unsuitable once implanted, which is exactly why titanium's exceptional performance in this regard makes it a mainstay of surgical implants." },
  { answer: "Inclined Plane", discipline: "Statics", accept: ["inclined plane", "ramp"], clues: ["Possibly the simplest machine of all, requiring no moving parts whatsoever.", "It lets you trade distance for a reduction in required force.", "A ramp is the everyday, familiar form of it.", "A screw is really just this simple machine, wrapped around a cylinder.", "A flat surface set at an angle, used to raise a load with less force over a longer distance."], reveal: "A flat surface set at an angle, letting a load be raised using less force than lifting it straight up, at the cost of moving it a longer distance. It's the simplest machine of all, requiring no moving parts, and a screw is really nothing more than this same principle wrapped helically around a cylinder." },
  { answer: "CNC Machining", discipline: "Manufacturing", accept: ["cnc machining", "computer numerical control"], clues: ["A manufacturing process guided entirely by code, not by a human hand on a dial.", "It removes material rather than adding or forming it.", "A cutting tool follows a precisely programmed toolpath through the raw stock.", "It trades the flexibility of manual machining for repeatability and precision.", "A subtractive manufacturing process where computer-controlled tools cut away material to shape a part."], reveal: "A subtractive manufacturing process in which computer-controlled cutting tools follow a precisely programmed toolpath, removing material from raw stock until the finished part shape remains. Trading a human operator's hand for programmed code gives up some manual flexibility in exchange for remarkable repeatability and precision, part after part." },
  { answer: "Amplitude Modulation", discipline: "Signal Processing", accept: ["amplitude modulation", "am"], clues: ["A way to piggyback a low-frequency signal onto a high-frequency carrier.", "The information rides entirely in the envelope, not the carrier frequency itself.", "It's simple to demodulate, which is why cheap radio receivers use it.", "It's more vulnerable to noise than its frequency-based rival.", "A modulation scheme where a signal is encoded by varying the amplitude of a carrier wave."], reveal: "A modulation scheme that encodes a signal by varying the amplitude of a high-frequency carrier wave, so the information rides entirely in the carrier's changing envelope. It's simple and cheap to demodulate, which kept it popular for broadcast radio, but that same simplicity makes it far more vulnerable to noise than frequency modulation." },
  { answer: "Convective Heat Transfer Coefficient", discipline: "Heat Transfer", accept: ["convective heat transfer coefficient", "convection coefficient", "film coefficient", "heat transfer coefficient"], clues: ["A number that stands in for a very messy fluid-mechanics problem.", "It's higher for a fan blowing across a surface than for still air.", "It multiplies a temperature difference to give heat flux.", "It appears buried inside the Nusselt number's definition.", "q = h(T_s − T_∞) — the proportionality constant linking convective heat flux to a temperature difference."], reveal: "The empirical proportionality constant linking convective heat flux from a surface to the temperature difference driving it, symbol h. It quietly absorbs all the complexity of the underlying fluid flow — velocity, turbulence, fluid properties — into one number that's usually measured or correlated rather than derived from first principles." },
  { answer: "Garbage Collection", discipline: "Computer Science", accept: ["garbage collection", "gc"], clues: ["A form of automatic memory management, freeing programmers from a tedious chore.", "It reclaims memory that a program can no longer reach at all.", "Reference counting and mark-and-sweep are two classic approaches to it.", "It can introduce unpredictable pauses, which matters a great deal in real-time systems.", "The automatic process of reclaiming memory occupied by objects a program no longer references."], reveal: "The automatic process of identifying and reclaiming memory occupied by objects a program can no longer reach, freeing developers from having to track and release every allocation by hand. It isn't free, though — the pauses it can introduce while scanning memory are why real-time and latency-sensitive systems often avoid it or manage memory manually instead." },
  { answer: "Reinforced Concrete", discipline: "Civil Engineering", accept: ["reinforced concrete", "rebar", "rc concrete"], clues: ["It pairs two materials specifically to cover for each other's weaknesses.", "One material handles compression; the other handles tension.", "Steel bars are embedded before the second material is poured around them.", "The two happen to expand and contract with temperature at almost the same rate.", "Concrete embedded with steel bars, since concrete is strong in compression but weak in tension."], reveal: "Concrete embedded with steel reinforcing bars, pairing concrete's strength in compression with steel's strength in tension so the composite handles both. It works as well as it does partly by coincidence — steel and concrete expand and contract with temperature at almost exactly the same rate, so thermal stresses between them stay small." },
  { answer: "Voltage Regulator", discipline: "Electrical Power", accept: ["voltage regulator"], clues: ["A component whose entire job is to hold a value steady, even as conditions shift.", "It keeps its output constant even as the input voltage or the load current varies.", "Without one, a car's electronics would be at the mercy of the alternator's fluctuating output.", "Phone chargers rely on one internally to deliver a clean, steady 5 volts.", "The component that maintains a constant output voltage despite changes in input or load."], reveal: "A component that maintains a steady, constant output voltage even as the input voltage or the connected load current fluctuates — the reason a phone charger delivers a clean, stable voltage no matter how noisy the wall power feeding it is." },
  { answer: "Tolerance Stack-Up", discipline: "Mechanical Design", accept: ["tolerance stack up", "tolerance stackup", "tolerance analysis", "stack up analysis"], clues: ["The reason an assembly fails even though every part passed inspection.", "The worst-case method is conservative and often uneconomic.", "The statistical method uses root-sum-square instead.", "You build a chain of dimensions from datum to feature.", "It predicts the accumulated variation across an assembly."], reveal: "Analysis of how individual part tolerances accumulate across an assembly to affect a critical dimension. A worst-case analysis simply adds every tolerance together and is safe but often needlessly conservative, while a statistical root-sum-square approach is more realistic." },
  { answer: "Ideal Gas Law", discipline: "Thermodynamics", accept: ["ideal gas law", "pv nrt", "perfect gas law"], clues: ["An equation of state that is wrong everywhere but useful almost everywhere.", "It breaks down at high pressure and near condensation.", "Van der Waals wrote a correction to it.", "Four variables and one constant.", "PV = nRT."], reveal: "PV = nRT — relating pressure, volume, temperature and quantity for a gas with no intermolecular forces. It's a convenient fiction: real gases deviate from it at high pressure and near condensation, which corrections like the Van der Waals equation try to fix." },
  { answer: "Five Whys", discipline: "Quality Engineering", accept: ["five whys", "5 whys"], clues: ["A root-cause technique that's disarmingly simple in concept.", "You keep asking the same one-word question, repeatedly.", "Five is a guideline, not a strict rule — sometimes fewer or more are needed.", "It was developed within the Toyota Production System.", "A root-cause analysis technique of repeatedly asking 'why' until the underlying cause of a problem is found."], reveal: "A root-cause analysis technique, developed within the Toyota Production System, that simply asks 'why' repeatedly — typically around five times — peeling back layer after layer of symptom until the true underlying cause is exposed. The number five is a guideline rather than a strict rule; some problems need fewer questions, others need considerably more." },
  { answer: "Vapor-Liquid Equilibrium", discipline: "Chemical Engineering", accept: ["vapor liquid equilibrium", "vle", "vapour liquid equilibrium"], clues: ["A state where two phases coexist without either one winning out.", "Molecules are constantly evaporating and condensing, at exactly matched rates.", "It's the fundamental data underlying every distillation calculation.", "Raoult's law offers one simple, idealised way to predict it.", "The condition where a liquid and its vapour coexist in balance, with equal rates of evaporation and condensation."], reveal: "The condition in which a liquid and its vapour coexist in balance, with molecules evaporating and condensing at exactly matched rates so neither phase grows at the other's expense. It's the fundamental data that every distillation calculation is built on, and Raoult's law offers the simplest idealised way to predict it for a mixture." },
  { answer: "Potentiometer", discipline: "Electronics", accept: ["potentiometer", "pot"], clues: ["A component that turns a physical position into a variable electrical value.", "Inside, a sliding contact, called a wiper, moves across a resistive strip.", "Turn its knob and you're really just adjusting how much resistance is in the circuit.", "It's the component behind almost every old-school volume knob.", "The variable resistor with a rotating or sliding wiper, used to adjust things like volume."], reveal: "A variable resistor whose sliding or rotating contact — the wiper — moves across a resistive strip, letting the resistance (and often the output voltage) be adjusted mechanically. It's the component behind a classic analog volume knob." },
  { answer: "Technology Readiness Level", discipline: "Systems Engineering", accept: ["technology readiness level", "trl"], clues: ["A scale from 1 to 9, originally created by NASA.", "Level 1 is little more than an idea in a paper.", "Level 6 involves a demonstration in a relevant environment.", "Level 9 means flight-proven, in operational use.", "Funding bodies now use it to gate investment decisions."], reveal: "A 1–9 scale assessing the maturity of a technology from basic principles to proven operational use. It runs from an idea on paper at level one, through a demonstration in a relevant environment at level six, to flight-proven operational use at level nine." },
  { answer: "Wing Aspect Ratio", discipline: "Aerodynamics", accept: ["wing aspect ratio", "aspect ratio"], clues: ["A simple ratio that says a great deal about a wing's efficiency.", "It compares a wing's span against its average chord.", "A glider's long, narrow wing sits at one extreme of the scale.", "A fighter jet's short, stubby wing sits at the other.", "Higher values generally mean lower induced drag, at the cost of structural weight and manoeuvrability."], reveal: "The ratio of a wing's span to its average chord, a single number that says a great deal about how it will perform. A long, narrow, high-aspect-ratio wing — like a glider's — generates lift with less induced drag, while a short, stubby, low-aspect-ratio wing trades that efficiency for structural strength and manoeuvrability." },
  { answer: "Convolutional Neural Network", discipline: "Deep Learning", accept: ["convolutional neural network", "cnn"], clues: ["A network architecture built specifically with grid-like data in mind, such as images.", "It slides small learned filters across the input rather than connecting every pixel to every neuron.", "That sliding operation is where the architecture gets its name.", "Early layers tend to detect simple features like edges; later layers detect far more complex ones.", "A neural network architecture using learned convolutional filters to extract spatial features, especially from images."], reveal: "A neural network architecture that slides small, learned filters across an input — typically an image — to detect spatial patterns, rather than connecting every input pixel independently to every neuron. Early layers tend to learn simple features like edges, while deeper layers combine those into increasingly complex, abstract shapes." },
  { answer: "Voltage", discipline: "Electrical Engineering", accept: ["voltage", "electric potential difference"], clues: ["A quantity best understood as a difference between two points, not a property of one.", "Batteries are commonly rated by this in volts, printed right on the label.", "It's the electrical 'pressure' that pushes charge around a circuit.", "Double it across a fixed resistance and the current through that resistance doubles too.", "The electrical potential difference that drives current through a circuit."], reveal: "The difference in electric potential between two points, which drives current to flow between them when a conductive path connects them. It's the electrical 'pressure' behind the flow — measured in volts, and printed on every battery." },
  { answer: "Router", discipline: "Manufacturing", accept: ["router", "wood router"], clues: ["A high-speed spinning tool that hollows out material rather than slicing straight through it.", "Change its bit and it can cut a groove, a curve, or an edge profile.", "Woodworkers use it to cut the decorative edge on a tabletop.", "Not to be confused with the box that sends your Wi-Fi around the house.", "The handheld power tool with a spinning bit used to hollow out and shape wood."], reveal: "A handheld or table-mounted power tool that spins a cutting bit at high speed to hollow out, groove, or profile the edges of wood and other materials. Swapping the bit changes the cut from a simple channel to a decorative edge." },
  { answer: "Prism", discipline: "Optics", accept: ["prism", "optical prism"], clues: ["A transparent object whose flat, angled faces are the whole point of its shape.", "It splits a single beam of white light into a visible spread of colors.", "Each color inside it bends by a slightly different amount as it passes through.", "Pink Floyd famously put one on an album cover, refracting a single beam into a rainbow.", "The transparent, angled block of glass that splits white light into a spectrum of colors."], reveal: "A transparent, angle-faced block, usually glass, that splits white light into its component colors because each wavelength refracts by a slightly different amount passing through it — the physics behind that iconic rainbow-through-triangle image." },
  { answer: "Rust", discipline: "Materials", accept: ["rust", "iron oxide"], clues: ["A reddish-brown compound that forms specifically from one metal, not metals in general.", "It's a particular kind of corrosion, specific to iron and its alloys like steel.", "Chemically, it's an oxide — the metal has bonded with oxygen from the air or water.", "Leave an unprotected steel tool out in the rain and this coating soon appears.", "The reddish-brown flaky coating that forms on iron or steel exposed to moisture and oxygen."], reveal: "Iron oxide — the reddish-brown, flaky compound that forms when iron or steel reacts with oxygen in the presence of moisture. It's a specific case of the broader phenomenon of corrosion, unique to iron and its alloys." },
  { answer: "Signal-to-Noise Ratio", discipline: "Instrumentation", accept: ["signal to noise ratio", "snr", "s n ratio"], clues: ["Usually quoted in decibels.", "Averaging N samples improves it by root N.", "Shielding, grounding and filtering all exist to raise it.", "Below about 1 you can no longer distinguish what you're measuring.", "It's the ratio of wanted signal power to unwanted noise power."], reveal: "The ratio of desired signal power to background noise power, typically expressed in decibels. Averaging N independent samples improves it by a factor of root N, the mathematical reason repeated measurements can pull a signal out of noise that would otherwise bury it." },
  { answer: "Damping Ratio", discipline: "Vibrations", accept: ["damping ratio", "damping coefficient"], clues: ["A dimensionless number that decides how oscillation dies out.", "Below one, a system overshoots and rings before settling.", "Above one, it creeps back to rest without ever overshooting.", "Exactly one is the fastest return to rest without any overshoot at all.", "That special value is called critical damping."], reveal: "A dimensionless measure of how quickly oscillation decays after a system is disturbed, relative to its natural frequency. A value below one leaves the system underdamped and ringing, above one leaves it sluggishly overdamped, and exactly one — critical damping — returns it to rest in the shortest possible time with no overshoot." },
  { answer: "Cavitation", discipline: "Fluid Machinery", accept: ["cavitation"], clues: ["It sounds like gravel rattling through the machine.", "It happens when local pressure drops below a critical threshold.", "It pits and erodes impellers and propeller blades.", "NPSH margin is specified precisely to avoid it.", "Vapour bubbles form, then collapse violently."], reveal: "Formation and violent collapse of vapour bubbles when local pressure falls below the fluid's vapour pressure. Each collapse sends out a tiny, intensely localised shockwave, and enough of them will pit and erode even hardened metal impellers over time." },
  { answer: "Micrometer", discipline: "Metrology", accept: ["micrometer", "micrometer screw gauge"], clues: ["A precision tool that turns a rotation into an extremely fine linear measurement.", "A calibrated screw thread advances its measuring face by a tiny, exact amount per turn.", "Machinists reach for it whenever a job's tolerance is tighter than calipers can reliably hold.", "It can typically resolve a measurement down to a thousandth of a millimeter or finer.", "The precision tool using a calibrated screw thread to measure very small dimensions extremely accurately."], reveal: "A precision measuring tool using a calibrated screw thread, where each turn advances the measuring face by a known, tiny amount — letting it resolve dimensions far more finely than calipers, often to a thousandth of a millimeter." },
  { answer: "Van de Graaff Generator", discipline: "Electromagnetics", accept: ["van de graaff generator", "van de graaff"], clues: ["A machine that builds up an enormous static charge using nothing but friction and a moving belt.", "A metal dome at the top accumulates charge carried up from a motor-driven belt below.", "Touch its charged dome and, if you're insulated, your hair stands straight up.", "It's a staple of physics demonstrations, capable of producing sparks several feet long.", "The classic science-demo machine with a metal dome that builds up huge static charges."], reveal: "An electrostatic machine that uses a motor-driven belt to carry charge up to a hollow metal dome, building an enormous static charge over time. It's the classic physics-class demo that makes a volunteer's hair stand on end." },
  { answer: "NAND Gate", discipline: "Digital Logic", accept: ["nand gate", "nand"], clues: ["A single gate that can, all by itself, build every other gate in existence.", "Its output is the opposite of a much simpler, more obvious gate's.", "It's high unless every one of its inputs is high.", "Manufacturers favour it because a chip needs to master only one gate design.", "A universal logic gate whose output is the inverse of AND — high unless all inputs are high."], reveal: "A logic gate whose output is simply the inverse of AND — high unless every input is high — but one with a special property: any other logic function, from OR to XOR to a full adder, can be built using only NAND gates. That universality is exactly why chip manufacturers can standardise fabrication around a single gate design." },
  { answer: "Degrees of Freedom", discipline: "Robotics", accept: ["degrees of freedom", "dof"], clues: ["A count of the independent ways something is free to move.", "A point moving in 3D space alone already has three of them.", "Add the ability to rotate about each axis and the count climbs further.", "A typical industrial robotic arm is built with exactly six.", "The number of independent parameters needed to fully define a system's position and orientation."], reveal: "The number of independent parameters needed to fully describe a system's position and orientation in space. A rigid body moving freely in 3D has six — three for position along each axis, three for rotation about each — which is exactly why a typical industrial robot arm is built with six joints to match." },
  { answer: "Pressure", discipline: "Fluid Mechanics", accept: ["pressure"], clues: ["A quantity defined as force spread out over an area, not force alone.", "Push the same force through a smaller area and this quantity rises sharply.", "It's why a sharp needle penetrates skin far more easily than a blunt finger with the same push.", "Deep-sea divers must account for how quickly it climbs with depth.", "Force divided by the area it's spread across."], reveal: "Force divided by the area over which it acts. Concentrating the same force onto a smaller area — like a needle's tip — dramatically increases it, which is exactly why sharp points penetrate so much more easily than blunt ones." },
  { answer: "Alloy", discipline: "Metallurgy", accept: ["alloy"], clues: ["A material engineered by deliberately mixing, not accidentally contaminating.", "It's a combination of a metal with one or more other elements, often another metal.", "The blend is chosen specifically to improve on a pure metal's strength, hardness or corrosion resistance.", "Steel, itself a mixture of iron and carbon, is one of the most common examples.", "A mixture of a metal with one or more other elements, engineered to improve its properties."], reveal: "A material made by deliberately combining a metal with one or more other elements — often another metal — to improve on the pure metal's strength, hardness, or corrosion resistance. Steel, iron blended with carbon, is the most familiar example." },
  { answer: "Hall Effect", discipline: "Sensors", accept: ["hall effect", "hall effect sensor", "hall sensor"], clues: ["Discovered in 1879, long before it was useful.", "It needs both a current and a perpendicular magnetic field.", "The result is a small voltage across the third axis.", "It gives you non-contact position and current sensing.", "It's how a brushless motor knows where its rotor is."], reveal: "A voltage generated across a current-carrying conductor when placed in a perpendicular magnetic field. Because the resulting voltage tracks the magnetic field with no physical contact needed, it's become the standard way to sense position and current without a wear-prone linkage." },
  { answer: "Method of Joints", discipline: "Structural Engineering", accept: ["method of joints", "joint method", "truss analysis"], clues: ["A technique for solving a structure made entirely of two-force members.", "You work through it one pin at a time.", "At each point, the forces in every connected member must sum to zero.", "It assumes every member carries only axial load — pure tension or compression.", "It's the standard hand-calculation method for analysing a statically determinate truss."], reveal: "A technique for finding the internal force in every member of a truss by applying equilibrium at each pin joint in turn, one at a time. It relies on the assumption that every member is a two-force member carrying only axial tension or compression, with no bending at all." },
  { answer: "Angle Grinder", discipline: "Manufacturing", accept: ["angle grinder", "grinder"], clues: ["A handheld power tool whose spinning disc is perpendicular to the handle, not in line with it.", "Swap the disc and it goes from cutting metal to polishing it.", "A shower of sparks is a normal side effect of using it on steel.", "You'll see one used to cut through rebar or smooth a rough weld.", "The handheld power tool with a spinning disc used to cut, grind or polish metal."], reveal: "A handheld power tool spinning an abrasive or cutting disc at a right angle to its handle. Swapping the disc changes the job entirely, from slicing through metal stock to grinding down a rough weld or polishing a surface." },
  { answer: "Quantisation Error", discipline: "Signal Processing", accept: ["quantisation error", "quantization error", "quantisation noise", "quantization noise"], clues: ["It exists no matter how good your converter is.", "It is bounded by half of one step.", "Add a bit of resolution and it halves.", "Deliberately adding noise — dither — can improve perceived results.", "It's the difference between the true analogue value and its digital code."], reveal: "The unavoidable difference between an analogue value and its nearest digital representation, bounded by half an LSB. It exists no matter how good the converter is, though adding a bit of resolution halves it, and injecting a little dither noise can improve the perceived result." },
  { answer: "Stefan-Boltzmann Law", discipline: "Heat Transfer", accept: ["stefan boltzmann law", "stefan boltzmann"], clues: ["It concerns the third mode of heat transfer.", "It needs no medium at all.", "The dependence on temperature is startlingly strong.", "Emissivity scales it down for real, non-ideal surfaces.", "Power goes with absolute temperature to the fourth power."], reveal: "Radiated power per unit area from a black body is σT⁴, scaled by emissivity for real surfaces. The fourth-power dependence is startlingly strong — double the absolute temperature and radiated power increases sixteenfold — and it needs no medium to travel through at all." },
  { answer: "Closed-Loop Control", discipline: "Control Systems", accept: ["closed loop control", "feedback control", "closed loop system"], clues: ["A control scheme that never stops checking its own work.", "It compares actual output against a desired setpoint continuously.", "The difference it measures is called the error signal.", "A thermostat maintaining room temperature is a familiar everyday example.", "A control system that continuously measures its output and feeds the error back to correct itself."], reveal: "A control scheme that continuously measures its own output, compares it against a desired setpoint, and feeds the resulting error signal back to correct its behaviour. A household thermostat is a simple everyday example — it keeps sensing room temperature and adjusting the heating or cooling to match the target." },
  { answer: "Loss Function", discipline: "Machine Learning", accept: ["loss function", "cost function", "objective function"], clues: ["A single number a model is trained to make as small as possible.", "It measures the gap between a model's prediction and the actual answer.", "Choosing the wrong one for a given task can quietly sabotage the entire training process.", "Gradient descent works by following this quantity's slope downhill.", "Mean squared error and cross-entropy are two of its most common forms."], reveal: "A function that measures the gap between a model's predictions and the true answers, condensed into a single number that training seeks to minimise. Choosing the right form for a given task matters enormously — mean squared error suits regression problems, while cross-entropy is the standard choice for classification." },
  { answer: "Work Hardening", discipline: "Materials", accept: ["work hardening", "strain hardening", "cold working"], clues: ["It happens as a side effect of forming.", "Dislocation density rises and they start blocking one another.", "Strength goes up; ductility goes down.", "It's why a paperclip snaps after you bend it back and forth.", "Annealing reverses it."], reveal: "The increase in strength and reduction in ductility caused by plastic deformation multiplying dislocations. As dislocations pile up and block each other's motion, the material gets progressively harder to deform — which is why a bent paperclip eventually snaps." },
  { answer: "Virtual Ground", discipline: "Electronics", accept: ["virtual ground", "virtual earth", "virtual short"], clues: ["It's a node that behaves like something it isn't connected to.", "It only exists when negative feedback is active.", "It follows from assuming infinite open-loop gain.", "It's why the inverting amplifier gain is just a ratio of two resistors.", "The two op-amp inputs are forced to the same potential."], reveal: "The op-amp inverting input held at the same potential as the non-inverting input by negative feedback, without a physical connection. It only exists while the feedback loop is active, and it's exactly why the gain of an inverting amplifier reduces to a simple ratio of two resistors." },
  { answer: "Soil Consolidation Settlement", discipline: "Geotechnical Engineering", accept: ["soil consolidation settlement", "consolidation settlement", "consolidation", "soil consolidation"], clues: ["It happens slowly, sometimes over years or decades.", "Water gets squeezed out of the soil's pore spaces under sustained load.", "Clay is far more prone to it than sand.", "It's why some buildings keep sinking long after construction ends.", "The gradual settlement of a structure as pore water is squeezed out of the soil beneath it over time."], reveal: "The gradual settlement of a structure as sustained load slowly squeezes pore water out of the soil beneath it, allowing the soil skeleton to compress. Clay soils are especially prone to it because water drains through their fine pores so slowly, which is why some buildings keep settling for years or even decades after construction." },
  { answer: "Heat Gun", discipline: "Manufacturing", accept: ["heat gun"], clues: ["A tool that looks like a hair dryer but is built for a much higher temperature.", "It softens material without ever touching an open flame.", "It's what shrinks heat-shrink tubing down around a wire splice.", "Reach for it to strip old paint or bend a sheet of plastic.", "The handheld tool that blows very hot air, used to soften, strip or shrink materials."], reveal: "A handheld tool that blows a stream of very hot air, used to soften paint for stripping, bend plastic, or shrink heat-shrink tubing — all without an open flame. Temperature, not combustion, does the work." },
  { answer: "Critical Point", discipline: "Thermodynamics", accept: ["critical point", "critical temperature", "critical pressure"], clues: ["Beyond it, boiling simply stops happening.", "Liquid and vapour become indistinguishable from one another.", "Above it, a substance is described as a single strange phase, neither liquid nor gas.", "That phase is called supercritical fluid.", "The temperature and pressure above which a substance's liquid and gas phases become indistinguishable."], reveal: "The temperature and pressure above which the distinction between liquid and gas phases disappears entirely, leaving a single supercritical fluid. Supercritical carbon dioxide, held just above its own critical point, is used industrially as a solvent — for decaffeinating coffee, among other things." },
  { answer: "Wheel and Axle", discipline: "Mechanical Design", accept: ["wheel and axle"], clues: ["One of the classic simple machines taught alongside the lever and the inclined plane.", "It trades force for distance, exactly like a very large lever bent into a circle.", "A small effort applied at the wheel's rim produces much greater torque at the axle's center.", "A doorknob, a steering wheel, and a screwdriver's handle are all everyday versions of it.", "The simple machine consisting of a wheel rigidly attached to a smaller central axle, trading force for distance."], reveal: "A simple machine consisting of a wheel fixed to a smaller central axle, so they rotate together. Effort applied at the wheel's larger radius produces greater torque at the axle, trading distance moved for mechanical advantage — like a doorknob or a steering wheel." },
  { answer: "Thévenin's Theorem", discipline: "Electrical Engineering", accept: ["thevenins theorem", "thevenin", "thevenin equivalent"], clues: ["It lets you throw away almost an entire circuit.", "Whatever is behind the terminals gets replaced by two components.", "Its dual uses a current source and a parallel resistance instead.", "You find the resistance by killing all independent sources.", "A voltage source in series with a resistance."], reveal: "Any linear two-terminal network can be replaced by a single voltage source in series with a resistance. It lets you collapse an arbitrarily complex circuit down to just two numbers, found by open-circuiting the terminals and killing all sources in turn." },
  { answer: "Graduated Cylinder", discipline: "Chemistry", accept: ["graduated cylinder", "measuring cylinder"], clues: ["A piece of labware whose whole purpose is precision, not mixing.", "Its narrow, tall shape makes a small volume change easier to read accurately.", "Read its scale at eye level, at the bottom of the curved liquid surface.", "You'd choose it over a beaker whenever the exact volume actually matters.", "The tall, narrow, precisely marked glass tube used to measure an exact liquid volume."], reveal: "A tall, narrow glass or plastic tube marked with precise volume graduations, used to measure liquid volume accurately. The narrow diameter makes each milliliter correspond to a taller, easier-to-read change in height than a wide beaker allows." },
  { answer: "Virtual Memory", discipline: "Computer Engineering", accept: ["virtual memory"], clues: ["It lets a program believe it has more memory than the machine actually has.", "Every process gets its own private address space, isolated from every other.", "A page table translates the illusion into real physical addresses behind the scenes.", "When physical memory runs short, it can quietly swap data out to disk.", "A memory management technique giving each process its own private, addressable memory space mapped to physical memory."], reveal: "A memory management technique that gives every process its own private, contiguous address space, translated behind the scenes by a page table into actual physical memory locations. It lets a program run as if it had far more memory than physically exists, quietly swapping less-used pages out to disk when physical memory runs short." },
  { answer: "Thrust-to-Weight Ratio", discipline: "Aerospace Engineering", accept: ["thrust to weight ratio", "twr"], clues: ["A single number that decides whether something can even get off the ground unaided.", "Below a value of one, an aircraft or rocket simply cannot climb vertically.", "A fighter jet at full afterburner can actually exceed a value of one.", "A heavy airliner, by contrast, sits well below it — but still generates enough lift to fly.", "The ratio of an engine's thrust output to the vehicle's total weight."], reveal: "The ratio of an engine's thrust output to a vehicle's total weight, a single figure that decides how aggressively it can accelerate or climb. A value above one means an aircraft or rocket can climb straight up under thrust alone — true of some fighter jets at full afterburner, but far from true of a heavy airliner, which relies on wings to generate lift instead." },
  { answer: "Barometer", discipline: "Instrumentation", accept: ["barometer"], clues: ["An instrument that measures something you can't see, feel, or usually even notice changing.", "A falling reading on it is a classic early warning sign of incoming stormy weather.", "The mercury version balances a column of liquid metal against the weight of the air above it.", "Meteorologists rely on it to track shifting high- and low-pressure systems.", "The instrument that measures atmospheric pressure, often used to help predict the weather."], reveal: "An instrument that measures atmospheric pressure — classically by balancing a column of mercury against the weight of the air pushing down on it. A falling reading signals an approaching low-pressure system, often a warning of stormy weather." },
  { answer: "Jig", discipline: "Manufacturing", accept: ["jig", "fixture"], clues: ["A shop-made helper whose whole purpose is to make the same mistake impossible to make twice.", "It holds a workpiece and guides a tool, but is not the tool itself.", "Build one once and every subsequent part comes out identical.", "A drilling one guarantees every hole lands in exactly the same spot.", "A custom fixture used to hold a workpiece and guide a tool for repeatable, accurate cuts or holes."], reveal: "A custom-made fixture that holds a workpiece and guides a cutting tool, ensuring every part produced from it comes out identical. Building one takes upfront effort but removes the chance of human error on repeated operations." },
  { answer: "Kinetic Energy", discipline: "Dynamics", accept: ["kinetic energy"], clues: ["A form of energy that any moving object has, purely by virtue of moving.", "It grows with the square of speed, not in direct proportion to it.", "Double an object's speed and this energy quadruples, not just doubles.", "A speed bump is far more dangerous to hit at 60 mph than at 30, for exactly this reason.", "The energy an object has because of its motion."], reveal: "The energy an object possesses because it's moving, equal to one-half its mass times the square of its velocity. That square relationship means doubling speed quadruples the energy — why a crash at highway speed is so much more violent than one at half the speed." },
  { answer: "Manning's Equation", discipline: "Civil Engineering", accept: ["mannings equation", "manning equation", "mannings formula", "manning"], clues: ["It applies to flow with a free surface, not full pipes.", "It needs a roughness coefficient, n, looked up from tables.", "Hydraulic radius appears raised to the two-thirds power.", "It's empirical, not derived from first principles.", "Used for rivers, channels and storm drains."], reveal: "An empirical formula for velocity in open-channel flow: v = (1/n)R^(2/3)S^(1/2). Unlike the Darcy-Weisbach equation for pipes, it's purely empirical rather than derived from first principles, and it's still the standard tool for sizing rivers and storm drains." },
  { answer: "Iron Filings", discipline: "Electromagnetics", accept: ["iron filings"], clues: ["A pile of tiny metal shavings that becomes a science demonstration the moment a magnet gets near.", "Each individual piece briefly becomes its own tiny magnet, aligning with the field around it.", "Sprinkle them over a sheet of paper above a magnet and the field's invisible shape appears.", "They're small enough to trace curved field lines that a single compass needle never could.", "The tiny metal shavings used to visualize the shape of a magnetic field."], reveal: "Small metal filings that each briefly magnetize and align with a nearby magnetic field, letting the field's invisible shape and curve be traced visually — something a single compass needle, sensing only one point, can't show." },
  { answer: "Vena Contracta", discipline: "Fluid Mechanics", accept: ["vena contracta"], clues: ["A Latin name for a narrowing that isn't the orifice itself.", "It forms just downstream of a sharp-edged opening, not at the opening.", "The jet's cross-section there is smaller than the hole it came from.", "It's the reason orifice-plate flow meters need a discharge coefficient correction.", "The point of minimum cross-sectional area in a jet issuing from an orifice, just past the opening."], reveal: "The point just downstream of a sharp-edged orifice where a fluid jet's cross-sectional area is at its narrowest — smaller than the orifice itself, as streamlines continue converging past the opening. It's why orifice-plate flow meters need an empirical discharge coefficient rather than relying on the geometric opening area alone." },
  { answer: "Tensile Strength", discipline: "Solid Mechanics", accept: ["tensile strength", "ultimate tensile strength"], clues: ["A property measured by pulling a material apart until it finally gives way.", "It's the maximum stress a material can bear before it starts to permanently neck down or break.", "Steel cables are chosen for suspension bridges largely because this value is so high.", "It's usually reported in units of stress, like megapascals, not in units of force alone.", "The maximum stress a material can withstand while being stretched before it breaks."], reveal: "The maximum stress a material can withstand while being pulled before it fractures, measured by stretching a sample until it fails. It's why steel cables, with their high value of this property, are the default choice for suspension bridges." },
  { answer: "Thermal Runaway", discipline: "Safety Engineering", accept: ["thermal runaway"], clues: ["A positive feedback loop with a very bad ending.", "The rate of heat generation outpaces the rate of heat removal.", "It's why battery packs need cell spacing and vent paths.", "Once it starts in one cell it can propagate to its neighbours.", "It's the failure mode behind lithium-ion fires."], reveal: "A self-accelerating exothermic process where rising temperature increases heat generation faster than dissipation. Once generation outpaces removal, temperature climbs, generation climbs faster still, and the process feeds on itself until something fails." },
  { answer: "Plug Flow Reactor", discipline: "Chemical Engineering", accept: ["plug flow reactor", "pfr", "tubular reactor"], clues: ["A reactor shaped like a long tube, not a stirred tank.", "Fluid moves through it like a series of discrete slugs, in order, with no back-mixing.", "Concentration and reaction rate both vary continuously along its length.", "It generally achieves higher conversion per unit volume than its stirred-tank cousin.", "An idealised reactor model where fluid flows through as discrete plugs with no mixing along the flow direction."], reveal: "An idealised reactor model where fluid moves through a long tube as a series of discrete 'plugs' in strict sequence, with no back-mixing along the direction of flow — so concentration and reaction rate both vary continuously from inlet to outlet. That lack of mixing typically gives it higher conversion per unit volume than a well-stirred tank reactor running the same reaction." },
  { answer: "Diode", discipline: "Electronics", accept: ["diode"], clues: ["A component that behaves like a one-way valve, but for electric current.", "Current flows through it easily one way, and almost not at all the other.", "It's what converts alternating current into a one-directional pulsing current.", "An LED is really just a special version of this component that happens to emit light.", "The two-terminal component that lets current flow easily in only one direction."], reveal: "A two-terminal component that allows current to flow easily in one direction and blocks it in the other, acting like a one-way valve for electricity. Rectifiers use them to convert AC into pulsing DC, and an LED is simply one that emits light as it conducts." },
  { answer: "Arduino", discipline: "Embedded Systems", accept: ["arduino"], clues: ["A hardware platform that made a whole category of engineering vastly more approachable to beginners.", "It pairs a small microcontroller with a simplified programming environment built for hobbyists.", "Its board designs are open-source, so anyone can legally build a compatible clone.", "Countless hobbyist robots and blinking-LED projects online start with the exact same small blue board.", "The popular open-source microcontroller board and beginner-friendly platform for hobbyist electronics projects."], reveal: "An open-source microcontroller board and accompanying simplified programming environment, designed to make embedded electronics approachable for hobbyists and beginners. Its open hardware design is why compatible clones exist everywhere." },
  { answer: "Geiger Counter", discipline: "Nuclear Engineering", accept: ["geiger counter", "geiger-muller counter"], clues: ["An instrument that turns an invisible hazard into an audible clicking sound.", "Each click marks a single particle of radiation striking a gas-filled tube inside it.", "The faster the clicking, the higher the radiation level it's currently detecting.", "It's the classic instrument nuclear inspectors are shown waving over suspect material.", "The handheld instrument that detects ionizing radiation and reports it as audible clicks."], reveal: "A handheld instrument that detects ionizing radiation: each particle striking a gas-filled tube inside triggers a tiny electrical pulse, converted into an audible click. Radiation level is read directly from how fast the clicks come." },
  { answer: "Thermocouple", discipline: "Sensors", accept: ["thermocouple"], clues: ["A sensor made from a junction between two different metals, and nothing more exotic than that.", "A temperature difference across that junction generates a small voltage, all on its own.", "It needs no external power supply at all to produce a usable reading.", "It can survive and measure far hotter environments than a typical glass liquid thermometer ever could.", "The temperature sensor made from a junction of two different metals that generates a voltage related to temperature."], reveal: "A temperature sensor made from a junction of two dissimilar metals, which generates a small voltage proportional to temperature difference with no external power needed — robust enough to measure far higher temperatures than a liquid thermometer could survive." },
  { answer: "Wedge", discipline: "Mechanical Design", accept: ["wedge"], clues: ["A simple machine that's really just two inclined planes joined back to back.", "Its thin edge concentrates a modest push into a much larger splitting force.", "It converts a force applied along its length into a force perpendicular to its sides.", "An axe head and a doorstop both put this simple machine to work.", "The simple machine, shaped like two inclined planes back to back, used to split or secure objects."], reveal: "A simple machine formed from two inclined planes joined back to back, converting a force pushed along its length into a much larger force spread sideways — the principle behind an axe splitting wood or a doorstop holding a door." },
  { answer: "Statically Indeterminate Structure", discipline: "Structural Engineering", accept: ["statically indeterminate structure", "statically indeterminate", "indeterminate structure"], clues: ["A structure with more support than the bare minimum needed to stand up.", "Equilibrium equations alone can't solve it — there aren't enough of them.", "You need to bring in compatibility of deformation to close the gap.", "Removing one redundant support still leaves it standing.", "A structure with more unknown reactions or internal forces than the equations of equilibrium alone can solve."], reveal: "A structure with more support reactions or internal forces than the equations of static equilibrium alone can determine, requiring additional compatibility conditions on deformation to solve fully. The extra supports are called redundant, and removing one still leaves a stable, if now determinate, structure standing." },
  { answer: "Lathe", discipline: "Manufacturing", accept: ["lathe"], clues: ["A machine that spins the workpiece while the cutting tool stays still.", "It's the machine that turns a rough cylindrical blank into a precise round shaft.", "Woodturners and machinists both use versions of the same basic machine.", "The part being shaped rotates on a horizontal axis while a tool bites into it from the side.", "The workshop machine that spins material against a fixed cutting tool to shape round parts."], reveal: "A machine tool that rotates a workpiece against a stationary cutting tool, used to produce precise cylindrical shapes — shafts, bushings, and turned wood. Unlike most machining, here it's the part that spins, not the tool." },
  { answer: "Galvanic Corrosion", discipline: "Materials", accept: ["galvanic corrosion", "bimetallic corrosion", "dissimilar metal corrosion"], clues: ["It needs three things: two of one, plus an electrolyte.", "A table ranks materials from noble to active.", "The area ratio matters enormously — small anodes are dangerous.", "It's why you don't bolt aluminium directly to stainless steel outdoors.", "Two dissimilar metals in electrical contact form a cell."], reveal: "Accelerated corrosion of the less noble metal when two dissimilar metals are electrically connected in an electrolyte. The area ratio matters enormously — a small anode paired with a large cathode corrodes far faster, which is why aluminium and stainless steel shouldn't touch outdoors." },
  { answer: "Frequency", discipline: "Signal Processing", accept: ["frequency"], clues: ["A rate, measured in a unit that literally means 'cycles per second.'", "It's the inverse of a wave's period — how long a single cycle takes.", "Turn a radio dial and you're really just selecting a specific value of this.", "A higher-pitched musical note corresponds to a higher value of this property.", "How many complete cycles of a repeating wave occur per second, measured in hertz."], reveal: "The number of complete cycles a repeating wave completes per second, measured in hertz — the inverse of its period. It's what a radio dial tunes, and what your ear perceives as a musical note's pitch." },
  { answer: "Terminal Velocity", discipline: "Aerodynamics", accept: ["terminal velocity"], clues: ["A speed limit that emerges naturally, with no engine or brake involved.", "It's the point where drag force has grown to exactly cancel out gravity.", "Past this speed, a falling object simply can't accelerate any further.", "A skydiver in a spread-eagle position reaches a slower version of it than one falling head-first.", "The constant speed a falling object reaches when drag force balances the pull of gravity."], reveal: "The constant speed a falling object reaches once air resistance has grown large enough to exactly balance the pull of gravity, so it stops accelerating. Body position changes drag, which is why a skydiver falls slower spread-eagle than head-first." },
  { answer: "Public-Key Cryptography", discipline: "Computer Science", accept: ["public key cryptography", "asymmetric cryptography", "asymmetric encryption"], clues: ["A scheme built on a pair of keys that are mathematically linked but not identical.", "One key can be shared with absolutely anyone; the other must never leave your possession.", "What one key locks, only the other can unlock.", "It relies on a mathematical problem that's easy in one direction and brutally hard in reverse.", "An encryption scheme using a publicly shared key to encrypt and a private, secret key to decrypt."], reveal: "An encryption scheme built on a mathematically linked key pair — a public key that can be freely shared to encrypt data, and a private key, kept secret, that alone can decrypt it. It relies on mathematical problems, like factoring large numbers, that are easy to compute in one direction but computationally infeasible to reverse without the private key." },
  { answer: "Feedforward Control", discipline: "Control Systems", accept: ["feedforward control", "feed forward control"], clues: ["A control action taken before an error even has the chance to appear.", "It relies on knowing a disturbance is coming, in advance.", "It's almost always paired with feedback, never used entirely alone.", "It requires a reasonably accurate model of the system being controlled.", "A control strategy that acts on a known or measured disturbance before it affects the output, rather than reacting after the fact."], reveal: "A control strategy that acts on a known or anticipated disturbance before it can affect the output, rather than waiting for feedback to detect and correct an error after the fact. Because it depends on an accurate model of the system, it's almost always used alongside feedback control rather than as a complete replacement for it." },
  { answer: "Current", discipline: "Electrical Engineering", accept: ["current", "electric current"], clues: ["A quantity measured not in volts, but in amperes.", "It's defined as the rate at which electric charge flows past a point.", "Too much of it through a wire, and heat starts to build up fast.", "It's the moving part of electricity — voltage is what pushes it, resistance is what opposes it.", "The flow of electric charge through a conductor, measured in amperes."], reveal: "The rate at which electric charge flows past a point in a circuit, measured in amperes. Voltage pushes it, resistance opposes it, and too much of it flowing through an undersized wire generates the heat that fuses are built to catch." },
  { answer: "Value Stream Mapping", discipline: "Lean Manufacturing", accept: ["value stream mapping", "vsm"], clues: ["A diagramming exercise that traces a product's entire journey, step by step.", "It separates steps into two blunt categories.", "One category adds value the customer would pay for; the other, strictly speaking, doesn't.", "It's often drawn twice: once for the current state, once for an improved future state.", "A lean tool that maps every step in a process to distinguish value-adding activity from waste."], reveal: "A lean manufacturing tool that maps every single step a product goes through, from raw material to customer, distinguishing value-adding activity from pure waste. It's typically drawn twice — once documenting the current state as it actually is, and once sketching an improved future state to work toward." },
  { answer: "Pneumatic Cylinder", discipline: "Fluid Machinery", accept: ["pneumatic cylinder", "air cylinder"], clues: ["A component nearly identical in concept to a hydraulic cylinder, but with one key substitution.", "Compressed air, not liquid, is what pushes its internal piston along.", "It's generally faster but less forceful than its liquid-powered counterpart.", "The distinctive hiss of a factory robot arm moving is often this component exhausting air.", "The device that uses compressed air pushing on a piston to produce fast, linear motion."], reveal: "A device that uses compressed air pushing against a piston to produce linear motion — like a hydraulic cylinder but powered by a compressible gas instead of a liquid, trading raw force for speed and that familiar hiss of exhausting air." },
  { answer: "Total Internal Reflection", discipline: "Optics", accept: ["total internal reflection", "fiber optics", "fibre optics"], clues: ["An optical phenomenon that traps light inside a material rather than letting it escape.", "It only happens past a specific, critical angle of incidence.", "Beyond that angle, absolutely all of the light reflects — none of it refracts out.", "It's the entire reason a fibre optic cable can carry a signal for kilometres with minimal loss.", "The phenomenon where light striking a boundary past a critical angle reflects entirely back, with none escaping."], reveal: "The phenomenon where light striking the boundary between two materials, at an angle beyond a critical threshold, reflects entirely back into the denser material with none escaping through refraction. It's exactly what lets a fibre optic cable guide a light signal around bends and across kilometres of distance with remarkably little loss." },
  { answer: "Circuit Breaker", discipline: "Electrical Power", accept: ["circuit breaker", "breaker"], clues: ["A safety device that does the same essential job as a fuse, but can be reused.", "Trip it once, and flipping a switch resets it instead of needing a replacement part.", "It automatically opens the circuit the instant current exceeds a safe limit.", "Your home's electrical panel has a whole row of these, one per circuit.", "The resettable safety switch that automatically cuts power if current exceeds a safe level."], reveal: "A resettable safety switch that automatically opens a circuit once current exceeds a safe threshold, protecting the wiring from overheating — unlike a fuse, it can simply be reset with a flip of a switch rather than replaced." },
  { answer: "Litmus Paper", discipline: "Chemistry", accept: ["litmus paper", "litmus test"], clues: ["A strip of paper that answers a yes-or-no chemistry question with a color change.", "It only tells you which side of neutral a solution falls on, not exactly how far.", "Dip the red strip in and watch for it to turn blue.", "It's derived from a dye extracted from lichen.", "The color-changing paper strip used to test whether a solution is acidic or basic."], reveal: "A paper strip treated with a lichen-derived dye that turns red in acidic solutions and blue in basic ones. It only signals which side of neutral a solution falls on — for an exact pH value you'd need a meter or indicator scale instead." },
  { answer: "Stepper Motor", discipline: "Robotics", accept: ["stepper motor", "step motor"], clues: ["A motor that moves in small, precise, individually countable increments rather than spinning smoothly.", "Each electrical pulse it receives advances its shaft by one fixed, known angle.", "Without any position sensor at all, it can still reach an exact, repeatable position just by counting pulses.", "3D printers rely on several of these to move their print head with high precision.", "The motor that rotates in fixed, precise steps rather than continuously, moved by a sequence of electrical pulses."], reveal: "A motor that rotates in small, fixed-angle steps rather than spinning continuously, advancing by one precise step per electrical pulse received. Because each step is known exactly, it can reach a precise position just by counting pulses, with no separate feedback sensor needed." },
  { answer: "Instruction Pipelining", discipline: "Computer Engineering", accept: ["instruction pipelining", "pipelining", "cpu pipelining"], clues: ["A technique borrowed conceptually from a factory assembly line.", "Multiple instructions are in different stages of execution simultaneously.", "A branch instruction can force the whole thing to be flushed and restarted.", "It boosts throughput without needing a single instruction to run any faster.", "Overlapping the execution of multiple instructions across stages like fetch, decode and execute."], reveal: "A CPU design technique that overlaps the execution of multiple instructions across stages like fetch, decode and execute, so several instructions are in flight simultaneously like cars on an assembly line. It boosts overall instruction throughput without making any single instruction execute faster — though a mispredicted branch can force the whole pipeline to be flushed and restarted." },
  { answer: "Poka-Yoke", discipline: "Manufacturing", accept: ["poka yoke", "pokayoke", "mistake proofing", "error proofing"], clues: ["A Japanese term from the Toyota Production System.", "The philosophy is to make the error physically impossible, not merely discouraged.", "A USB-C connector is a good example; the original USB-A was not.", "Shigeo Shingo formalised it.", "It translates roughly as mistake-proofing."], reveal: "Designing a process or part so an error cannot be made, rather than relying on operator care. A part that can only physically fit one way — like a USB-C connector — is the textbook example: the mistake is engineered out, not merely warned against." },
  { answer: "Full-Wave Rectifier", discipline: "Electronics", accept: ["full wave rectifier", "bridge rectifier"], clues: ["It turns an AC waveform into something that never goes negative.", "Four diodes, arranged in a diamond, is the classic implementation.", "Unlike its half-wave cousin, it wastes none of the incoming waveform.", "Both halves of the AC cycle get flipped the same way, into the same direction.", "A circuit that converts both halves of an AC input into a pulsating, unidirectional DC output."], reveal: "A circuit, most commonly four diodes wired as a bridge, that converts both the positive and negative halves of an AC waveform into a single unidirectional, pulsating output. Unlike a half-wave rectifier it wastes none of the incoming cycle, which is why it's the standard front end of nearly every DC power supply." },
  { answer: "Continuity Equation", discipline: "Fluid Mechanics", accept: ["continuity equation", "conservation of mass", "mass continuity"], clues: ["The fluid-dynamics version of a very old accounting principle.", "It says mass can't simply vanish as fluid moves through a pipe.", "Narrow the pipe and the fluid must speed up to compensate.", "It's the partner equation that makes Bernoulli's principle work.", "A1V1 = A2V2 for incompressible flow — area times velocity stays constant."], reveal: "The statement that mass is conserved as a fluid flows through a system, so the mass flow rate must be the same at every cross-section. For incompressible flow this reduces to area times velocity staying constant along a streamtube — exactly why fluid speeds up through a narrowing pipe." },
  { answer: "Gear Ratio", discipline: "Mechanical Design", accept: ["gear ratio", "gearing ratio"], clues: ["A simple ratio that trades one quantity for its inverse.", "Speed it down and torque goes up by the same factor.", "It's set by the ratio of teeth counts on two meshing gears.", "A bicycle's lowest gear uses it to trade speed for climbing torque.", "Output speed divided by input speed, inversely proportional to the torque ratio."], reveal: "The ratio between the rotational speeds — or equivalently, teeth counts — of two meshing gears, which sets how torque and speed trade off between input and output. A reduction gearbox multiplies torque at the cost of speed, exactly in proportion to the ratio, since power is conserved." },
  { answer: "Petri Dish", discipline: "Biomedical Engineering", accept: ["petri dish"], clues: ["A piece of labware named after the German bacteriologist who invented it.", "It's a shallow, lidded, transparent dish, designed to be stacked and easily inspected.", "A gel-like growth medium is typically poured into its base before use.", "Alexander Fleming famously spotted an unexpected mold growing in one of these, leading to penicillin.", "The shallow, lidded, transparent dish used to culture cells, bacteria or other microorganisms."], reveal: "A shallow, transparent, lidded dish used to culture cells, bacteria, or other microorganisms on a growth medium. Named after Julius Richard Petri, it's the dish in which Alexander Fleming famously noticed the mold that led to penicillin." },
  { answer: "Load Cell", discipline: "Instrumentation", accept: ["load cell"], clues: ["A sensor whose entire job is converting force into an electrical signal.", "Inside it, one or more strain gauges are bonded to a precisely machined metal body.", "A digital kitchen scale contains a small version of exactly this.", "Industrial versions can weigh entire loaded trucks.", "A force transducer that uses strain gauges bonded to a metal body to convert applied load into an electrical signal."], reveal: "A force transducer that converts an applied load into an electrical signal, typically using strain gauges bonded to a precisely machined metal body that flexes minutely under weight. The same working principle scales from a small kitchen scale's internal sensor all the way up to industrial cells rated to weigh a fully loaded truck." },
  { answer: "Potential Energy", discipline: "Physics", accept: ["potential energy", "gravitational potential energy"], clues: ["A stored form of energy that depends entirely on position, not motion.", "Lift an object higher against gravity, and this quantity increases right along with it.", "Release the object, and this stored energy converts smoothly into energy of motion instead.", "A roller coaster car at the very top of its first hill has the most of it it'll ever have on the ride.", "The stored energy an object has because of its position, such as its height above the ground."], reveal: "Energy stored because of an object's position — most commonly its height in a gravitational field. Lift it higher and this stored energy grows; let it fall and that stored energy converts smoothly into kinetic energy of motion." },
  { answer: "Combustion", discipline: "Thermodynamics", accept: ["combustion"], clues: ["A chemical reaction that releases energy far faster than it was originally stored.", "It's an exothermic reaction between a fuel and an oxidizer, almost always oxygen.", "Light a match and you're triggering a small, controlled version of it.", "A car engine converts the rapid version of this reaction into mechanical motion, stroke by stroke.", "The rapid chemical reaction between a fuel and oxygen that releases heat and light."], reveal: "A rapid, exothermic chemical reaction between a fuel and an oxidizer — almost always oxygen — releasing heat and often light. A car engine harnesses many small, controlled instances of it, stroke by stroke, to produce mechanical motion." },
  { answer: "Torque Wrench", discipline: "Quality Engineering", accept: ["torque wrench"], clues: ["A tool built to stop you the instant you've applied exactly enough force, and no more.", "It clicks or signals once a preset rotational force has been reached.", "Over-tightening a bolt can be just as damaging as leaving it loose, which is exactly what this tool prevents.", "Engine head bolts and wheel lug nuts are both specified with an exact value this tool can hit.", "The wrench that measures and limits the rotational force applied to a fastener."], reveal: "A wrench that measures the rotational force being applied and signals — often with a click — once a preset torque value is reached, preventing a fastener from being over- or under-tightened relative to its engineering specification." },
  { answer: "Faraday's Law of Induction", discipline: "Electromagnetics", accept: ["faradays law", "faraday law", "faraday"], clues: ["It made the electrical grid possible.", "A stationary magnet in a stationary coil produces nothing at all.", "The induced EMF depends on rate of change, not magnitude.", "Lenz's law adds the minus sign that keeps energy conserved.", "Changing magnetic flux through a loop induces a voltage."], reveal: "A time-varying magnetic flux through a circuit induces an EMF equal to −dΦ/dt. Nothing has to touch anything else — the changing flux alone is enough, which is exactly what makes generators and transformers possible." },
  { answer: "Bode Plot", discipline: "Control Systems", accept: ["bode plot", "bode", "bode diagram"], clues: ["Two stacked graphs sharing a logarithmic horizontal axis.", "The top one is in decibels, the bottom one in degrees.", "Slopes come in tidy multiples of 20 dB per decade.", "You read gain margin and phase margin straight off it.", "Named after a Bell Labs engineer, and pronounced 'boh-dah'."], reveal: "A frequency-response plot of magnitude and phase against log frequency, used for stability margin analysis. Straight-line asymptotic approximations make it possible to sketch one by hand, reading gain and phase margin almost at a glance." },
  { answer: "Dropout", discipline: "Machine Learning", accept: ["dropout"], clues: ["A regularisation trick that works by deliberately sabotaging training.", "During each training step, a random subset of neurons is simply switched off.", "It forces the network to avoid over-relying on any single connection.", "At inference time, the full network is used again, with no units removed.", "A regularisation technique that randomly disables a fraction of neurons during each training step."], reveal: "A regularisation technique that randomly disables a fraction of a network's neurons during each training step, forcing the remaining units to avoid over-relying on any single connection or feature. The full, undamaged network is used again once training is complete, having effectively learned a more robust, redundant representation." },
  { answer: "Convection", discipline: "Heat Transfer", accept: ["convection", "convective heat transfer"], clues: ["A mode of heat transfer that only works because warmer fluid tends to rise.", "It requires a fluid, gas or liquid, physically moving heat from one place to another.", "A radiator warms a whole room partly by setting this circulating motion of air in motion.", "Stirring a pot of soup speeds up how evenly it heats, thanks to this same effect.", "The transfer of heat by the physical movement of a fluid, like rising warm air."], reveal: "Heat transfer carried out by the physical movement of a fluid — warm fluid rises, cooler fluid sinks to replace it, circulating heat throughout a room or a pot of soup. Unlike conduction, it requires the medium itself to be moving." },
  { answer: "Impedance Matching", discipline: "Electrical Engineering", accept: ["impedance matching", "matched impedance"], clues: ["Get it wrong and part of your signal comes straight back at you.", "The mismatch is quantified by a reflection coefficient.", "Transmission line effects make it matter above a certain frequency.", "Stubs, transformers and L-networks are the usual tools.", "It's why RF and video systems specify 50 or 75 ohms."], reveal: "Designing source, line and load impedances to be equal so power transfers without reflection. Get it wrong and part of the signal bounces straight back toward the source instead of being absorbed by the load — exactly why RF and video systems standardise on 50 or 75 ohms." },
  { answer: "Fiber-Reinforced Composite", discipline: "Materials", accept: ["fiber reinforced composite", "fibre reinforced composite", "frp", "composite material"], clues: ["Two very different materials, combined so neither works alone.", "One component carries the load; the other holds it in place and transfers stress.", "Its strength is highly directional, unlike a metal.", "Carbon fibre and fibreglass are the best-known examples.", "Stiff, strong fibres embedded in a softer matrix, giving high strength for very low weight."], reveal: "A material made of strong, stiff fibres embedded in a softer matrix that binds them together and transfers load between them. Because the fibres are usually aligned, the resulting strength is highly directional — strong along the fibre axis and far weaker across it, unlike an isotropic metal." },
  { answer: "Wrench", discipline: "Manufacturing", accept: ["wrench", "spanner"], clues: ["A hand tool whose jaws are shaped to fit one specific hex or square profile.", "Called by a different, more British-sounding name across the Atlantic.", "Fixed-size versions come in a full set; one adjustable version replaces the whole set, less precisely.", "You slide its open jaw or ring over a bolt head before applying torque.", "The hand tool used to grip and turn a nut or bolt head."], reveal: "A hand tool with jaws shaped to grip a nut or bolt head, used to apply turning torque. Called a spanner in British English, it comes in fixed sizes for a precise fit or as an adjustable version that trades precision for versatility." },
  { answer: "Second Moment of Area", discipline: "Structural Engineering", accept: ["second moment of area", "area moment of inertia", "moment of inertia", "i value"], clues: ["Its units are length to the fourth power.", "It's why an I-beam is shaped the way it is.", "Move material away from the centre and it grows fast.", "It appears in both the bending stress and deflection equations.", "Symbol I, and often confused with the mass-based version."], reveal: "A geometric property describing how cross-sectional area is distributed about an axis, governing bending stiffness. Moving material away from the neutral axis increases it dramatically, which is why an I-beam concentrates its area in the flanges rather than spreading it evenly." },
  { answer: "Screw", discipline: "Mechanical Design", accept: ["screw"], clues: ["A simple machine that's really an inclined plane wrapped around a cylinder.", "Turning it converts rotational motion into straight-line motion along its axis.", "Its thread pitch determines how far it advances with every single full turn.", "A jar lid, a bolt, and a corkscrew all put this same simple machine to work.", "The simple machine, an inclined plane wound around a shaft, used to fasten or lift by turning."], reveal: "A simple machine formed by wrapping an inclined plane around a cylinder, so rotating it converts turning motion into linear motion along its axis. The thread's pitch sets exactly how far it advances per full turn." },
  { answer: "High-Pass Filter", discipline: "Signal Processing", accept: ["high pass filter"], clues: ["The low-pass filter's mirror-image opposite.", "It blocks slow drift and lets fast changes through.", "Swap the positions of the resistor and capacitor in a basic low-pass filter and you get this instead.", "It's what strips a wandering DC offset out of an AC signal.", "A filter that passes frequencies above a cutoff and attenuates frequencies below it."], reveal: "A filter that passes frequencies above a chosen cutoff while attenuating frequencies below it — the mirror image of a low-pass filter, built from the very same components with their positions simply swapped. It's what strips a slowly wandering DC offset out of a signal while leaving the faster, wanted content untouched." },
  { answer: "Geostationary Orbit", discipline: "Aerospace Engineering", accept: ["geostationary orbit", "geosynchronous orbit"], clues: ["An orbit where a satellite appears to hang motionless in the sky.", "It requires one very specific altitude, and no other.", "At that altitude, the orbital period exactly matches Earth's rotation.", "It must also sit directly above the equator, not at any other latitude.", "A circular orbit roughly 35,786 km above the equator where a satellite's period matches Earth's rotation."], reveal: "A circular orbit roughly 35,786 km above the equator, at the one specific altitude where a satellite's orbital period exactly matches Earth's 24-hour rotation. From the ground, a satellite parked there appears to hang perfectly motionless in the sky, which is exactly why it's the preferred orbit for communications and weather satellites." },
  { answer: "Logic Gate", discipline: "Digital Logic", accept: ["logic gate"], clues: ["A component that outputs exactly one of two possible values, based purely on its inputs.", "It implements one basic rule from Boolean logic, in physical electronic form.", "Combine enough of these simple building blocks together and you can build an entire processor.", "One common version outputs true only when every single one of its inputs is also true.", "The basic electronic building block that performs a single Boolean operation on one or more binary inputs."], reveal: "A basic electronic building block that performs one Boolean operation — like AND, OR, or NOT — on binary inputs to produce a binary output. Wire enough of them together in the right pattern and you can build an entire processor." },
  { answer: "Linear Variable Differential Transformer", discipline: "Sensors", accept: ["lvdt", "linear variable differential transformer"], clues: ["It has one primary and two secondary windings.", "A ferromagnetic core slides through the middle.", "It has effectively infinite resolution and no sliding contact to wear.", "The output nulls at the centre and reverses phase either side.", "A four-letter abbreviation for a displacement sensor."], reveal: "An inductive position sensor whose differential secondary output varies linearly with core displacement. With no sliding electrical contact to wear out and a core that moves essentially without friction, it achieves fine resolution and long-term reliability contact sensors struggle to match." },
  { answer: "Le Chatelier's Principle", discipline: "Chemical Engineering", accept: ["le chateliers principle", "le chatelier", "lechatelier"], clues: ["A qualitative principle about systems that push back.", "It applies to a system already at equilibrium.", "Change pressure, temperature or concentration and it shifts.", "The shift always partially opposes the change you made.", "It's the basis of optimising the Haber process."], reveal: "A system at equilibrium responds to an imposed change by shifting so as to partially counteract that change. It's purely qualitative but enormously useful — it's the reasoning behind running the Haber process at high pressure to favour the ammonia equilibrium." },
  { answer: "Mean Time Between Failures", discipline: "Reliability Engineering", accept: ["mtbf", "mean time between failures"], clues: ["A number often quoted in tens of thousands of hours.", "It applies to repairable items; a different acronym covers the rest.", "It assumes a constant failure rate, which is often untrue.", "It is emphatically not the same as service life.", "Its reciprocal is the failure rate, lambda."], reveal: "The average operating time between failures of a repairable system — the reciprocal of failure rate. It only applies to items that get repaired and returned to service, and it assumes a constant failure rate that's often untrue near the start or end of a product's life." },
  { answer: "Mass Moment of Inertia", discipline: "Dynamics", accept: ["mass moment of inertia", "moment of inertia", "rotational inertia"], clues: ["Rotation's answer to ordinary mass.", "It resists angular acceleration the way mass resists linear acceleration.", "Spread the same mass further from the axis and it grows with the square of that distance.", "A figure skater speeds up by pulling their arms in — this is why.", "It appears in the rotational form of Newton's second law: τ = Iα."], reveal: "A measure of an object's resistance to angular acceleration about a given axis, analogous to mass in linear motion. Because it scales with the square of distance from the axis, redistributing mass closer to or farther from that axis changes it dramatically even if total mass stays fixed." },
  { answer: "Drag Coefficient", discipline: "Fluid Mechanics", accept: ["drag coefficient", "cd"], clues: ["A dimensionless number that captures how shape alone affects drag.", "A sleek teardrop shape scores far lower on it than a flat plate.", "It's found experimentally, usually in a wind tunnel.", "It scales drag force against dynamic pressure and a reference area.", "C_d in F_d = ½ρV²C_dA — the dimensionless factor scaling drag with shape and flow conditions."], reveal: "A dimensionless number capturing how much a body's shape contributes to the drag force it experiences, independent of size or speed. It's typically found experimentally in a wind tunnel, and it's why a sleek teardrop shape scores far lower than a flat plate pushed broadside through the same flow." },
  { answer: "Transistor", discipline: "Electronics", accept: ["transistor"], clues: ["A component that can act as either a switch or an amplifier, depending on how it's used.", "A tiny current or voltage at one terminal controls a much larger current at the others.", "Billions of a microscopic version of it are etched onto a single modern computer chip.", "Its invention in 1947 is widely credited with launching the entire modern electronics era.", "The semiconductor component used to amplify or switch electronic signals, and the building block of modern computer chips."], reveal: "A semiconductor component that uses a small current or voltage at one terminal to control a much larger current between two others, letting it act as an amplifier or an electronic switch. Billions of microscopic versions make up a modern computer chip." },
  { answer: "Soil Liquefaction", discipline: "Geotechnical Engineering", accept: ["soil liquefaction", "liquefaction"], clues: ["Solid ground that, for a moment, stops behaving like solid ground.", "It's triggered by strong shaking, most often from an earthquake.", "Loose, saturated sand is the soil type most vulnerable to it.", "Pore water pressure rises so high that grains lose contact with each other.", "The sudden loss of soil strength as shaking causes it to temporarily behave like a liquid."], reveal: "A phenomenon in which strong shaking causes pore water pressure in loose, saturated sand to rise so high that soil grains lose contact with one another, and the ground temporarily behaves like a liquid rather than a solid. It's one of the most destructive earthquake effects, capable of making buildings sink or tip over even without direct structural damage." },
  { answer: "Mohr's Circle", discipline: "Solid Mechanics", accept: ["mohrs circle", "mohr circle"], clues: ["A graphical method, invented long before computers existed.", "It transforms a quantity from one coordinate orientation to another.", "The radius gives maximum shear; the horizontal extremes give the principal values.", "You draw it on axes of normal stress against shear stress.", "Named after a 19th-century German civil engineer."], reveal: "A 2D graphical representation of the stress transformation equations, giving principal stresses and maximum shear directly. Rotating the diameter by twice the physical angle lets you read off stresses on any plane without touching the underlying trigonometry." },
  { answer: "Allen Key", discipline: "Manufacturing", accept: ["allen key", "hex key", "allen wrench"], clues: ["A tool that's just a bent hexagonal rod, with no moving parts at all.", "It fits into a recessed socket rather than gripping an external head.", "Flat-pack furniture assembly is impossible without one nearby.", "Its L-shape gives you a short end for tight spots and a long end for leverage.", "The small L-shaped hex tool used to drive socket-head screws, often included with flat-pack furniture."], reveal: "A hexagonal rod bent into an L-shape, used to drive screws with a matching recessed hex socket rather than an external head. The two arm lengths trade off leverage against clearance in tight spaces." },
  { answer: "Thermometer", discipline: "Instrumentation", accept: ["thermometer"], clues: ["An instrument that relies on the fact that most materials expand predictably as they warm up.", "A liquid trapped inside a thin glass tube climbs higher as it's heated.", "Modern digital versions read temperature electronically instead of by liquid expansion.", "You'd hold one under your tongue, or against your forehead, to check for a fever.", "The instrument used to measure temperature, classically using a liquid that expands in a thin tube."], reveal: "An instrument that measures temperature, classically by tracking how much a liquid — mercury or colored alcohol — expands inside a thin sealed tube as it warms. Digital versions instead use an electronic sensor whose properties shift predictably with temperature." },
  { answer: "Radioactive Half-Life", discipline: "Nuclear Engineering", accept: ["radioactive half life", "half life"], clues: ["A measure of time that never actually reaches zero, no matter how long you wait.", "It's the time needed for exactly half of a radioactive sample to decay.", "Wait that same interval again and half of what's left decays too.", "It ranges from fractions of a second to billions of years, depending on the isotope.", "The time required for half the atoms in a radioactive sample to undergo decay."], reveal: "The time required for exactly half the atoms in a radioactive sample to decay, a fixed property of each specific isotope that ranges from a fraction of a second to billions of years. Because the same fraction decays in every successive interval, the quantity remaining approaches zero only asymptotically — in principle, it never quite reaches it." },
  { answer: "Instruction Set Architecture", discipline: "Computer Engineering", accept: ["instruction set architecture", "isa"], clues: ["The contract between hardware and every piece of software that runs on it.", "It defines the vocabulary a processor actually understands.", "Two competing philosophies for designing it dominate the industry.", "Software compiled for one won't run on hardware built for a different one, without translation.", "The defined set of instructions, registers and addressing modes a processor's hardware implements."], reveal: "The defined vocabulary of instructions, registers and addressing modes that a processor's hardware actually implements — the contract every compiler and piece of software has to target. x86 and ARM are the two most familiar competing examples, and software compiled for one won't run natively on the other without translation." },
  { answer: "Ductile-Brittle Transition Temperature", discipline: "Materials", accept: ["ductile brittle transition temperature", "dbtt", "ductile to brittle transition"], clues: ["It's a property of body-centred cubic metals, not of face-centred cubic ones.", "Cross it and the failure mode changes completely.", "It's why some WWII Liberty ships cracked in cold North Atlantic water.", "Charpy testing across a temperature range reveals it.", "Below it, steel fails with almost no plastic deformation."], reveal: "The temperature below which a metal's fracture mode shifts from ductile tearing to brittle cleavage. It's a property of body-centred cubic metals like steel, and it's the reason some WWII Liberty ships cracked apart in cold North Atlantic water." },
  { answer: "Electroscope", discipline: "Electromagnetics", accept: ["electroscope"], clues: ["A device that detects an invisible property by showing you two thin metal leaves move apart.", "It has no electronics inside it at all, despite what its name might suggest.", "Bring a charged object near it and its two leaves repel each other, visibly diverging.", "It detects presence and relative amount of charge, not the exact voltage.", "The simple device with two metal leaves that spread apart to detect static electric charge."], reveal: "A simple device with two thin, lightweight metal leaves that spread apart when charge is transferred onto them, since like charges repel. It reveals the presence and rough amount of static charge, with no electronic components at all." },
  { answer: "Shaft", discipline: "Mechanical Design", accept: ["shaft", "drive shaft"], clues: ["A component whose entire job is to carry rotation from one place to another.", "It's the rotating backbone that other components like gears and bearings mount onto.", "A car's engine sends power to its wheels through a long rotating version of this.", "It must resist twisting forces, called torsion, without permanently deforming.", "The rotating rod that transmits rotational power and torque from one component to another."], reveal: "A rotating rod that transmits rotational power and torque between components — from an engine to a wheel, or a motor to a gear — while resisting the twisting force, called torsion, that carrying that power places on it." },
  { answer: "Enthalpy", discipline: "Thermodynamics", accept: ["enthalpy"], clues: ["A quantity engineers use so they don't have to track pressure and volume work separately.", "It combines internal energy with a pressure-volume term.", "In a constant-pressure process, its change equals the heat added or removed.", "It's what a steam table is really giving you at each state point.", "H = U + PV."], reveal: "A combined property equal to internal energy plus the product of pressure and volume, bundling flow work into one convenient quantity. In any constant-pressure process, the change in enthalpy simply equals the heat transferred, which is why it's the property tabulated in steam tables and used throughout power-cycle analysis." },
  { answer: "Drill Press", discipline: "Manufacturing", accept: ["drill press", "pillar drill"], clues: ["A stationary version of a tool you'd normally hold in your hand.", "It moves the bit straight down along a fixed vertical column.", "It trades the portability of a handheld version for guaranteed perpendicularity.", "A lever, not your arm, controls how fast the bit plunges into the work.", "The bench-mounted machine that drills perfectly straight, repeatable holes."], reveal: "A stationary machine that guides a rotating drill bit straight down along a fixed column, trading a handheld drill's portability for a guaranteed, repeatable, perfectly perpendicular hole." },
  { answer: "Influence Line", discipline: "Civil Engineering", accept: ["influence line", "influence lines"], clues: ["It answers a different question from a normal diagram.", "The load moves; the location of interest stays fixed.", "Müller-Breslau gave a neat way to sketch it.", "Bridge engineers use it constantly for moving traffic.", "It shows a response at one point as a unit load traverses the structure."], reveal: "A diagram showing how a response at a fixed point varies as a unit load moves across the structure. It flips the usual question around: instead of fixing the load and asking about the whole structure, it fixes the point of interest and lets the load travel." },
  { answer: "Bandwidth", discipline: "Electrical Engineering", accept: ["bandwidth", "3db bandwidth", "half power bandwidth"], clues: ["The range over which a system is considered to still be doing its job well.", "Its edges are defined by a specific drop in power, not an arbitrary cutoff.", "That drop is to half the maximum power — a loss of about 3 decibels.", "A wider one generally trades off against something else, like noise rejection.", "The frequency range over which a system's response stays within 3 dB of its peak value."], reveal: "The range of frequencies over which a system's output power stays within a factor of two — about 3 dB — of its peak value, defining the span it can be considered to handle effectively. Push it wider and a filter typically becomes less selective, admitting more out-of-band noise along with the wanted signal." },
  { answer: "Pipette", discipline: "Chemistry", accept: ["pipette", "pipet"], clues: ["A lab tool whose entire purpose is precision at a very small scale.", "Squeeze a bulb or press a plunger, and a controlled volume draws up into a thin tube.", "Electronic versions can now dispense down to a fraction of a microliter.", "You'd reach for it to transfer a single precise drop, not to pour a whole beaker.", "The lab tool used to draw up and transfer a precise, small volume of liquid."], reveal: "A lab tool used to draw up and dispense a precise, small volume of liquid, from a simple bulb-and-tube design to electronic versions accurate to a fraction of a microliter." },
  { answer: "Decision Tree", discipline: "Machine Learning", accept: ["decision tree"], clues: ["A model whose logic you can actually follow just by tracing a path.", "Every internal node asks a simple yes-or-no question about a single feature.", "Every path from root to leaf ends in a prediction.", "It's prone to overfitting unless deliberately kept shallow or pruned.", "A model that makes predictions by following a series of feature-based branching decisions to a leaf node."], reveal: "A model that makes predictions by following a series of simple, feature-based yes-or-no questions down through branching nodes until it reaches a leaf holding the final prediction. Unlike many machine learning models, its logic can be traced and read directly — though left unchecked, a tree deep enough to explain every training example is also deep enough to badly overfit." },
  { answer: "Root Locus", discipline: "Control Systems", accept: ["root locus", "rootlocus"], clues: ["A plot that traces paths as one parameter is swept.", "Branches start at poles and end at zeros, or at infinity.", "Crossing into the right half plane means trouble.", "The parameter being swept is usually loop gain.", "Developed by Walter Evans in the 1940s."], reveal: "A graphical technique showing how closed-loop pole locations migrate as gain varies. Watching where the branches cross into the right half of the plane tells a designer exactly how much gain the system can tolerate before it goes unstable." },
  { answer: "Prandtl Number", discipline: "Heat Transfer", accept: ["prandtl number", "prandtl"], clues: ["A dimensionless group that belongs to the fluid alone, not the flow around it.", "It compares how quickly momentum diffuses against how quickly heat diffuses.", "For air it's close to one; for oils it can be in the hundreds or more.", "A low value means heat diffuses much faster than momentum, as in liquid metals.", "Pr = ν/α — the ratio of momentum diffusivity to thermal diffusivity."], reveal: "A dimensionless property of a fluid alone, comparing how readily it diffuses momentum against how readily it diffuses heat. Liquid metals sit at the low end, where heat spreads far faster than momentum, while oils sit at the high end, spreading momentum much more readily than heat." },
  { answer: "Operational Amplifier", discipline: "Electronics", accept: ["operational amplifier", "op amp", "opamp"], clues: ["A near-ideal building block, originally designed to perform mathematical operations in analogue computers.", "On its own, its open-loop gain is so high it's almost useless.", "Wrap it in negative feedback and its behaviour becomes wonderfully predictable.", "Two inputs, one output, and — ideally — infinite input impedance.", "A high-gain differential amplifier whose behaviour in a circuit is set almost entirely by external feedback components."], reveal: "A high-gain differential amplifier whose raw open-loop gain is so large it's practically unusable on its own — but wrapped in a negative feedback network of external resistors, its behaviour becomes precise and predictable. It's the basic building block behind amplifiers, filters, integrators and comparators throughout analogue electronics." },
  { answer: "Laser Triangulation", discipline: "Metrology", accept: ["laser triangulation", "triangulation", "laser displacement sensor"], clues: ["The sensor and the detector sit at a known angle to each other.", "The spot's position on the detector encodes the distance.", "Accuracy degrades on shiny, transparent or very dark surfaces.", "It's the basis of most laser profilers and 3D scanners.", "The geometry is literally a triangle."], reveal: "A non-contact ranging method deducing distance from the lateral position of a projected spot on a detector. Because the sensor and emitter sit at a fixed, known angle to each other, simple geometry converts where the reflected spot lands into a distance measurement." },
  { answer: "Euler Buckling", discipline: "Structural Engineering", accept: ["euler buckling", "eulers buckling", "euler critical load", "buckling"], clues: ["A failure mode that has nothing to do with the material yielding.", "It's why a long thin ruler fails long before it crushes.", "The critical load scales with second moment of area and inversely with length squared.", "End conditions change the answer through an effective length factor.", "Named after the most prolific mathematician in history."], reveal: "Sudden lateral instability of a slender column under axial compression, at P_cr = π²EI/(KL)². Because the critical load depends only on stiffness and geometry, a slender column can buckle well before the material itself would ever yield." },
  { answer: "Convolution", discipline: "Signal Processing", accept: ["convolution"], clues: ["A mathematical operation that combines two functions into a third.", "It describes how a system's response smears out an input signal over time.", "In the frequency domain, this messy operation collapses into simple multiplication.", "Image blurring in photo software is this operation, applied in two dimensions.", "An operation combining an input signal with a system's impulse response to produce the system's output."], reveal: "A mathematical operation that combines an input signal with a system's impulse response, sliding one across the other, to produce the system's actual output. It looks complicated in the time domain, but the same operation collapses into simple multiplication once both signals are viewed in the frequency domain via the Fourier transform." },
  { answer: "Lever Rule", discipline: "Metallurgy", accept: ["lever rule"], clues: ["It's applied inside a two-phase region.", "You draw a horizontal line first, called a tie line.", "The name comes from an analogy with a balanced beam.", "The proportions come out as ratios of segment lengths.", "It tells you how much of each phase is present."], reveal: "A graphical method for calculating the relative proportions of two phases in equilibrium from a phase diagram. Draw a horizontal tie line through the composition of interest, and the phase proportions come out as ratios of the segment lengths either side — like balancing a see-saw." },
  { answer: "End Effector", discipline: "Robotics", accept: ["end effector"], clues: ["The part of a robot that actually does the job it was built for.", "Everything upstream of it exists purely to position it correctly.", "It can be a gripper, a welding torch, a paint sprayer, or countless other tools.", "It sits at the very tip of the kinematic chain, furthest from the base.", "The device attached to the end of a robotic arm that directly interacts with the task or environment."], reveal: "The device mounted at the very tip of a robot's kinematic chain, furthest from the base, that directly interacts with the task at hand — a gripper, welding torch or paint sprayer, among countless others. Every joint and link upstream of it exists purely to move this one component into exactly the right position and orientation." },
  { answer: "Buoyancy", discipline: "Fluid Mechanics", accept: ["buoyancy", "buoyant force"], clues: ["An upward force that exists purely because pressure increases with depth.", "It's exactly equal to the weight of the fluid a submerged object pushes out of the way.", "A steel ship floats not despite this force, but because of how much water its hull displaces.", "It's why a helium balloon rises and a stone sinks in the same fluid.", "The upward force a fluid exerts on an object submerged or floating in it."], reveal: "The upward force a fluid exerts on a submerged or floating object, equal to the weight of fluid the object displaces. A steel ship floats because its hollow hull displaces enough water to outweigh the steel itself." },
  { answer: "Clock Signal", discipline: "Digital Logic", accept: ["clock signal", "clock speed", "cpu clock"], clues: ["A steady, repeating pulse with one very important job.", "It keeps every synchronous part of a circuit moving in lockstep.", "Its rate is quoted in hertz, or these days, gigahertz.", "Push it too fast and signals don't settle before the next pulse arrives.", "A periodic signal that synchronises the timing of operations across a digital circuit."], reveal: "A periodic square-wave signal that synchronises when every flip-flop and register in a digital circuit updates, keeping otherwise-independent logic moving in lockstep. Push its frequency too high and signals no longer have time to settle before the next edge arrives, which is exactly what limits how fast a processor can run." },
  { answer: "Piezoelectric Effect", discipline: "Sensors", accept: ["piezoelectric effect", "piezoelectric", "piezo"], clues: ["It works in both directions, which makes it unusually useful.", "Quartz and PZT ceramic are the classic materials.", "It cannot measure a truly static load — the charge leaks away.", "It's in accelerometers, ultrasonic transducers and gas lighters.", "Mechanical stress produces an electric charge, and vice versa."], reveal: "The generation of electric charge in certain crystals under mechanical stress, and the reverse strain under applied voltage. It works in both directions, making the same crystal useful as both sensor and actuator, though it can't measure a truly static load since the charge leaks away." },
  { answer: "Milling Machine", discipline: "Manufacturing", accept: ["milling machine", "mill", "cnc mill"], clues: ["A machine that removes material with a rotating cutter moved along multiple axes.", "Unlike a lathe, here the workpiece typically stays still while the tool travels.", "It can cut flat faces, slots and pockets that a lathe simply can't produce.", "A CNC version follows a programmed toolpath instead of a machinist's hand crank.", "The machine tool that moves a spinning cutter across a stationary workpiece to shape flat and complex surfaces."], reveal: "A machine tool that moves a rotating multi-edge cutter along one or more axes across a workpiece, cutting flat faces, slots, and complex profiles that a lathe's single-axis rotation can't reach. Modern versions follow a computer-controlled toolpath." },
  { answer: "Sonic Boom", discipline: "Aerodynamics", accept: ["sonic boom"], clues: ["A sound that doesn't arrive gradually — it arrives all at once.", "It's not produced at the instant of breaking the sound barrier, but continuously afterward.", "A cone of compressed air trails an object moving faster than sound.", "Anyone the cone sweeps across hears the same sharp double-crack.", "The shockwave-generated noise produced continuously by an object travelling faster than the speed of sound."], reveal: "The shockwave-generated noise produced continuously by any object travelling faster than the speed of sound, trailing behind it as a cone of compressed air. It's a common misconception that the boom happens only once, at the instant of 'breaking' the sound barrier — anyone the trailing cone sweeps across hears the same sharp crack, for as long as the object stays supersonic." },
  { answer: "Spring Scale", discipline: "Statics", accept: ["spring scale", "force meter", "newton meter"], clues: ["An instrument that measures force by relying on how predictably a spring stretches.", "The more force you hang from it, the further its internal spring extends.", "Its scale can be calibrated to read out in newtons directly, not just in mass units.", "Fishermen and physics classrooms both use a version of this simple, elegant tool.", "The instrument, with an internal spring, used to measure force by how far it stretches under load."], reveal: "An instrument that measures applied force by how far it stretches an internal spring, relying on the spring's predictable, roughly proportional response to load — simple enough to calibrate directly in units of force like newtons." },
  { answer: "Pitot Tube", discipline: "Instrumentation", accept: ["pitot tube", "pitot static tube"], clues: ["A deceptively simple open tube facing directly into the flow.", "It measures one specific kind of pressure by bringing flow to a dead stop.", "Compare that reading against a static port and you get a speed.", "Every airliner's airspeed indicator depends on one, or several.", "A device that measures fluid flow velocity from the difference between stagnation and static pressure."], reveal: "A device that measures flow velocity by comparing stagnation pressure, sensed at a tube facing directly into the flow, against static pressure sensed separately. It's the working principle behind essentially every aircraft airspeed indicator, and famously vulnerable to error if the tube ices over." },
  { answer: "Arrhenius Equation", discipline: "Chemical Engineering", accept: ["arrhenius equation", "arrhenius"], clues: ["It contains an exponential and a temperature in the denominator.", "Plot the log against reciprocal temperature and you get a straight line.", "That slope gives you an activation energy.", "A rough rule of thumb: rate doubles every 10°C.", "It's also the basis of accelerated life testing."], reveal: "k = A·exp(−Ea/RT) — the temperature dependence of reaction rate through an activation energy. Plotting its logarithm against reciprocal temperature gives a straight line whose slope reveals the activation energy directly." },
  { answer: "Diffraction Grating", discipline: "Optics", accept: ["diffraction grating"], clues: ["An optical component covered in an enormous number of extremely fine, closely spaced lines.", "Light passing through or reflecting off it interferes with itself, splitting into separate colors.", "The rainbow sheen on the back of a CD is this effect happening by accident.", "Spectrometers use one to split incoming light apart for precise analysis, wavelength by wavelength.", "The optical component with many fine parallel lines that splits light into its component colors by diffraction."], reveal: "An optical component ruled with thousands of closely spaced parallel lines per millimeter, splitting light into its component wavelengths through interference and diffraction — the same effect that makes the back of a CD flash rainbow colors." },
  { answer: "Process Capability Index", discipline: "Quality Engineering", accept: ["process capability index", "cpk", "process capability"], clues: ["A single number comparing what a process can actually do against what it's allowed to do.", "It relates the width of a specification to the natural spread of the process.", "A value of 1.33 is a commonly cited minimum target in industry.", "Unlike a simpler related index, it also accounts for the process being off-centre.", "A statistic comparing the spread of a process's output against specification limits, accounting for centering."], reveal: "A statistic comparing how tightly a process's natural output spread fits within its specification limits, while also accounting for whether the process is centred within those limits or shifted to one side. A value of 1.33 or higher is commonly cited across industry as the minimum for a process considered reliably capable." },
  { answer: "Faraday Cage", discipline: "Electromagnetics", accept: ["faraday cage", "faraday shield"], clues: ["An enclosure that protects what's inside it by redirecting something around the outside instead.", "It doesn't need to be solid — a metal mesh works just as well as solid sheet metal.", "A car's metal body famously offers its occupants a version of this protection during a lightning strike.", "Inside one, a phone often loses signal entirely, cut off from external electric fields.", "A conductive enclosure that blocks external electric fields from reaching whatever is inside."], reveal: "A conductive enclosure — solid or mesh — that shields its interior from external electric fields by redistributing charge across its own surface, canceling the field inside. It's why a car offers real protection in a lightning strike." },
  { answer: "Generative Adversarial Network", discipline: "Deep Learning", accept: ["generative adversarial network", "gan"], clues: ["An architecture built from two networks locked in direct competition.", "One network tries to create convincing fakes; the other tries to catch them.", "As training proceeds, both sides are forced to keep getting better.", "At its best, the fake-creating network produces output indistinguishable from the real thing.", "A pair of neural networks — a generator and a discriminator — trained adversarially against each other."], reveal: "An architecture pairing two neural networks trained against each other — a generator trying to produce convincing fake data, and a discriminator trying to tell real data from generated fakes. As training proceeds, each network's improvement forces the other to improve in turn, and at its best the generator learns to produce output indistinguishable from the real thing." },
  { answer: "Centrifugal Pump", discipline: "Fluid Machinery", accept: ["centrifugal pump"], clues: ["The most common type of pump in industry, by a wide margin.", "It adds energy to a fluid using a spinning impeller, not a piston.", "It converts kinetic energy into pressure as flow leaves the impeller.", "Its performance curve trades off flow rate against head in a predictable way.", "A rotodynamic pump that uses a rotating impeller to accelerate fluid outward and generate pressure."], reveal: "A rotodynamic pump that spins an impeller to fling fluid outward, converting the kinetic energy it picks up into pressure as it slows down in the surrounding casing. Its flow rate and the head it can produce trade off along a fixed performance curve, unlike the near-constant flow of a positive-displacement pump." },
  { answer: "Factor of Safety", discipline: "Mechanical Design", accept: ["factor of safety", "safety factor", "fos"], clues: ["A number, usually greater than one, that lets engineers sleep at night.", "Aerospace uses low values; lifting equipment uses high ones.", "Critics argue it's really a factor of ignorance.", "It's the ratio of capacity to demand.", "Strength divided by applied stress."], reveal: "The ratio of a structure's capacity to the load actually applied, absorbing uncertainty in both. How large it needs to be depends on the consequences of failure — aerospace pushes it low to save weight, lifting gear keeps it high." },
  { answer: "Resistance", discipline: "Electrical Engineering", accept: ["resistance", "electrical resistance"], clues: ["A property measured in a unit named after the same physicist behind the law that links it to voltage and current.", "Thin, long wires have more of it than thick, short ones.", "It's what converts electrical energy into heat inside a toaster or an incandescent bulb's filament.", "Rearrange V = IR and you can solve directly for it.", "The property of a material that opposes the flow of electric current, measured in ohms."], reveal: "A material's opposition to the flow of electric current, measured in ohms. It depends on the material, its length, and its thickness — and it's exactly what turns electrical energy into heat inside a toaster's coil or a bulb's filament." },
  { answer: "Melting Point", discipline: "Materials", accept: ["melting point"], clues: ["A specific temperature where two states of matter briefly coexist in equilibrium.", "For a pure substance, it's usually a single sharp temperature, not a range.", "Alloying a metal, like adding carbon to iron, can shift this value significantly.", "It's the temperature at which a solid and a liquid form of the same substance are equally stable.", "The temperature at which a solid substance turns into a liquid."], reveal: "The specific temperature at which a solid and liquid phase of the same pure substance can coexist in equilibrium — heat past it and the solid melts. Alloying a material, like adding carbon to iron to make steel, can shift it substantially." },
  { answer: "Vice", discipline: "Manufacturing", accept: ["vice", "vise", "bench vice"], clues: ["A tool with no motor and no cutting edge, yet essential to almost every other tool's job.", "Two jaws close on a screw thread to clamp something steady.", "Bolted to a workbench, it frees up both of your hands for the actual work.", "You tighten its handle until the workpiece can't budge, then start cutting or filing.", "The bench-mounted clamping tool with two jaws that holds a workpiece steady."], reveal: "A clamping tool with two jaws closed by a screw thread, bolted to a workbench to hold a workpiece steady and free both hands for cutting, filing, or drilling." },
  { answer: "Rankine Cycle", discipline: "Thermodynamics", accept: ["rankine cycle", "rankine"], clues: ["A practical cycle, unlike its idealised cousin.", "The working fluid changes phase twice per cycle.", "Pump, boiler, turbine, condenser.", "Reheat and regeneration are the standard efficiency improvements.", "It's the cycle behind almost every steam power station."], reveal: "The vapour power cycle using phase change of a working fluid through pump, boiler, turbine and condenser. Reheat and regeneration are the standard tricks for pushing its efficiency higher, and in some form it's the cycle behind almost every steam power station on the planet." },
  { answer: "V-Model", discipline: "Systems Engineering", accept: ["v model", "vee model", "v-model"], clues: ["Named for the shape you draw it in.", "The left-hand branch descends through decomposition.", "The right-hand branch ascends through integration.", "Each level on the left pairs with a test level on the right.", "It's mandated in automotive and aerospace development standards."], reveal: "A development lifecycle pairing each design decomposition stage with a corresponding verification stage. Named for its shape, the descending left branch breaks a system down into components while the ascending right branch verifies each level back up through integration." },
  { answer: "Printed Circuit Board", discipline: "Electronics", accept: ["printed circuit board", "pcb"], clues: ["A flat board whose 'wires' are etched copper traces, not loose strands.", "Components are soldered directly onto its surface rather than wired point to point.", "Its thin copper layers are laminated onto a rigid, usually green, insulating substrate.", "Almost every piece of modern electronics is built around at least one of these.", "The flat board with etched copper traces used to mechanically support and electrically connect components."], reveal: "A flat, rigid board with etched copper traces laminated onto an insulating substrate, replacing loose point-to-point wiring by both mechanically supporting components and electrically connecting them in a fixed, repeatable layout." },
  { answer: "Slope Stability", discipline: "Geotechnical Engineering", accept: ["slope stability", "slope stability analysis"], clues: ["An analysis asking one blunt question about an earthen or rock slope.", "It compares resisting shear strength against forces driving potential collapse.", "A circular or planar surface is usually assumed as the likely failure path.", "The ratio between those two competing forces is a familiar concept from elsewhere in engineering.", "The analysis of a slope's factor of safety against sliding failure along an assumed failure surface."], reveal: "The analysis of a slope's factor of safety against sliding failure, comparing the shear strength resisting collapse against the forces driving it along an assumed failure surface, often approximated as circular or planar. It's the same basic factor-of-safety logic used throughout structural engineering, just applied to a mass of soil or rock instead of a beam or column." },
  { answer: "Hash Table", discipline: "Computer Science", accept: ["hash table", "hash map"], clues: ["A data structure built for near-instant lookup, on average.", "A function scrambles a key into an array index.", "Two different keys can, unluckily, land on the same index — a collision.", "Chaining and open addressing are the two standard ways of handling that problem.", "A data structure using a hash function to map keys to array indices, giving average-case constant-time lookup."], reveal: "A data structure that uses a hash function to map keys directly to array indices, giving average-case constant-time insertion and lookup. Different keys can occasionally collide at the same index, which is why every practical implementation needs a collision-resolution strategy like chaining or open addressing." },
  { answer: "Nusselt Number", discipline: "Heat Transfer", accept: ["nusselt number", "nusselt"], clues: ["Another dimensionless group, this one in heat transfer.", "A value of one means a rather disappointing result.", "It's usually correlated against Reynolds and Prandtl numbers.", "It is the ratio of convective to conductive heat transfer across a boundary.", "Named after a German engineer, and abbreviated Nu."], reveal: "Nu = hL/k — the ratio of convective to conductive heat transfer at a surface. A value near one means convection is barely helping at all, while high values reflect vigorous mixing driving heat away far faster than conduction alone could." },
  { answer: "Alternating Current", discipline: "Electrical Power", accept: ["alternating current", "ac"], clues: ["A form of electrical current that periodically reverses its own direction.", "It's the form of electricity that comes out of a standard household wall outlet.", "Transformers can step its voltage up or down easily, which direct current can't do as simply.", "Its frequency, in most countries, is either 50 or 60 cycles per second.", "Electric current that periodically reverses direction, unlike the current from a battery."], reveal: "Electric current that periodically reverses direction, unlike the one-way flow from a battery. It's the form delivered by household wall outlets, chosen partly because transformers can step its voltage up or down far more easily than they can with direct current." },
  { answer: "Additive Manufacturing", discipline: "Manufacturing", accept: ["additive manufacturing", "3d printing"], clues: ["A manufacturing category defined by what it does that traditional machining doesn't.", "Material is built up, one thin layer at a time, rather than cut away.", "It can produce internal geometries that would be physically impossible to machine.", "Its most familiar consumer form goes by a much shorter, everyday name.", "A manufacturing process that builds parts layer by layer from a digital model, rather than removing material."], reveal: "A manufacturing process that builds parts up layer by layer directly from a digital model, the opposite approach to subtractive machining, which cuts material away. Because it isn't limited by what a cutting tool can physically reach, it can create complex internal geometries — lattices, internal channels — that would be impossible to machine any other way." },
  { answer: "Tuning Fork", discipline: "Vibrations", accept: ["tuning fork"], clues: ["A metal tool shaped like a two-pronged fork, designed to do exactly one thing precisely.", "Strike it, and it vibrates at a single, extremely stable and predictable frequency.", "Musicians once used it as a portable, reliable reference pitch before electronic tuners existed.", "Hold its stem against a table and the sound it produces gets noticeably louder.", "The two-pronged metal tool that vibrates at a fixed, precise pitch when struck."], reveal: "A two-pronged metal tool that, when struck, vibrates at one extremely stable and precise frequency, historically used by musicians as a portable, reliable reference pitch before electronic tuners existed." },
  { answer: "Prosthesis", discipline: "Biomedical Engineering", accept: ["prosthesis", "prosthetic", "prosthetic limb"], clues: ["An engineered replacement for something the body has lost.", "Modern versions increasingly read electrical signals straight from muscle tissue.", "Those signals let a user control the device with intention alone, not mechanical linkage.", "3D printing has dramatically driven down the cost of custom-fitted versions.", "An artificial device engineered to replace a missing body part and restore its function."], reveal: "An artificial device engineered to replace a missing body part and restore as much of its function as possible. Advanced modern versions read myoelectric signals directly from residual muscle tissue, letting a user control the device through intended muscle activation rather than a purely mechanical linkage." },
  { answer: "Low-Pass Filter", discipline: "Signal Processing", accept: ["low pass filter"], clues: ["A filter with a clear favourite among frequencies.", "It lets the slow stuff through and blocks the fast stuff.", "A simple resistor and capacitor is enough to build a basic version.", "It's what smooths a noisy sensor reading into something usable.", "A filter that passes frequencies below a cutoff and attenuates frequencies above it."], reveal: "A filter that passes frequencies below a chosen cutoff largely unaffected while attenuating frequencies above it, smoothing out fast fluctuations while preserving slower trends. A single resistor and capacitor is enough to build a simple version, which is exactly why it's often the first thing added to clean up a noisy sensor signal." },
  { answer: "Kármán Vortex Street", discipline: "Fluid Mechanics", accept: ["karman vortex street", "von karman vortex street", "vortex shedding", "karman vortex"], clues: ["A repeating pattern you can see in satellite photos of clouds behind islands.", "It has a characteristic frequency, described by the Strouhal number.", "It made the Tacoma Narrows bridge famous, though the full story is more complex.", "It's why tall chimneys have helical strakes wrapped around them.", "Alternating vortices shed from behind a bluff body."], reveal: "The alternating pattern of vortices shed from a bluff body, producing periodic side forces. The shedding frequency is remarkably predictable, which is why tall chimneys are wrapped in helical strakes to break up the pattern before it excites a resonance." },
  { answer: "Suspension Bridge", discipline: "Civil Engineering", accept: ["suspension bridge"], clues: ["Its main cables carry load almost entirely by hanging in tension.", "Towers support the cables; the cables support everything else, via smaller verticals.", "The main cable's shape approximates a specific mathematical curve under uniform load.", "The Golden Gate Bridge is one of the most famous examples in the world.", "A bridge whose deck is hung from main cables in tension, draped between towers and anchored at each end."], reveal: "A bridge whose deck hangs from vertical suspender cables connected to main cables draped between towers and anchored in tension at each end. Under a uniformly distributed load, the main cable naturally settles into a parabolic shape, carrying the entire load purely in tension with no bending at all." },
  { answer: "Field-Programmable Gate Array", discipline: "Computer Engineering", accept: ["field programmable gate array", "fpga"], clues: ["A chip that's blank until you tell it what to be.", "Its internal logic can be rewired after manufacturing, not just once but repeatedly.", "It sits in a middle ground between a general-purpose processor and a fixed custom chip.", "Hardware description languages like VHDL or Verilog are used to configure it.", "A reconfigurable integrated circuit whose internal logic gates and interconnects can be programmed after manufacture."], reveal: "A reconfigurable integrated circuit built from a grid of programmable logic blocks and interconnects, which can be configured — and reconfigured — after manufacture using a hardware description language like VHDL or Verilog. It sits between a general-purpose processor and a fixed custom ASIC, trading some efficiency for the flexibility to redefine the hardware itself." },
  { answer: "Tape Measure", discipline: "Metrology", accept: ["tape measure", "measuring tape"], clues: ["A flexible measuring tool that coils up compactly when it isn't being used.", "A springy metal blade retracts automatically back into its case at the push of a button.", "A small hook at its end is intentionally left slightly loose, to correct for its own thickness.", "It's the first tool reached for on nearly every construction site, for jobs big and small.", "The retractable, flexible ruler used to measure length, coiled inside a case when not in use."], reveal: "A flexible, retractable ruler — usually a thin, curved metal blade — that coils into a case for storage and extends for measuring. The end hook is deliberately loose by a small amount, calibrated to cancel out its own thickness." },
  { answer: "Schmitt Trigger", discipline: "Electronics", accept: ["schmitt trigger", "schmitt"], clues: ["It has two thresholds instead of one.", "The gap between them is deliberate, not a defect.", "It cleans up a slow or noisy edge into a crisp one.", "Its symbol contains a small hysteresis loop.", "Positive feedback around a comparator produces it."], reveal: "A comparator with hysteresis — separate rising and falling thresholds — used to reject noise on slow transitions. A noisy or slowly changing input has to swing all the way across the gap before the output flips, keeping a marginal signal from chattering." },
  { answer: "Kalman Filter", discipline: "Control Systems", accept: ["kalman filter", "kalman"], clues: ["It was used on the Apollo guidance computer.", "It is recursive — it never stores the whole history.", "It runs a predict step and an update step, forever.", "It optimally blends a model's prediction with a noisy measurement.", "It's the standard tool in sensor fusion and IMU processing."], reveal: "A recursive estimator producing optimal state estimates by weighting model predictions against noisy measurements. It never stores the full measurement history — each estimate builds purely on the last one plus the latest reading — which made it practical for the Apollo guidance computer." },
  { answer: "Erlenmeyer Flask", discipline: "Chemistry", accept: ["erlenmeyer flask", "conical flask"], clues: ["A flask shaped like a cone, not a cylinder or a sphere.", "Its narrow neck exists specifically to make swirling without spilling easy.", "Named after the German chemist who designed it in 1860.", "You can set a stopper or a funnel neatly into its narrow top.", "The cone-shaped flask with a narrow neck and flat base, easy to swirl without spilling."], reveal: "A cone-shaped flask with a flat base and narrow neck, designed by German chemist Emil Erlenmeyer so its contents can be swirled vigorously without splashing out — the narrowing walls funnel any splash back down." },
  { answer: "Tsiolkovsky Rocket Equation", discipline: "Aerospace Engineering", accept: ["tsiolkovsky rocket equation", "rocket equation", "tsiolkovsky", "ideal rocket equation"], clues: ["It contains a natural logarithm, and that's the whole problem.", "It explains why rockets are almost entirely propellant.", "It's the reason for staging.", "It relates exhaust velocity and mass ratio to a change in speed.", "Δv = v_e ln(m_0/m_f)."], reveal: "Δv = v_e ln(m₀/m_f) — the velocity change achievable given exhaust velocity and mass ratio. Because mass ratio only enters as a logarithm, each extra increment of velocity costs disproportionately more propellant — exactly why rockets are staged, shedding dead mass as they empty." },
  { answer: "Current Divider", discipline: "Electrical Engineering", accept: ["current divider"], clues: ["The voltage divider's counterpart, working on parallel branches instead.", "Two resistors in parallel share the total incoming current between them.", "The branch with less resistance carries more of the current, not less.", "It's the inverse relationship you'd expect from Ohm's law applied to parallel paths.", "A circuit of parallel resistors that splits an input current between branches in inverse proportion to resistance."], reveal: "A circuit of two or more resistors in parallel that splits an incoming current between branches, with each branch carrying current in inverse proportion to its own resistance. Counterintuitively to some, the lower-resistance path always takes the larger share of current, since it offers the easier route." },
  { answer: "Bolt", discipline: "Mechanical Design", accept: ["bolt"], clues: ["A fastener that, unlike a screw, is usually meant to pair with a separate nut.", "Its external threads mesh with matching internal threads to clamp two parts together.", "The tension deliberately built into it when tightened is what actually holds a joint together.", "Torque wrenches exist specifically to tighten this fastener to a precise, specified value.", "The threaded fastener, typically paired with a nut, used to clamp two parts together."], reveal: "A threaded fastener, typically paired with a matching nut, that clamps two parts together by stretching slightly under tension when tightened — that built-in tension, not just friction, is what actually holds the joint together." },
  { answer: "C-Clamp", discipline: "Manufacturing", accept: ["c-clamp", "c clamp", "g-clamp"], clues: ["A tool shaped exactly like the letter it's named after.", "A threaded screw at one end presses a workpiece against a fixed jaw at the other.", "Unlike a vice, it's not fixed to a bench — you clamp it directly onto the work.", "Woodworkers use it to hold glued pieces together while the glue cures.", "The C-shaped clamping tool with a screw that tightens to hold pieces together."], reveal: "A C-shaped clamp with a threaded screw that presses a workpiece against the frame's fixed jaw, used to hold parts together — most commonly while glue or a weld sets." },
  { answer: "Backpropagation", discipline: "Machine Learning", accept: ["backpropagation", "backprop"], clues: ["The algorithm that actually makes training a deep network computationally feasible.", "It computes how much each individual weight contributed to the final error.", "It works backward through the network, layer by layer, from output to input.", "Under the hood, it's really just a very efficient application of the chain rule from calculus.", "An algorithm computing the gradient of a neural network's loss with respect to every weight, by propagating error backward."], reveal: "An algorithm that computes how much every individual weight in a neural network contributed to the final error, by propagating that error backward through the layers using the chain rule from calculus. It's what makes training networks with millions of parameters computationally tractable at all." },
  { answer: "Galvanometer", discipline: "Instrumentation", accept: ["galvanometer"], clues: ["An instrument named after the scientist whose twitching frog-leg experiments hinted electricity could move muscle.", "A small current passing through its internal coil deflects a needle against a spring.", "It's the sensitive core mechanism hiding inside many old analog meters.", "Long before digital displays, it was how tiny currents were first made visible.", "The sensitive instrument that detects and measures small electric currents using a deflecting needle."], reveal: "A sensitive instrument that detects small electric currents by deflecting a needle, using the magnetic force a current-carrying coil experiences in a fixed field. It's the analog mechanism that older voltmeters and ammeters were built around." },
  { answer: "Control Rod", discipline: "Nuclear Engineering", accept: ["control rod", "control rods"], clues: ["A component whose entire job is to slow something down, deliberately.", "It's made of a material that readily soaks up free neutrons.", "Inserting it further into a reactor core throttles the chain reaction.", "Withdrawing it lets the reaction run faster instead.", "A neutron-absorbing rod inserted into a nuclear reactor core to control the rate of the fission chain reaction."], reveal: "A rod made of a strongly neutron-absorbing material, inserted into a nuclear reactor core to control the rate of the fission chain reaction. Pushing it further in soaks up more free neutrons and slows the reaction down; withdrawing it lets more neutrons through to sustain a faster reaction." },
  { answer: "Cantilever Beam", discipline: "Structural Engineering", accept: ["cantilever beam", "cantilever"], clues: ["A beam that commits to only one end being held.", "The free end is the one that deflects the most under load.", "A diving board is a familiar everyday example.", "Its maximum bending moment occurs right at the fixed support, not at midspan.", "A beam rigidly fixed at one end and completely free at the other."], reveal: "A beam rigidly fixed at one end while the other end remains completely free, unlike a simply supported beam held at both ends. Its bending moment is largest right at the fixed support and its deflection is largest at the free end — the exact opposite arrangement of a simply supported beam under a similar load." },
  { answer: "Shear Modulus", discipline: "Materials", accept: ["shear modulus", "modulus of rigidity", "g modulus"], clues: ["The shear-world counterpart to Young's modulus.", "It relates shear stress to shear strain, not normal stress to normal strain.", "It governs how much a shaft twists under torque.", "For an isotropic material it's linked to Young's modulus and Poisson's ratio by a single formula.", "Symbol G, appearing in τ = Gγ."], reveal: "The elastic constant relating shear stress to shear strain, governing how much a material distorts angularly rather than stretches. For isotropic materials it isn't independent — it's fixed by Young's modulus and Poisson's ratio through a simple relationship." },
  { answer: "Free Fall", discipline: "Dynamics", accept: ["free fall", "freefall"], clues: ["A state where the only force acting on an object is gravity itself.", "Air resistance, by definition, is either absent or being deliberately ignored.", "Astronauts orbiting Earth are technically in a continuous version of this state.", "It's why, ignoring air resistance, a feather and a hammer would drop at the same rate.", "The motion of an object falling under gravity alone, with no other forces acting on it."], reveal: "The state of falling under gravity alone, with no other force — like air resistance — acting on the object. Without that resistance, a hammer and a feather really do fall at the same rate, as famously demonstrated on the airless Moon." },
  { answer: "Gauss's Law", discipline: "Electromagnetics", accept: ["gausss law", "gauss law", "gauss"], clues: ["One of the four great equations of electromagnetism.", "It concerns a closed surface, not a path.", "Symmetry makes it enormously powerful — otherwise it is unwieldy.", "It explains why a Faraday cage works.", "Total electric flux through a closed surface is proportional to enclosed charge."], reveal: "The electric flux through any closed surface equals the enclosed charge divided by permittivity. For symmetric charge distributions it turns a difficult integral into simple algebra, and it's why a closed conductive shell — a Faraday cage — shields its interior." },
  { answer: "Just-In-Time Manufacturing", discipline: "Lean Manufacturing", accept: ["just in time manufacturing", "just in time", "jit"], clues: ["A production philosophy that treats inventory as a cost, not an asset.", "Materials arrive exactly when needed, not stockpiled in advance.", "It exposes problems that excess inventory would otherwise hide.", "It leaves a system with very little slack to absorb a supply disruption.", "A production strategy that receives goods only as they are needed in the process, minimising inventory."], reveal: "A production strategy that brings materials in only exactly when they're needed in the process, minimising inventory held on hand at any point. It deliberately removes the slack that excess inventory would otherwise provide, which exposes hidden problems in a process — but also leaves the whole system far more vulnerable to any disruption in supply." },
  { answer: "Brayton Cycle", discipline: "Thermodynamics", accept: ["brayton cycle", "brayton", "joule cycle"], clues: ["Compression, combustion, expansion — all continuous, not intermittent.", "Heat addition happens at constant pressure.", "Turbine inlet temperature is the key limit, set by blade materials.", "Its exhaust is hot enough to feed a second, different cycle.", "It's the cycle of a gas turbine or jet engine."], reveal: "The gas turbine cycle: adiabatic compression, constant-pressure heat addition, adiabatic expansion. Turbine inlet temperature is the real limiting factor, set by what the blade material and cooling scheme can survive, and the hot exhaust can drive a second cycle behind it." },
  { answer: "Inductive Proximity Sensor", discipline: "Sensors", accept: ["inductive proximity sensor", "proximity sensor"], clues: ["A sensor that detects presence without ever making physical contact.", "It only responds to one broad category of target material.", "That category is metal, specifically.", "It works by sensing how a nearby conductor disturbs a small oscillating magnetic field.", "A non-contact sensor detecting nearby metallic objects by sensing their effect on an oscillating magnetic field."], reveal: "A non-contact sensor that detects nearby metallic objects by generating a small oscillating magnetic field and sensing how a conductive target disturbs it through induced eddy currents. Because it relies specifically on that electromagnetic interaction, it only responds to metal — it's blind to plastic, wood or any other non-conductive material." },
  { answer: "Boolean Algebra", discipline: "Digital Logic", accept: ["boolean algebra"], clues: ["A form of algebra where every variable has only two possible values.", "Named after a 19th-century English mathematician and logician.", "AND, OR and NOT are its three fundamental operations.", "It underlies every digital circuit ever designed.", "The mathematical framework of true/false logic that digital circuits implement in hardware."], reveal: "The mathematical framework of two-valued logic — true and false, or 1 and 0 — built from the operations AND, OR and NOT. Every digital circuit, no matter how complex, is ultimately just an implementation of some Boolean expression in hardware." },
  { answer: "Paris' Law", discipline: "Solid Mechanics", accept: ["paris law", "paris equation", "paris erdogan law"], clues: ["It concerns growth, not initiation.", "Plotted log-log, the middle region is a straight line.", "Its slope is the exponent m, typically around 3 for steels.", "The driving quantity is the stress intensity factor range.", "It predicts crack growth per cycle: da/dN."], reveal: "da/dN = C(ΔK)^m — the rate of fatigue crack growth per cycle as a function of stress intensity range. Plotted log-log, the middle of its range forms a straight line, letting engineers predict how many cycles a known crack has left before it turns critical." },
  { answer: "Rate-Limiting Step", discipline: "Chemical Engineering", accept: ["rate limiting step", "rate determining step"], clues: ["In a chain of steps, one link decides the pace for the whole reaction.", "It's the slowest individual step in a multi-step process.", "Speeding up any of the other, faster steps does essentially nothing to the overall rate.", "Identify it correctly and you know exactly where to focus your optimisation effort.", "The slowest step in a multi-step reaction sequence, which controls the overall rate of the entire process."], reveal: "The single slowest step in a multi-step reaction sequence, which alone controls the overall rate of the entire process no matter how fast every other step runs. Speeding up any of the faster steps does essentially nothing for the overall reaction rate, which is exactly why identifying this one step correctly is the key to any process optimisation." },
  { answer: "Electron", discipline: "Physics", accept: ["electron"], clues: ["A particle so light it's often treated as having almost no mass at all, by comparison.", "It carries a negative charge and orbits an atom's much heavier, positively charged nucleus.", "Its movement through a conductor is, by definition, what electric current actually is.", "Gain or lose a few of these and a neutral atom turns into a charged ion.", "The negatively charged particle that orbits an atom's nucleus and carries electric current."], reveal: "A negatively charged particle, far lighter than a proton or neutron, that orbits an atom's nucleus. Its movement through a conductor is literally what electric current is, and gaining or losing a few of them turns a neutral atom into an ion." },
  { answer: "Jumper Wire", discipline: "Electronics", accept: ["jumper wire", "jumper cable", "breadboard wire"], clues: ["A wire whose whole job is temporary connection, not permanent installation.", "It's the go-to way to link two holes on a breadboard together.", "Pre-cut versions come with a pin on each end, ready to plug straight in.", "It carries no components of its own — just a path for current between two points.", "The short wire with a connector on each end used to link points on a breadboard or circuit."], reveal: "A short length of wire with a connector on each end, used to make a quick, temporary electrical link — most commonly between two points on a breadboard — without any soldering." },
  { answer: "Hacksaw", discipline: "Manufacturing", accept: ["hacksaw", "hack saw"], clues: ["A hand saw with a very rigid frame under tension around its blade.", "Its blade is designed to be replaced far more often than the tool itself.", "Fine teeth let it cut a material that a wood saw would just skip over.", "You'd reach for it before a wood saw if you needed to cut through a metal pipe.", "The hand saw with a thin, fine-toothed blade held in tension, used mainly to cut metal."], reveal: "A hand saw with a narrow, fine-toothed replaceable blade held under tension in a rigid frame, designed to cut metal — the fine teeth and rigidity are what a coarse wood-cutting blade lacks." },
  { answer: "Streamline", discipline: "Fluid Mechanics", accept: ["streamline", "streamlines"], clues: ["A line you can draw through a flow field, not a physical object.", "At every point along it, the tangent matches the local flow direction.", "In steady flow, a particle released into the fluid traces exactly this path.", "They never cross each other in the same flow field.", "An imaginary curve everywhere tangent to the local velocity vector of a flow."], reveal: "An imaginary curve drawn through a flow field such that, at every point, it's tangent to the local velocity vector. In steady flow it also traces the actual path a fluid particle follows, and because velocity has only one direction at any given point, streamlines can never cross." },
  { answer: "Nut", discipline: "Mechanical Design", accept: ["nut", "hex nut"], clues: ["A fastener defined entirely by the hole running through its center.", "It has no head of its own — it's just a threaded ring.", "Six flat sides let a wrench grip it from any angle to turn it.", "It threads onto a bolt's shaft, clamping the assembly together from the far side.", "The small threaded fastener with a hole through the center, tightened onto a matching bolt."], reveal: "A small fastener with internal threads running through its center, designed to thread onto a matching bolt and clamp a joint together from the opposite side. Its hexagonal outer shape lets a wrench grip it from any angle." },
  { answer: "Butterworth Filter", discipline: "Signal Processing", accept: ["butterworth filter", "butterworth"], clues: ["A filter designed to prioritise one quality above almost everything else.", "That priority is a passband with no ripple at all.", "The tradeoff is a roll-off that's gentler than some rival designs.", "Named after a British engineer who published the design in 1930.", "A filter design characterised by a maximally flat passband response, at the cost of a more gradual roll-off."], reveal: "A filter design characterised by a maximally flat passband — no ripple at all in the frequencies it's meant to pass — at the cost of a more gradual roll-off than steeper designs like the Chebyshev filter. Published by a British engineer in 1930, it remains one of the most widely used general-purpose filter designs." },
  { answer: "Lift Coefficient", discipline: "Aerodynamics", accept: ["lift coefficient", "cl"], clues: ["The lift-generating counterpart to a more famous drag-related number.", "It rises with angle of attack, up to a point.", "Push past that point and it suddenly collapses — the stall.", "It depends on airfoil shape as much as on speed.", "C_L in L = ½ρV²C_LA — the dimensionless factor scaling lift with airfoil shape and angle of attack."], reveal: "A dimensionless number capturing how effectively an airfoil shape converts dynamic pressure into lift at a given angle of attack. It climbs steadily as angle of attack increases, until the flow separates from the upper surface and the coefficient collapses abruptly — the aerodynamic stall." },
  { answer: "Hall-Petch Relationship", discipline: "Materials", accept: ["hall petch", "hall petch relationship", "hall petch equation"], clues: ["It relates a mechanical property to a microstructural feature.", "It involves an inverse square root.", "Grain boundaries impede dislocation movement.", "Smaller is stronger, until you get to the nanoscale and it inverts.", "It explains why grain refinement is a strengthening mechanism."], reveal: "σ_y = σ_0 + k/√d — yield strength increases as grain size decreases. Smaller grains mean more boundaries to block dislocation motion, the whole basis of grain refinement as a strengthening strategy — until the nanoscale, where the trend actually reverses." },
  { answer: "Bathtub Curve", discipline: "Reliability Engineering", accept: ["bathtub curve", "bath tub curve"], clues: ["It's named for its shape, not its function.", "Three distinct regions across a product's life.", "The middle region is flat and random.", "Burn-in testing exists to skip past the first region.", "It plots failure rate against time."], reveal: "The failure-rate-versus-time curve showing infant mortality, a constant random period, and wear-out. Burn-in testing exists specifically to weed out the early, defect-driven failures before a product ever reaches a customer." },
  { answer: "Integrated Circuit", discipline: "Computer Engineering", accept: ["integrated circuit", "ic", "microchip", "chip"], clues: ["A tiny slice of semiconductor containing what used to require an entire room of components.", "Thousands, or billions, of transistors are etched directly onto a single small piece of it.", "Jack Kilby and Robert Noyce are both separately credited with helping invent it.", "You'd recognize its usual black plastic package with rows of small metal legs along the edges.", "The small semiconductor chip containing a complete electronic circuit, often with millions of transistors."], reveal: "A complete electronic circuit — sometimes billions of transistors — miniaturized and etched onto a single small piece of semiconductor. Its invention, credited independently to Jack Kilby and Robert Noyce, is what made modern compact electronics possible." },
  { answer: "Series Circuit", discipline: "Electrical Engineering", accept: ["series circuit"], clues: ["A circuit with exactly one path for current to take, and no other option.", "Break the connection at any single point, and every component on that loop goes dark.", "The same current flows through every component along it, without exception.", "Old-style string lights were a famous example — one bulb dies, the whole strand goes out.", "A circuit where components are connected end to end along a single path, so the same current flows through each."], reveal: "A circuit where components are connected end to end along a single path, so the same current flows through every one of them. Break the loop anywhere and the whole circuit stops — the classic failure mode of old string lights." },
  { answer: "Mohr-Coulomb Failure Criterion", discipline: "Geotechnical Engineering", accept: ["mohr coulomb", "mohr coulomb failure criterion", "mohr coulomb criterion"], clues: ["It combines two engineers' names from different centuries.", "It's a straight-line envelope tangent to a family of circles.", "Its intercept and slope have physical names.", "Those names are cohesion and angle of internal friction.", "It's the standard shear strength model for soil and rock."], reveal: "τ = c + σ tan φ — shear strength as a linear function of normal stress, via cohesion and friction angle. Plotted as a straight line tangent to a family of Mohr's circles, it remains the standard way geotechnical engineers describe when soil or rock will fail." },
  { answer: "State-Space Representation", discipline: "Control Systems", accept: ["state space representation", "state space model", "state space"], clues: ["An alternative to the transfer function, better suited to complex systems.", "It describes a system with first-order differential equations, not one high-order one.", "It handles multiple inputs and multiple outputs naturally, unlike a single transfer function.", "Its core objects are matrices, usually named A, B, C and D.", "ẋ = Ax + Bu, y = Cx + Du — a time-domain description of a system's internal state evolution."], reveal: "A time-domain description of a system using a set of coupled first-order differential equations, ẋ = Ax + Bu and y = Cx + Du, built from matrices rather than one high-order transfer function. It handles multiple inputs and outputs naturally and exposes a system's internal state directly, which is why it underpins modern control techniques like the Kalman filter." },
  { answer: "Valve", discipline: "Fluid Machinery", accept: ["valve"], clues: ["A component whose entire job is to control whether, and how much, something can flow.", "Open it fully, close it completely, or set it somewhere in between — its whole function is regulation.", "A garden hose's shutoff nozzle is one of the simplest everyday examples.", "The human heart relies on four of them to keep blood flowing in only one direction.", "The device used to control, direct or regulate the flow of a fluid through a pipe or opening."], reveal: "A device that controls, directs, or regulates the flow of a fluid through a system — anywhere from fully open to fully shut, or one-way only, as with the four valves keeping blood flowing correctly through a human heart." },
  { answer: "Orifice Plate", discipline: "Instrumentation", accept: ["orifice plate", "orifice meter"], clues: ["One of the simplest and cheapest flow meters ever devised.", "A flat plate with a precisely sized hole, bolted into a pipeline.", "It works by forcing a pressure drop across itself.", "That pressure drop is compared using the same physics behind a Venturi meter.", "A restriction plate that measures flow rate from the pressure drop it creates."], reveal: "A thin plate with a precisely sized hole, installed across a pipeline so the pressure drop it creates can be related to flow rate. It's cheap and simple compared to a Venturi meter, at the cost of a permanent, unrecoverable pressure loss downstream." },
  { answer: "Metal File", discipline: "Manufacturing", accept: ["file", "metal file", "hand file"], clues: ["A hand tool covered edge to edge in tiny raised cutting teeth.", "It removes material a little at a time, with every stroke in one direction.", "Different tooth patterns range from rough shaping to fine finishing.", "You drag it across a rough edge, again and again, to smooth it down.", "The hand tool with a rough, toothed surface used to smooth or shape metal by hand."], reveal: "A hand tool covered in rows of small, angled cutting teeth, dragged across a surface to remove material and smooth or shape it. Coarser tooth patterns cut faster and rougher; finer patterns leave a smoother finish." },
  { answer: "pH", discipline: "Chemistry", accept: ["ph", "ph scale"], clues: ["A logarithmic scale, which is why moving one whole unit is such a big deal.", "It measures the concentration of one specific ion.", "Seven sits at the exact neutral midpoint, at least in pure water at room temperature.", "Each step down the scale represents a tenfold increase in that ion's concentration.", "A logarithmic measure of hydrogen ion concentration in a solution, indicating acidity or alkalinity."], reveal: "A logarithmic measure of hydrogen ion concentration in a solution, running from acidic through neutral at 7 to alkaline. Because the scale is logarithmic, each single-unit drop represents a full tenfold increase in hydrogen ion concentration — meaning a solution at pH 4 is a hundred times more acidic than one at pH 6, not just twice." },
  { answer: "Robot Workspace", discipline: "Robotics", accept: ["robot workspace", "workspace"], clues: ["The complete set of points a robot's end effector could ever possibly reach.", "It's shaped entirely by link lengths and joint limits, nothing else.", "A point just outside its boundary is permanently, geometrically unreachable.", "Within it, some points can be reached in only one way; others in many.", "The complete set of positions and orientations a robot's end effector can physically reach."], reveal: "The complete set of positions, and sometimes orientations, that a robot's end effector can physically reach, shaped entirely by its link lengths and joint range limits. A point sitting just outside that boundary isn't merely difficult to reach — it's permanently, geometrically unreachable, no matter how the joints are commanded." },
  { answer: "Conductor", discipline: "Electromagnetics", accept: ["conductor", "electrical conductor"], clues: ["A material defined by how loosely it holds onto its outermost electrons.", "Metals are the most familiar example, thanks to electrons that move freely through them.", "Wrap this kind of material around your finger and current would happily pass right through it.", "It's the opposite of an insulator in almost every electrical sense.", "A material that allows electric current to flow through it easily."], reveal: "A material whose outer electrons move freely between atoms, letting electric current pass through it easily. Metals are the classic example — the opposite of an insulator, whose electrons stay tightly bound." },
  { answer: "Race Condition", discipline: "Software Engineering", accept: ["race condition", "race conditions", "data race"], clues: ["The bug that only appears on the customer's machine.", "It depends on timing you don't control.", "Adding a print statement often makes it disappear.", "Mutexes, atomics and locks exist to prevent it.", "Two threads access shared state and the outcome depends on ordering."], reveal: "A defect where correctness depends on the unpredictable relative timing of concurrent operations. It's notoriously hard to reproduce on demand — a debug print statement can shift the timing just enough to make it vanish — which is why mutexes and atomics exist." },
  { answer: "Thermal Conductivity", discipline: "Heat Transfer", accept: ["thermal conductivity"], clues: ["A material property, in watts per metre-kelvin.", "Metals tend to sit at the high end of the scale; gases at the low end.", "It's the constant of proportionality in Fourier's law of conduction.", "Diamond, oddly, conducts heat better than most metals.", "A measure of a material's ability to conduct heat, symbol k."], reveal: "A material property quantifying how readily heat conducts through a substance, measured in watts per metre-kelvin and denoted k. Metals typically sit at the high end thanks to free electrons carrying energy efficiently, while gases sit at the low end — with diamond a famous outlier, conducting heat better than almost any metal despite being an electrical insulator." },
  { answer: "Castigliano's Theorem", discipline: "Structural Engineering", accept: ["castiglianos theorem", "castigliano"], clues: ["An energy method, not a force-balance method.", "You differentiate a scalar quantity to get a vector one.", "It handles curved members and frames elegantly.", "You sometimes add a dummy load just to differentiate with respect to it.", "Partial derivative of strain energy gives deflection."], reveal: "Deflection at a point equals the partial derivative of total strain energy with respect to the load applied there. It handles curved members and complex frames elegantly, and engineers sometimes add a fictitious 'dummy' load purely to differentiate with respect to." },
  { answer: "MEMS", discipline: "Sensors", accept: ["mems", "micro electro mechanical systems"], clues: ["Machines so small they're measured in micrometres, not millimetres.", "They're fabricated using the same processes that build computer chips.", "Moving mechanical parts and electronics sit side by side on the same tiny device.", "They're why a modern accelerometer fits on a chip instead of filling a box.", "Miniaturised mechanical and electromechanical devices fabricated using semiconductor manufacturing techniques."], reveal: "Miniaturised mechanical and electromechanical structures, fabricated using the same photolithographic processes that build computer chips, with moving parts measured in micrometres. That manufacturing approach is exactly why modern accelerometers, gyroscopes and pressure sensors shrank from bulky standalone devices down to a single low-cost chip." },
  { answer: "Welding Torch", discipline: "Manufacturing", accept: ["welding torch", "welding gun", "oxy torch"], clues: ["A tool that joins two pieces of metal by melting them, not by mechanically fastening them.", "Some versions burn a mix of gases; others strike an electric arc instead.", "The filler rod it feeds in melts right alongside the base metal.", "You'd reach for one to fuse a crack shut, not to just clamp it closed.", "The tool that melts metal, often with an electric arc or gas flame, to fuse pieces together."], reveal: "A tool that generates intense localized heat — from a gas flame or an electric arc — to melt the edges of two metal pieces (and often a filler rod) so they fuse into one continuous joint as they cool." },
  { answer: "Washer", discipline: "Mechanical Design", accept: ["washer"], clues: ["A component so simple it's just a flat disk with a hole, and nothing else.", "It sits under a bolt head or nut, doing a job neither of them can do alone.", "It spreads out the clamping force over a wider area, protecting the surface underneath.", "Some versions are split or toothed specifically to resist a fastener loosening over time.", "The flat disk placed under a bolt head or nut to spread out load and prevent loosening."], reveal: "A flat disk with a center hole, placed under a bolt head or nut to spread the clamping force over a wider area and protect the surface beneath — some variants are split or toothed to help resist the fastener loosening under vibration." },
  { answer: "Magnetic Resonance Imaging", discipline: "Biomedical Engineering", accept: ["magnetic resonance imaging", "mri"], clues: ["A medical imaging technique that uses no ionising radiation at all.", "It relies on the magnetic behaviour of hydrogen nuclei in the body's water and fat.", "A powerful magnetic field aligns them; radio pulses then knock them out of alignment.", "It excels at distinguishing between different types of soft tissue, unlike a standard X-ray.", "A medical imaging technique using strong magnetic fields and radio waves to image soft tissue in the body."], reveal: "A medical imaging technique that uses a strong magnetic field to align hydrogen nuclei in the body's water and fat, then radio pulses to knock them briefly out of alignment and measures the signal as they realign. Because it distinguishes soft tissue types so well, and uses no ionising radiation at all, it's often preferred over X-ray or CT for imaging the brain and other soft tissues." },
  { answer: "Moody Chart", discipline: "Fluid Mechanics", accept: ["moody chart", "moody diagram"], clues: ["A single log-log plot that has appeared in every fluids textbook since 1944.", "The left region is a straight line; the right region flattens out.", "Curves are labelled with relative roughness.", "You enter with Reynolds number and read off a factor.", "That factor is the Darcy friction factor."], reveal: "The log-log chart giving the Darcy friction factor as a function of Reynolds number and relative pipe roughness. Its left region is a clean straight line for laminar flow, while the right region flattens out as roughness, not viscosity, comes to dominate." },
  { answer: "MOSFET", discipline: "Electronics", accept: ["mosfet", "metal oxide semiconductor field effect transistor"], clues: ["Unlike its older cousin, it's controlled by voltage, not current.", "Almost no current flows into its control terminal at all.", "It's the switching component inside virtually every digital chip ever made.", "Its name describes its layered construction: metal, oxide, semiconductor.", "A voltage-controlled transistor whose gate terminal draws essentially no steady current."], reveal: "A voltage-controlled transistor whose gate terminal, insulated from the channel by a thin oxide layer, draws essentially no steady current to control conduction. That combination of near-zero gate current and easy fabrication at tiny scales is exactly why it became the switching element inside virtually every digital integrated circuit." },
  { answer: "Reinforcement Learning", discipline: "Machine Learning", accept: ["reinforcement learning", "rl"], clues: ["A learning paradigm with no labelled examples to learn from at all.", "An agent learns purely by acting and observing the consequences.", "Good outcomes get rewarded; bad outcomes get penalised.", "It's the paradigm behind computer programs that learned to master Go and complex video games from scratch.", "A learning paradigm where an agent learns to act by receiving rewards or penalties from its environment."], reveal: "A learning paradigm in which an agent learns to act purely through trial and error, receiving rewards or penalties from its environment rather than being shown labelled correct answers. It's the paradigm behind systems that learned to master games like Go and complex video games essentially from scratch, through millions of self-played trials." },
  { answer: "Pareto Principle", discipline: "Quality Engineering", accept: ["pareto principle", "pareto", "80 20 rule", "pareto chart"], clues: ["It began as an observation about land ownership in Italy.", "Juran applied it to quality and gave it a memorable slogan.", "That slogan is 'the vital few and the trivial many'.", "Its chart form is bars descending, with a cumulative line over them.", "Commonly stated as an 80/20 split."], reveal: "The observation that a small proportion of causes typically accounts for the large majority of effects. Juran popularised it in quality work as 'the vital few and the trivial many,' and its chart form — descending bars with a cumulative line — is a staple of root-cause prioritisation." },
  { answer: "Superposition Theorem", discipline: "Electrical Engineering", accept: ["superposition theorem", "superposition"], clues: ["It only works because the underlying system is linear.", "You solve a circuit with many sources by handling them one at a time.", "Turn off every source but one, solve, then repeat for the next.", "Voltage sources get shorted and current sources get opened when they're 'off'.", "The total response of a linear circuit equals the sum of responses to each independent source acting alone."], reveal: "In any linear circuit with multiple independent sources, the total response at any point equals the sum of the responses produced by each source acting alone, with every other source turned off. Turning a source 'off' means shorting a voltage source or open-circuiting a current source, never simply deleting it." },
  { answer: "Routh-Hurwitz Stability Criterion", discipline: "Control Systems", accept: ["routh hurwitz stability criterion", "routh hurwitz criterion", "routh hurwitz", "routh array"], clues: ["A stability check that needs no plotting at all — just arithmetic.", "It works directly on the coefficients of a characteristic equation.", "You arrange those coefficients into a table and check one column for sign changes.", "Any sign change in that column means an unstable root exists.", "A tabular method determining how many roots of a characteristic equation lie in the right half of the complex plane."], reveal: "A purely algebraic method, arranging a characteristic equation's coefficients into a table called the Routh array, that determines how many roots lie in the unstable right half of the complex plane without ever having to solve for the roots directly. Any sign change down the array's first column signals an unstable pole." },
  { answer: "Joule-Thomson Effect", discipline: "Thermodynamics", accept: ["joule thomson effect", "joule kelvin effect"], clues: ["A real gas doesn't quite follow the ideal gas law here, and that's the whole point.", "It happens when a gas is forced through a restriction with no heat exchange.", "For most gases at room temperature, it produces cooling.", "Hydrogen and helium are the well-known exceptions — they warm up instead.", "The temperature change of a real gas as it expands through a valve or porous plug at constant enthalpy."], reveal: "The temperature change a real gas undergoes when forced through a throttling valve or porous plug at constant enthalpy, with no heat exchanged and no work done. Most gases cool on expansion — the working principle behind gas liquefaction plants — but hydrogen and helium actually warm up instead unless pre-cooled below their inversion temperature." },
  { answer: "Spirit Level", discipline: "Civil Engineering", accept: ["spirit level", "bubble level", "level"], clues: ["A tool with a liquid-filled tube at its center, doing all the actual work.", "A trapped bubble inside it always drifts toward whichever side sits higher.", "Center that bubble between two marked lines and you've found true horizontal.", "You'd rest it on a shelf before drilling in the mounting screws.", "The tool with a bubble in a liquid-filled tube used to check whether a surface is level."], reveal: "A tool with a curved, liquid-filled tube containing a trapped air bubble that drifts toward the higher side. Center the bubble between two reference lines and the surface underneath is level." },
  { answer: "Brinell Hardness Test", discipline: "Materials", accept: ["brinell hardness test", "brinell hardness", "brinell test", "brinell"], clues: ["It presses a hard ball into a surface and measures the dent.", "The load is applied for a set dwell time, then removed.", "The result comes from the diameter of the resulting indentation, not its depth.", "It's better suited to coarse-grained or cast materials than the alternative Rockwell test.", "Named after a Swedish engineer, and abbreviated HB."], reveal: "A hardness test that presses a hardened steel or carbide ball into a surface under a known load and measures the diameter of the resulting indentation. Larger, coarser indentations make it well suited to cast metals and forgings where a finer test would be thrown off by local microstructure." },
  { answer: "Fourier Transform", discipline: "Signal Processing", accept: ["fourier transform", "fourier", "fft"], clues: ["It swaps one domain for another.", "Any periodic signal can be built up from sines and cosines.", "A pure tone becomes a single spike.", "Its fast algorithm turned an O(n²) job into O(n log n).", "Named after the French mathematician who also studied heat conduction."], reveal: "A transform decomposing a time-domain signal into its constituent frequency components. Filtering, compression and spectral analysis all become far simpler once a signal is viewed this way instead of as a trace against time." },
  { answer: "Flywheel", discipline: "Dynamics", accept: ["flywheel"], clues: ["A component whose entire job is to resist a change in rotational speed.", "It stores energy not as heat or charge, but as pure rotational motion.", "A potter's wheel keeps spinning smoothly between kicks partly because of one.", "An engine's crankshaft speed stays smooth between power strokes largely thanks to one.", "A heavy rotating disk used to store rotational energy and smooth out variations in speed."], reveal: "A heavy rotating mass, typically a disk, that stores energy in its rotation and resists changes to its spin speed through rotational inertia. It's what smooths out an engine's power delivery between individual combustion strokes." },
  { answer: "Overall Equipment Effectiveness", discipline: "Manufacturing", accept: ["oee", "overall equipment effectiveness"], clues: ["A single percentage that plant managers watch closely.", "It's the product of three separate ratios.", "Those are availability, performance and quality.", "85% is considered world-class, which surprises people.", "Its three-letter abbreviation starts with O."], reveal: "OEE = availability × performance × quality — a composite measure of manufacturing productivity. Because it multiplies three ratios together, small losses in each one compound quickly, which is why a plant running at 85% is considered world-class." },
  { answer: "Specific Impulse", discipline: "Aerospace Engineering", accept: ["specific impulse", "isp"], clues: ["A measure of efficiency, quoted confusingly in seconds.", "Chemical rockets manage a few hundred; ion thrusters manage thousands.", "It is exhaust velocity divided by standard gravity.", "Higher values mean less propellant for the same job.", "Abbreviated Isp."], reveal: "Thrust per unit propellant weight flow rate — a measure of rocket propellant efficiency, quoted in seconds. Chemical rockets typically manage a few hundred seconds while electric ion thrusters reach into the thousands, trading thrust for far greater efficiency." },
  { answer: "Deadlock", discipline: "Computer Science", accept: ["deadlock"], clues: ["A situation where everyone is waiting, and nobody is moving.", "It needs at least two competing processes and shared resources.", "Each side holds something the other one needs.", "Four specific conditions must all hold simultaneously for it to occur.", "A state where two or more processes are each waiting on a resource the other holds, so none can proceed."], reveal: "A state in which two or more processes are each waiting on a resource held by the other, so none of them can ever proceed. It requires four conditions to hold simultaneously — mutual exclusion, hold-and-wait, no preemption, and circular wait — which is exactly why breaking just one of them is enough to prevent it." },
  { answer: "Power Factor", discipline: "Electrical Power", accept: ["power factor", "pf", "cos phi"], clues: ["A number between 0 and 1 that utilities charge you for.", "Motors and fluorescent ballasts drag it downward.", "Capacitor banks are installed specifically to correct it.", "It's the cosine of the phase angle between voltage and current.", "Real power divided by apparent power."], reveal: "The ratio of real power to apparent power in an AC circuit, reflecting phase displacement and harmonic distortion. Inductive loads like motors drag it below one by pushing current out of phase with voltage, which is why utilities install capacitor banks to correct it." },
  { answer: "Convex Lens", discipline: "Optics", accept: ["convex lens", "converging lens"], clues: ["A lens shaped so it's thicker in the middle than at its edges.", "Parallel light rays passing through it are bent inward, converging toward a single point.", "A magnifying glass is the most familiar everyday example of this lens shape.", "A farsighted person's glasses typically use this shape to help focus close-up images.", "The lens, thicker in the middle than at the edges, that bends light rays inward to a focal point."], reveal: "A lens that's thicker at its center than at its edges, bending parallel light rays inward to converge at a focal point. It's the shape behind a magnifying glass, and the corrective lens typically prescribed for farsightedness." },
  { answer: "Continuous Stirred-Tank Reactor", discipline: "Chemical Engineering", accept: ["continuous stirred tank reactor", "cstr", "stirred tank reactor"], clues: ["A reactor built around one core idealisation: perfect, instantaneous mixing.", "Whatever concentration exists inside it is, by assumption, identical everywhere, including right at the outlet.", "Reactants entering are instantly diluted to that same low, already-reacted concentration.", "It generally needs more volume than a tubular reactor to hit the same conversion.", "An idealised reactor model assuming perfect, instantaneous mixing so conditions are uniform throughout."], reveal: "An idealised reactor model assuming perfect, instantaneous mixing, so concentration and temperature are uniform everywhere inside — including right at the outlet, which is assumed identical to the bulk. Fresh reactant entering is instantly diluted down to that same, already partly reacted concentration, which is exactly why it typically needs more volume than a plug flow reactor to reach the same conversion." },
  { answer: "Voltmeter", discipline: "Instrumentation", accept: ["voltmeter"], clues: ["A meter that must be connected across a component, never in line with it.", "Its internal resistance is deliberately made very high, so it barely disturbs the circuit it's measuring.", "It answers exactly one question: how big is the potential difference between these two points?", "You'd touch its two leads to the two terminals of a battery to check it isn't dead.", "The meter that measures the voltage, or potential difference, between two points in a circuit."], reveal: "A meter connected across a component to measure the potential difference between its two terminals. It's built with very high internal resistance so that connecting it barely draws any current, leaving the circuit it's measuring undisturbed." },
  { answer: "Geometric Dimensioning and Tolerancing", discipline: "Mechanical Design", accept: ["gdt", "gd t", "geometric dimensioning and tolerancing", "gd&t"], clues: ["A symbolic language on a drawing, standardised as ASME Y14.5 and ISO 1101.", "It controls form, orientation, location and runout.", "Datums establish the frame everything is measured from.", "Maximum material condition can grant bonus tolerance.", "Its position control uses a circle with a cross in it."], reveal: "A symbolic drawing language specifying permissible variation in part geometry relative to defined datums. Everything is measured from an established datum reference frame rather than arbitrary edges, and features can even earn bonus tolerance as their size departs from worst case." },
  { answer: "Radiation", discipline: "Heat Transfer", accept: ["radiation", "thermal radiation", "radiative heat transfer"], clues: ["A mode of heat transfer that needs no matter at all to travel between two points.", "It's how the Sun's warmth reaches Earth, crossing millions of miles of empty vacuum.", "Every object above absolute zero emits some of it, whether you can see the glow or not.", "Stand near a campfire and feel warmth even without touching the flame — that's this at work.", "The transfer of heat as electromagnetic waves, requiring no medium to travel through."], reveal: "Heat transfer carried by electromagnetic waves, needing no medium at all to travel through — which is how the Sun warms Earth across empty vacuum. Every object above absolute zero radiates some of it, visibly or not." },
  { answer: "Combination Square", discipline: "Metrology", accept: ["combination square", "combo square"], clues: ["A measuring tool that folds several separate jobs into one sliding component.", "A ruler slides through a movable head that can check both a right angle and a 45-degree miter.", "A small built-in bubble vial even lets it double as a basic level.", "Woodworkers use it to mark a line square across a board before ever making a cut.", "The measuring tool with a sliding ruler and adjustable head used to check angles and mark lines."], reveal: "A measuring tool with a ruler that slides through an adjustable head, letting a single tool check a 90-degree or 45-degree angle, mark a line, gauge depth, and often check level, all from one sliding assembly." },
  { answer: "Static Electricity", discipline: "Electromagnetics", accept: ["static electricity", "static charge"], clues: ["A charge that builds up and stays put, rather than flowing continuously as current.", "Rubbing two different materials together is often enough to transfer it between them.", "It's the reason a balloon rubbed on your hair will stick to a wall for a few minutes.", "A sudden, sharp spark when you touch a doorknob is this charge finally discharging.", "An imbalance of electric charge built up on a surface, typically from friction, that doesn't flow as current."], reveal: "An imbalance of electric charge sitting on a surface, usually built up by friction transferring electrons between two materials. It doesn't flow continuously like current — it just sits there until it suddenly discharges, often as a visible spark." },
  { answer: "CPU Cache", discipline: "Computer Engineering", accept: ["cpu cache", "cache memory", "cache"], clues: ["A small, fast memory sitting between the processor and something much slower.", "It exploits the fact that recently used data tends to be needed again soon.", "It usually comes in tiered levels, each bigger and slower than the last.", "A request that finds its data here is called a hit; one that doesn't is a miss.", "A small, fast memory layer storing recently or frequently accessed data to reduce average access time to main memory."], reveal: "A small, fast memory layer sitting between the processor and much slower main memory, storing recently or frequently accessed data so most requests never have to wait on the slower memory at all. It exploits locality of reference — the tendency for recently used data to be needed again soon — and is typically organised into multiple tiers of increasing size and decreasing speed." },
  { answer: "Isotope", discipline: "Nuclear Engineering", accept: ["isotope"], clues: ["Two atoms sharing an identical chemical identity while differing in mass.", "They share the exact same number of protons, but a different number of neutrons.", "One common one is used to date ancient organic material, based on its steady decay rate.", "Carbon-12 and carbon-14 are two well-known examples of the same underlying element.", "One of two or more forms of an element with the same number of protons but a different number of neutrons."], reveal: "One of two or more variants of the same element, sharing an identical number of protons but differing in neutron count, and so in atomic mass. Carbon-14's steady decay rate is exactly what radiocarbon dating relies on." },
  { answer: "Elasticity", discipline: "Solid Mechanics", accept: ["elasticity"], clues: ["A property that describes a material's ability to undo its own deformation.", "Remove the load, and a material with this property snaps right back to its original shape.", "Push it too far, past its elastic limit, and the deformation becomes permanent instead.", "A rubber band demonstrates it far more dramatically than a steel bar does.", "A material's ability to return to its original shape after a deforming force is removed."], reveal: "A material's ability to return to its original shape once a deforming force is removed, as long as it hasn't been stretched past its elastic limit into permanent deformation. Rubber shows it dramatically; steel shows it too, just over a much smaller range." },
  { answer: "Molecule", discipline: "Chemistry", accept: ["molecule"], clues: ["A structure that can be made of just one type of atom, or several bonded together.", "Break the bonds holding it together and you no longer have the same substance.", "Two hydrogen atoms and one oxygen atom, bonded, give you the most familiar example on Earth.", "It's the smallest unit of a compound that still has that compound's chemical properties.", "Two or more atoms bonded together, the smallest unit that still behaves like the substance."], reveal: "Two or more atoms held together by chemical bonds, forming the smallest unit that still carries the chemical identity of a substance. Break those bonds and you're left with something chemically different — like splitting water into hydrogen and oxygen." },
  { answer: "Crystal Oscillator", discipline: "Electronics", accept: ["crystal oscillator", "quartz crystal", "crystal"], clues: ["A component that vibrates at an extremely precise, repeatable rate when you apply voltage to it.", "It relies on a property of quartz where mechanical stress and electric charge are linked.", "Nearly every digital clock and microcontroller relies on one to keep exact time.", "Squeeze the right cut of quartz and it generates a voltage; apply voltage and it vibrates back.", "The quartz-based component that vibrates at a precise frequency, used to keep time in electronic circuits."], reveal: "A component, typically a precisely cut quartz crystal, that vibrates at an extremely stable, repeatable frequency when voltage is applied, thanks to the piezoelectric effect. That steady vibration is what keeps time in everything from wristwatches to microcontrollers." },
  { answer: "3D Printer", discipline: "Manufacturing", accept: ["3d printer", "three-d printer", "fdm printer"], clues: ["A machine that builds an object up, one thin layer at a time, rather than cutting it down from stock.", "It's an additive process, the direct opposite of what a lathe or mill does.", "A common version melts a spool of plastic filament and extrudes it through a nozzle.", "A digital 3D model is the input; a physical part is the output.", "The machine that builds physical objects layer by layer from a digital design."], reveal: "A machine that builds a physical part layer by layer from a digital model, adding material rather than removing it — the opposite approach to a lathe or mill's subtractive machining. A common desktop version melts and extrudes plastic filament." },
  { answer: "Finite Element Analysis", discipline: "Structural Engineering", accept: ["finite element analysis", "fea", "finite element method", "fem"], clues: ["It replaces one impossible problem with thousands of easy ones.", "Mesh quality can matter more than material data.", "Convergence studies exist because the answer depends on discretisation.", "It solves a large sparse system, usually written [K]{u} = {F}.", "Its three-letter abbreviation is on every stress engineer's CV."], reveal: "A numerical method that discretises a continuum into elements to approximate solutions to field problems. Refine the mesh and the approximate answer converges toward the true one, at the cost of solving an ever-larger system of equations." },
  { answer: "Stokes' Law", discipline: "Fluid Mechanics", accept: ["stokes law", "stokes drag"], clues: ["It applies only when inertia is negligible.", "Valid for Reynolds numbers well below one.", "Drag is proportional to velocity, not velocity squared.", "It gives you the terminal velocity of a settling particle.", "F = 6πμrv."], reveal: "The drag force on a small sphere in creeping viscous flow: F = 6πμrv. It only holds where inertia is negligible compared to viscosity — exactly the regime that sets the terminal settling velocity of fine particles in a fluid." },
  { answer: "Photoresistor", discipline: "Sensors", accept: ["photoresistor", "light dependent resistor", "ldr"], clues: ["A component whose resistance value is controlled by something other than voltage or current.", "Shine more light on it, and its electrical resistance drops sharply.", "Streetlights that switch on automatically at dusk often rely on one to sense falling light levels.", "It's essentially a resistor that reacts to brightness instead of staying fixed.", "The light-sensitive component whose electrical resistance decreases as more light falls on it."], reveal: "A light-sensitive resistor whose resistance drops as more light falls on it, and rises in darkness — the sensing element behind streetlights and night-lights that switch on automatically as it gets dark." },
  { answer: "SLAM", discipline: "Robotics", accept: ["slam", "simultaneous localization and mapping", "simultaneous localisation and mapping"], clues: ["A problem that sounds circular, because in a sense it is.", "A robot needs a map to know where it is, and needs to know where it is to build a map.", "It solves both problems together, incrementally, at the same time.", "Autonomous vacuum cleaners and self-driving cars both rely on some version of it.", "The problem of a robot building a map of an unknown environment while simultaneously tracking its own position within it."], reveal: "The problem of a robot building a map of an entirely unknown environment while simultaneously tracking its own position within that same map — two problems that each seem to depend on solving the other first. Algorithms solve both incrementally and together, and it's the technique behind everything from robot vacuum cleaners to self-driving cars navigating unfamiliar streets." },
  { answer: "Karnaugh Map", discipline: "Digital Logic", accept: ["karnaugh map", "k map", "kmap", "karnaugh"], clues: ["A grid you fill with ones and zeros.", "Adjacent cells differ by exactly one bit — Gray code ordering.", "You group ones in powers of two, and groups may wrap around edges.", "Don't-care conditions can be used opportunistically.", "It minimises a Boolean expression graphically."], reveal: "A grid-based method for simplifying Boolean expressions by grouping adjacent minterms. Its cells are arranged in Gray code order so any two physically adjacent cells differ by only one bit, letting you spot simplifications visually instead of through algebra." },
  { answer: "Fault Tree Analysis", discipline: "Safety Engineering", accept: ["fault tree analysis", "fta", "fault tree"], clues: ["A deductive method, working in the opposite direction to FMEA.", "You start with the undesired outcome and work downward.", "The diagram uses AND and OR gates.", "Minimal cut sets identify the smallest combinations that cause failure.", "Developed at Bell Labs for the Minuteman missile programme."], reveal: "A top-down deductive method tracing an undesired top event to combinations of contributing basic failures. AND and OR gates link the basic failures together, and finding the minimal cut sets tells engineers exactly where redundancy is most worth adding." },
  { answer: "Parallel Circuit", discipline: "Electrical Engineering", accept: ["parallel circuit"], clues: ["A circuit that offers current more than one route to choose from.", "Every branch across it sees the same voltage, even though currents can differ.", "Unplug one lamp from a modern power strip and the others stay lit.", "Household wiring is built this way specifically so one dead appliance doesn't kill the rest.", "A circuit where components are connected across the same two points, giving current multiple paths."], reveal: "A circuit where components are connected across the same two nodes, giving current multiple paths to flow and holding the same voltage across every branch. It's why unplugging one lamp in a house doesn't turn off the rest." },
  { answer: "Fick's Law of Diffusion", discipline: "Materials", accept: ["ficks law", "fick law", "fick"], clues: ["It has the same mathematical form as two other famous transport laws.", "Flux is proportional to a gradient, with a minus sign.", "Its second form is a partial differential equation in time.", "It governs case hardening and dopant diffusion in silicon.", "The gradient in question is concentration."], reveal: "J = −D dC/dx — diffusive flux is proportional to the negative concentration gradient. Its second form turns this into a time-dependent partial differential equation, which is what actually governs processes like case hardening and dopant diffusion in silicon." },
  { answer: "Clausius-Clapeyron Equation", discipline: "Thermodynamics", accept: ["clausius clapeyron equation", "clausius clapeyron"], clues: ["It links two curves on a phase diagram that most people never think to connect.", "It relates a slope to a latent heat.", "It explains why water boils at a lower temperature on a mountaintop.", "Pressure cookers exploit the reverse of that same relationship.", "It describes how the equilibrium vapour pressure of a substance changes with temperature."], reveal: "An equation describing how a substance's equilibrium vapour pressure — the slope of its phase boundary — varies with temperature, in terms of its latent heat of transition. It explains why water boils at a lower temperature at high altitude, and why a sealed pressure cooker can push water's boiling point well above 100°C." },
  { answer: "Open-Loop Control", discipline: "Control Systems", accept: ["open loop control", "open loop system"], clues: ["A control scheme that never checks whether it actually worked.", "It has no sensor feeding information back to the controller.", "It's simple and cheap, but blind to disturbances.", "A microwave running for a fixed time, regardless of the food's actual temperature, is a classic example.", "A control system that applies a predetermined input without measuring or correcting for the actual output."], reveal: "A control system that applies a predetermined input based purely on expectation, with no sensor measuring the actual output to correct for error. It's simpler and cheaper than closed-loop control, but blind to disturbances — a microwave timer runs for a fixed duration regardless of what's actually happening to the food inside." },
  { answer: "Terzaghi Bearing Capacity", discipline: "Geotechnical Engineering", accept: ["terzaghi bearing capacity", "terzaghi", "bearing capacity"], clues: ["It concerns what the ground beneath a structure can take.", "The equation has three terms: cohesion, surcharge and self-weight.", "Each term carries a dimensionless factor dependent on friction angle.", "It assumes a general shear failure mechanism.", "Named after the father of soil mechanics."], reveal: "q_ult = cN_c + qN_q + 0.5γBN_γ — the ultimate bearing capacity of soil beneath a shallow foundation. Its three terms separately account for cohesion, surcharge from surrounding material, and the soil's own self-weight, each scaled by a friction-angle-dependent factor." },
  { answer: "Amplitude", discipline: "Signal Processing", accept: ["amplitude"], clues: ["A property of a wave that has nothing to do with how fast it repeats.", "It's the maximum displacement of a wave from its resting, zero position.", "Turn a volume knob up, and you're really just increasing this for a sound wave.", "A taller wave on an oscilloscope screen means a larger value of this.", "The maximum height, or displacement, a wave reaches from its resting position."], reveal: "The maximum displacement of a wave from its rest position — its height, essentially, independent of how fast it repeats. Turning up a volume knob increases exactly this property of the sound wave, not its frequency." },
  { answer: "Rivet Gun", discipline: "Manufacturing", accept: ["rivet gun", "pop rivet gun", "riveter"], clues: ["A tool built to install a fastener that, once set, can't easily be removed.", "It permanently deforms the tail of the fastener to lock it in place.", "A single squeeze snaps off the fastener's center pin once it's fully set.", "Aircraft skins are held together with thousands of the fasteners this tool installs.", "The hand tool used to squeeze and set pop rivets, permanently joining two sheets of material."], reveal: "A hand tool that pulls a rivet's center pin through its body, deforming the rivet's tail against the far side of the material to clamp two sheets together permanently — then snaps the pin off once it's fully set." },
  { answer: "Center of Pressure", discipline: "Aerodynamics", accept: ["center of pressure", "centre of pressure", "cop"], clues: ["A point where an entire distributed load can be replaced by one single force.", "Unlike the centre of gravity, its position isn't fixed — it moves as conditions change.", "Change the angle of attack and it shifts along the chord.", "Its relationship to the centre of gravity governs a lot of an aircraft's basic stability.", "The single point along an airfoil's chord where the entire aerodynamic force can be considered to act."], reveal: "The single point along an airfoil's chord where the entire distributed aerodynamic force can be considered to act as one resultant. Unlike the fixed centre of gravity, it migrates along the chord as angle of attack changes, and its position relative to the centre of gravity is a major factor in an aircraft's inherent pitch stability." },
  { answer: "CAN Bus", discipline: "Embedded Systems", accept: ["can bus", "controller area network", "can"], clues: ["A two-wire differential bus, developed by Bosch in the 1980s.", "There is no addressing of nodes — messages carry identifiers instead.", "Arbitration is non-destructive: the lower identifier simply wins.", "It needs 120 ohm termination at both ends.", "It's in essentially every car built since the 1990s."], reveal: "A robust multi-master serial bus using message identifiers and non-destructive bitwise arbitration. There's no addressing of individual nodes — every message carries a priority identifier, and when two nodes transmit at once the lower identifier wins without either message being corrupted." },
  { answer: "Zener Diode", discipline: "Electronics", accept: ["zener diode", "zener"], clues: ["A component deliberately operated in a mode that would destroy its cousin.", "It works in reverse bias, past a designed breakdown point.", "You must always pair it with a series resistor.", "Its knee voltage is remarkably stable with current.", "Used as a simple voltage reference or clamp."], reveal: "A diode deliberately operated in reverse breakdown, engineered so that beyond its rated voltage, current can rise sharply while the voltage across it stays nearly constant. Paired with a series resistor to limit current, it's used as a simple voltage regulator, reference, or clamp." },
  { answer: "Wing Nut", discipline: "Mechanical Design", accept: ["wing nut", "wingnut", "butterfly nut"], clues: ["A fastener with two flared wings that exist purely so a screwdriver becomes unnecessary.", "You tighten and loosen it entirely by hand, between finger and thumb.", "It's the obvious choice wherever a fastener needs to be removed and replaced frequently.", "A jigsaw puzzle's clamp or a bicycle's quick-release seat post commonly use one.", "The nut with two flared wings that lets you tighten or loosen it entirely by hand."], reveal: "A nut with two flat wings extending from its sides, sized to be gripped and turned entirely by hand — no tool needed — making it the go-to choice for a fastener meant to be removed and replaced often." },
  { answer: "Martensite", discipline: "Metallurgy", accept: ["martensite", "martensitic transformation"], clues: ["It forms without any diffusion at all.", "The transformation is essentially instantaneous.", "Its crystal structure is body-centred tetragonal, heavily distorted.", "It's extremely hard and extremely brittle, so tempering usually follows.", "It's what you get when you quench steel rapidly."], reveal: "The hard, supersaturated phase formed by rapid quenching of austenite, via a diffusionless shear transformation. Because the transformation happens by shear rather than atomic diffusion, it occurs almost instantaneously, locking carbon into a severely distorted, brittle lattice." },
  { answer: "Sensor Calibration", discipline: "Instrumentation", accept: ["sensor calibration", "calibration"], clues: ["A process that has nothing to do with a sensor's precision, only its accuracy.", "It compares a sensor's output against a known, trusted reference standard.", "Without it, a perfectly precise sensor can still be confidently, consistently wrong.", "Traceability to a national or international standard is what gives the process real credibility.", "The process of comparing a sensor's output against a known reference to correct for systematic error."], reveal: "The process of comparing a sensor's output against a known, trusted reference standard and correcting for any systematic offset or scaling error found. It's entirely distinct from precision — a poorly calibrated sensor can be perfectly repeatable and still be confidently, consistently wrong, which is why traceability back to a recognised standard is what actually gives a measurement credibility." },
  { answer: "Gasket", discipline: "Manufacturing", accept: ["gasket"], clues: ["A component whose entire job is to fill in the gaps another part leaves behind.", "It sits compressed between two mating surfaces that were never machined perfectly smooth.", "Replace it whenever an engine starts weeping oil from a joint that used to be dry.", "It seals against leaks without needing to be strong enough to bear any structural load.", "The thin part squeezed between two surfaces to seal a joint and stop leaks."], reveal: "A thin, compressible part clamped between two mating surfaces to seal the gap between them, stopping fluid or gas from leaking out even though neither surface is machined perfectly flat." },
  { answer: "Water Hammer", discipline: "Fluid Machinery", accept: ["water hammer", "waterhammer", "hydraulic shock"], clues: ["You have heard it in a domestic plumbing system.", "It happens when momentum has nowhere to go.", "The pressure spike can exceed the pipe's rating many times over.", "Surge tanks and slow-closing valves are the standard mitigations.", "It's caused by a sudden change in fluid velocity."], reveal: "A pressure surge produced when a moving column of fluid is forced to stop or change direction suddenly. The spike can momentarily exceed a pipe's rated limit several times over, which is why slow-closing valves and surge tanks are standard mitigations." },
  { answer: "Arch Bridge", discipline: "Civil Engineering", accept: ["arch bridge", "arch"], clues: ["One of the oldest bridge forms still built today, dating back millennia.", "It carries load almost entirely by pushing outward, not by bending.", "Every piece of it is ideally kept in pure compression.", "Roman engineers relied heavily on it, often without any mortar at all.", "A curved structural form that transfers load to its supports primarily through compression."], reveal: "A curved structural form that carries load down to its supports primarily through compression along its own curve, rather than through bending. Roman engineers exploited this so effectively that many of their stone arch bridges and aqueducts were built with no mortar at all — every stone simply held the next in compression." },
  { answer: "Free Body Diagram", discipline: "Statics", accept: ["free body diagram", "fbd"], clues: ["The first thing taught in any statics or dynamics course.", "It isolates one object from everything touching it.", "Every force and moment acting on that object gets drawn as an arrow.", "Get it wrong and every equation that follows is wrong too.", "It's the essential first step before applying Newton's laws or equilibrium equations."], reveal: "A simplified sketch of a single body showing every external force and moment acting on it, with the surrounding structure stripped away. It's the foundational step in solving almost any statics or dynamics problem — an error here propagates through every calculation that follows." },
  { answer: "Magnetic Field", discipline: "Electromagnetics", accept: ["magnetic field"], clues: ["An invisible region of influence surrounding anything from a fridge magnet to an entire planet.", "It's what a compass needle actually responds to, wherever it happens to be placed.", "A moving electric charge always creates one, whether inside a wire or a solenoid.", "Iron filings sprinkled nearby will arrange themselves along its invisible curved lines.", "The region around a magnet or current-carrying wire where a magnetic force can be detected."], reveal: "The region of space around a magnet or a moving electric charge where a magnetic force can act on another magnet or moving charge. A compass needle, and a sprinkle of iron filings, both respond to and trace out its shape." },
  { answer: "Mass Balance", discipline: "Chemical Engineering", accept: ["mass balance", "material balance"], clues: ["An accounting exercise applied to matter instead of money.", "It's built on one unbreakable rule: matter can't simply appear or disappear.", "In equals out, plus or minus whatever accumulates or reacts inside.", "Every process design starts with drawing a boundary and applying exactly this.", "An accounting of mass entering, leaving, accumulating and reacting within a defined system boundary."], reveal: "An accounting of mass entering, leaving, accumulating and reacting within a defined system boundary, grounded in the simple, unbreakable rule that matter can't be created or destroyed. It's the first calculation drawn up for essentially any process design, from a single mixing tank to an entire refinery." },
  { answer: "Support Vector Machine", discipline: "Machine Learning", accept: ["support vector machine", "svm"], clues: ["A classification method that cares most about the hardest-to-classify points, not the easy ones.", "It searches for the boundary that leaves the widest possible margin on both sides.", "The points closest to that boundary are the ones that actually define it.", "A mathematical trick lets it draw curved boundaries while still doing simple linear math underneath.", "A classifier that finds the maximum-margin hyperplane separating classes, using only the closest data points to define it."], reveal: "A classifier that finds the hyperplane separating two classes with the widest possible margin on either side, defined entirely by the closest points to that boundary — the support vectors that give the method its name. The so-called kernel trick lets it draw curved decision boundaries while the underlying computation stays purely linear." },
  { answer: "Nozzle", discipline: "Fluid Mechanics", accept: ["nozzle"], clues: ["A shaped opening whose only job is to change how a fluid leaves a pipe.", "Narrow its opening and, for an incompressible flow, the exit velocity climbs.", "A garden hose's adjustable tip is a simple everyday example.", "Rocket engines use a carefully flared version to accelerate exhaust to extreme speeds.", "The shaped opening at the end of a pipe or hose that controls how a fluid exits."], reveal: "A shaped fitting at the end of a pipe that controls the speed, direction, and spread of a fluid as it exits — from a garden hose tip to a rocket engine's flared exhaust cone, all working on the same speed-versus-area trade-off." },
  { answer: "Phillips Screw", discipline: "Manufacturing", accept: ["phillips screw", "phillips head screw", "cross-head screw"], clues: ["A fastener named after the man who patented its driving shape, not its inventor.", "Its recess is designed to let a driver cam out under too much torque, by design.", "You'd need a driver with an X-shaped tip, not a flat one, to turn it.", "Look at the head from above and you'll see a small cross cut into it.", "The common screw with a cross-shaped recess in its head, driven by a matching screwdriver."], reveal: "A screw with a cross-shaped recess in its head, designed to be driven by a matching cross-tip screwdriver. The shape was deliberately engineered to let the driver cam out — slip free — before the screw or driver is over-torqued." },
  { answer: "Transformer", discipline: "Electrical Engineering", accept: ["transformer", "electrical transformer"], clues: ["It moves energy between two circuits that never physically touch.", "Two coils, sharing one magnetic core.", "The ratio of turns on each coil sets how voltage changes between them.", "It only works with AC — a steady DC current does nothing useful here.", "A device that transfers electrical energy between circuits via electromagnetic induction, changing voltage according to a turns ratio."], reveal: "A device that transfers electrical energy between two electrically isolated coils purely through electromagnetic induction, stepping voltage up or down according to their turns ratio. Because it relies on a changing magnetic flux, it only works with alternating current — a constant DC current produces no induced voltage at all." },
  { answer: "Bond Graph", discipline: "Systems Engineering", accept: ["bond graph", "bondgraph"], clues: ["A modelling notation, not an equation.", "It treats mechanical, hydraulic and electrical systems in one unified language.", "Every connection carries an effort and a flow whose product is power.", "Half-arrows show the direction of power transfer.", "Developed at MIT by Henry Paynter."], reveal: "A domain-independent graphical modelling method representing energy flow through effort–flow pairs. Because every domain — electrical, mechanical, hydraulic — reduces to the same effort-flow bookkeeping, one bond graph can model a whole mixed-physics system at once." },
  { answer: "Response Spectrum", discipline: "Structural Engineering", accept: ["response spectrum", "seismic response spectrum"], clues: ["A single chart that summarises how an entire earthquake record would affect any structure.", "Its horizontal axis is a structure's own natural period, not time.", "It's built by running that same ground motion through many different simple oscillators.", "Building codes hand designers a smoothed, idealised version of it directly.", "A plot of the peak response of single-degree-of-freedom oscillators of varying natural period to a given ground motion."], reveal: "A plot of the peak response — typically acceleration — of simple single-degree-of-freedom oscillators across a range of natural periods, all subjected to the same ground motion record. Building codes provide designers with a smoothed, idealised version of it, letting a structure's expected seismic demand be read off directly once its own natural period is known." },
  { answer: "Psychrometric Chart", discipline: "Heat Transfer", accept: ["psychrometric chart", "psychrometrics", "psychrometric"], clues: ["A dense, curved chart that looks intimidating at first.", "Its saturation line runs up the left-hand side.", "Axes include dry bulb, wet bulb, and humidity ratio.", "You plot processes on it: heating, cooling, mixing, dehumidifying.", "It's the essential design tool for air conditioning."], reveal: "A chart plotting the thermodynamic properties of moist air, used to design air-conditioning processes. Heating, cooling, humidifying and mixing streams of air all show up as simple straight-line moves on the chart, despite how dense it looks at first glance." },
  { answer: "Buzzer", discipline: "Electronics", accept: ["buzzer", "piezo buzzer"], clues: ["A component whose entire output is sound, and nothing else.", "A piezoelectric version vibrates a small disc when voltage is applied across it.", "Microwaves and smoke detectors both rely on one to get your attention.", "It converts an electrical signal directly into an audible tone.", "The small electronic component that produces a beeping or buzzing sound when powered."], reveal: "A small electronic component that converts an electrical signal directly into an audible tone — a piezoelectric version does it by vibrating a thin ceramic disc. It's the beep behind everything from microwaves to smoke alarms." },
  { answer: "Rare Earth Magnet", discipline: "Materials", accept: ["rare earth magnet", "neodymium magnet"], clues: ["A magnet made from elements that, despite the name, aren't actually all that rare geologically.", "Gram for gram, it's dramatically stronger than an ordinary ferrite magnet.", "A small one can pinch your finger hard enough to bruise it.", "Neodymium is the most common element behind this powerful category of magnet.", "The extremely strong permanent magnet made from elements like neodymium."], reveal: "A permanent magnet made from alloys of rare-earth elements — most commonly neodymium — producing a magnetic field dramatically stronger, size for size, than an ordinary ferrite magnet. Despite the name, the elements involved aren't actually geologically scarce." },
  { answer: "Direct Memory Access", discipline: "Computer Engineering", accept: ["direct memory access", "dma"], clues: ["A way for a device to bypass the processor entirely for one specific job.", "It lets data move straight between a peripheral and memory.", "Without it, every single byte transferred would have to pass through the processor.", "It frees the processor up to do other useful work while a transfer happens in the background.", "A method allowing peripherals to read or write system memory directly, without routing data through the CPU."], reveal: "A method that lets a peripheral device read from or write to system memory directly, without routing every single byte through the processor. It frees the CPU to keep working on other tasks while a large data transfer — a disk read, for instance — happens in the background." },
  { answer: "Clutch", discipline: "Mechanical Design", accept: ["clutch"], clues: ["A component that can connect or disconnect two rotating shafts without stopping either one.", "Engage it and torque flows through; disengage it and the two sides spin independently.", "A manual-transmission car's driver operates one with the left-most foot pedal.", "It lets an engine keep idling even while the wheels it's connected to sit completely still.", "The mechanism that connects or disconnects two rotating shafts, letting one spin freely of the other."], reveal: "A mechanism that engages or disengages two rotating shafts, letting torque pass through when connected or letting each side spin independently when not — most familiar as the pedal that lets a manual car's idling engine decouple from its stationary wheels." },
  { answer: "Kaizen", discipline: "Lean Manufacturing", accept: ["kaizen", "continuous improvement"], clues: ["A Japanese philosophy built on small steps rather than dramatic leaps.", "It assumes every process, no matter how good, can still be improved.", "Everyone on the floor, not just management, is expected to contribute ideas.", "It's one of the foundational pillars of the Toyota Production System.", "A philosophy of continuous, incremental improvement involving every employee in a process."], reveal: "A Japanese philosophy of continuous, incremental improvement, built on the belief that every process — no matter how refined — can still be made a little better. Unlike top-down overhauls, it deliberately involves everyone on the floor, not just management, and forms one of the foundational pillars of the Toyota Production System." },
  { answer: "Gyroscope", discipline: "Sensors", accept: ["gyroscope"], clues: ["A sensor that measures a rate, not a position.", "It reports how fast something is rotating, in degrees or radians per second.", "Modern versions are usually vibrating MEMS structures, not spinning mechanical wheels.", "Combined with an accelerometer, it forms the core of an inertial measurement unit.", "A device measuring angular velocity, the rate of rotation about one or more axes."], reveal: "A device that measures angular velocity — the rate of rotation about one or more axes — rather than absolute orientation itself. Modern versions are almost always tiny vibrating MEMS structures rather than spinning mechanical wheels, and paired with an accelerometer they form the core of the inertial measurement units inside drones, phones and spacecraft alike." },
  { answer: "Otto Cycle", discipline: "Thermodynamics", accept: ["otto cycle", "otto"], clues: ["Four processes, and in practice four strokes.", "Heat addition happens at constant volume.", "Its efficiency depends only on compression ratio and gamma.", "Knock is what limits how far you can push that ratio.", "It's the idealised cycle of a petrol engine."], reveal: "The ideal spark-ignition cycle with constant-volume heat addition; efficiency depends only on compression ratio. Push the ratio too high, though, and the fuel-air mixture can ignite prematurely on its own — the knock that ultimately limits real-engine efficiency." },
  { answer: "Proton", discipline: "Physics", accept: ["proton"], clues: ["A particle that gives an atom's nucleus its positive charge.", "The number of these in a nucleus is what actually defines which chemical element an atom is.", "It sits in the nucleus alongside the neutron, but unlike it, carries an electric charge.", "Change how many of these a nucleus has, and you've changed the element entirely, not just the isotope.", "The positively charged particle in an atom's nucleus whose count defines the element."], reveal: "A positively charged particle in an atom's nucleus, whose count — the atomic number — is what actually defines which chemical element the atom is. Change that count and you've transmuted the atom into a different element entirely." },
  { answer: "Shannon Entropy", discipline: "Signal Processing", accept: ["shannon entropy", "information entropy"], clues: ["It borrows its name from thermodynamics but measures something else.", "It is measured in bits.", "A fair coin gives exactly one; a two-headed coin gives zero.", "It sets the theoretical floor on lossless compression.", "H = −Σ p log p."], reveal: "The average information content of a source, setting the minimum bits per symbol for lossless coding. A perfectly predictable source carries zero entropy and needs no bits to describe, while one where every outcome is equally likely needs the most." },
  { answer: "Natural Frequency", discipline: "Vibrations", accept: ["natural frequency", "resonant frequency", "resonance"], clues: ["Every physical structure has at least one, whether you want it to or not.", "Drive a system at this frequency and its response can grow dramatically.", "A wine glass shattering from a singer's voice is a famous example.", "The Tacoma Narrows Bridge collapse is popularly, if imperfectly, blamed on it.", "The frequency at which a system oscillates freely once disturbed, with no external driving force."], reveal: "The frequency at which a system naturally oscillates once disturbed and left alone, determined by its stiffness and mass. Drive that same system with an external force at or near this frequency and the response can amplify dramatically — the phenomenon of resonance." },
  { answer: "Ion", discipline: "Chemistry", accept: ["ion"], clues: ["A particle carrying a property that a neutral atom doesn't have.", "It forms when an atom gains or loses one or more electrons.", "Gain extra electrons and the charge goes negative; lose some and it goes positive.", "Table salt dissolves in water into two of these, one from sodium and one from chlorine.", "An atom or molecule with a net electric charge from gaining or losing electrons."], reveal: "An atom or molecule that has gained or lost one or more electrons, leaving it with a net electric charge — negative if it gained electrons, positive if it lost them. Dissolved salt splits into exactly this kind of charged pair." },
  { answer: "Rivet", discipline: "Manufacturing", accept: ["rivet"], clues: ["A permanent fastener installed by deforming it, not by turning it.", "It starts as a smooth shaft with one head, and gains a second head only during installation.", "Undo it and you're left with two holes and a scrap fastener, not a reusable joint.", "Thousands of them, driven by hand or by robot, hold an airplane's skin together.", "The permanent metal fastener set by hammering or squeezing one end into a second head."], reveal: "A permanent fastener with a factory-formed head on one end; installing it deforms the other end into a second head, clamping the joined material between the two. Unlike a bolt, it can't be undone without destroying it." },
  { answer: "Boundary Layer", discipline: "Fluid Mechanics", accept: ["boundary layer"], clues: ["A concept introduced by Prandtl in 1904 that rescued fluid dynamics.", "It is very thin, and everything interesting happens inside it.", "Outside it, you can pretend viscosity doesn't exist.", "It can be laminar, then transition, then become turbulent.", "When it separates, you get stall and a large drag increase."], reveal: "The thin region adjacent to a surface where viscous effects dominate and velocity rises from zero to freestream. Outside this thin sliver, the flow behaves almost as if viscosity didn't exist — a simplification that made modern aerodynamics tractable." },
  { answer: "Ammeter", discipline: "Instrumentation", accept: ["ammeter"], clues: ["A meter that must be spliced directly into a circuit's path, never just touched across it.", "Its internal resistance is deliberately made very low, so it barely disturbs the circuit it's measuring.", "It answers exactly one question: how much current is actually flowing right here?", "Wire it in backwards, in series, and the whole circuit still has to flow straight through it.", "The meter that measures the current flowing through a point in a circuit."], reveal: "A meter wired directly in series into a circuit's current path to measure the current flowing through it. It's built with very low internal resistance, so inserting it barely changes the current it's trying to measure." },
  { answer: "Recurrent Neural Network", discipline: "Deep Learning", accept: ["recurrent neural network", "rnn"], clues: ["A network architecture built for data where order genuinely matters.", "It carries a hidden state forward from one step to the next.", "Text, speech and time-series data are its natural habitat.", "Training it over long sequences runs into a notorious vanishing gradient problem.", "A neural network architecture with connections looping back, allowing it to maintain state across a sequence of inputs."], reveal: "A neural network architecture with connections that loop back on themselves, letting it carry a hidden state forward across a sequence of inputs — well suited to text, speech and time-series data where order matters. Training it over long sequences runs into a notorious vanishing gradient problem, which specialised variants like LSTM were designed specifically to fix." },
  { answer: "Z-Transform", discipline: "Control Systems", accept: ["z transform"], clues: ["The Laplace transform's counterpart for a world of discrete samples.", "It's the natural language of digital control and digital signal processing.", "A time delay in the discrete world becomes a simple multiplication by z⁻¹.", "Its stability boundary is a unit circle, not an imaginary axis.", "An integral transform converting a discrete-time signal into a complex-frequency-domain representation."], reveal: "An integral transform that converts a discrete-time sequence into a representation in the complex z-domain, playing the same role for sampled, digital systems that the Laplace transform plays for continuous ones. Its stability boundary is the unit circle rather than the imaginary axis, and a pure time delay becomes nothing more than multiplication by z⁻¹." },
  { answer: "Weibull Distribution", discipline: "Reliability Engineering", accept: ["weibull distribution", "weibull"], clues: ["A statistical distribution flexible enough to model all three stages of a famous curve.", "One shape parameter alone decides whether failure rate rises, falls or stays flat.", "It's the workhorse distribution behind most modern reliability analysis.", "Named after a Swedish engineer who applied it to material strength and fatigue life.", "A flexible probability distribution used to model time-to-failure data, capable of representing increasing, decreasing or constant failure rates."], reveal: "A flexible probability distribution used throughout reliability engineering to model time-to-failure data, with a single shape parameter that decides whether the modelled failure rate rises, falls or stays constant over time. That flexibility is exactly why it can represent all three regions of the bathtub curve — infant mortality, random failure, and wear-out — within one unified model." },
  { answer: "Maxwell's Equations", discipline: "Electromagnetics", accept: ["maxwells equations", "maxwell equations", "maxwell"], clues: ["Four of them, and they fit on a T-shirt.", "They unified two forces previously thought separate.", "They predict a wave travelling at a very specific speed.", "That speed turned out to be the speed of light.", "Named after a Scottish physicist."], reveal: "The four equations governing electric and magnetic fields, unifying electricity, magnetism and light. Combined, they predict a self-propagating electromagnetic wave travelling at a fixed speed — which turned out to be exactly the speed of light." },
  { answer: "Turbofan Engine", discipline: "Aerospace Engineering", accept: ["turbofan engine", "turbofan"], clues: ["The engine type powering essentially every modern commercial airliner.", "Most of its thrust doesn't come from air that ever touches the combustion chamber.", "A large front fan bypasses air around the engine core entirely.", "The ratio of that bypassed air to the air actually burned is a defining design number.", "A jet engine where a large fan bypasses most incoming air around the core, generating most thrust outside combustion."], reveal: "A jet engine in which a large front fan pushes most of its incoming air around the combustion core entirely rather than through it, generating the bulk of its thrust from that bypassed air rather than from combustion exhaust. The ratio of bypassed to combusted air — the bypass ratio — is a defining design parameter, and modern high-bypass engines are dramatically quieter and more fuel-efficient than older, low-bypass designs." },
  { answer: "Bragg's Law", discipline: "Materials", accept: ["braggs law", "bragg law", "bragg"], clues: ["It underpins a whole family of characterisation techniques.", "It concerns constructive interference from parallel planes.", "The spacing it reveals is on the order of ångströms.", "nλ = 2d sin θ.", "A father-and-son pair won a Nobel Prize for it."], reveal: "The condition for constructive interference of X-rays scattered by crystal lattice planes. Because the wavelengths involved are comparable to atomic spacing, the diffraction pattern it predicts lets crystallographers read off a material's atomic structure directly." },
  { answer: "Concave Lens", discipline: "Optics", accept: ["concave lens", "diverging lens"], clues: ["A lens shaped so it's thinner in the middle than at its edges, the opposite of the other common shape.", "Parallel light rays passing through it spread apart instead of converging.", "It always produces a smaller, upright image, never a magnified one.", "A nearsighted person's glasses typically use this shape to help focus distant objects.", "The lens, thinner in the middle than at the edges, that spreads light rays apart instead of focusing them."], reveal: "A lens that's thinner at its center than at its edges, spreading parallel light rays apart rather than focusing them to a point. It's the shape typically prescribed for nearsightedness, where distant objects need to be brought into focus." },
  { answer: "DC Motor", discipline: "Electrical Engineering", accept: ["dc motor", "direct current motor"], clues: ["A machine that turns steady electrical current into continuous rotation.", "Inside, a magnetic field pushes on a current-carrying coil to produce torque.", "Reverse the polarity of its supply and it spins the other way.", "It's the simple motor type found in most battery-powered toys.", "An electric motor that runs on direct current, converting electrical energy into continuous rotary motion."], reveal: "An electric motor that converts direct current into continuous rotation, using the force between a magnetic field and a current-carrying coil to produce torque. Reversing the supply polarity reverses the direction it spins." },
  { answer: "Four-Bar Linkage", discipline: "Mechanical Design", accept: ["four bar linkage", "four bar mechanism"], clues: ["The simplest closed-loop mechanism that can still do useful, complex motion.", "It's made of four rigid links connected by four pins.", "One link is usually fixed to the frame and never moves.", "Grashof's criterion tells you whether any link can complete a full rotation.", "A windshield wiper mechanism is a familiar everyday example."], reveal: "A mechanism of four rigid links joined by four revolute pins, forming the simplest closed kinematic chain capable of complex, non-trivial motion. Whether any of its links can rotate fully or only rock back and forth is decided by Grashof's criterion, based purely on the four link lengths." },
  { answer: "Stack", discipline: "Computer Science", accept: ["stack", "lifo", "call stack"], clues: ["A structure with exactly one way in and one way out — the same way.", "The last thing added is always the first thing removed.", "Undo buttons in software are commonly built on top of it.", "Your program's own function calls are tracked on one, behind the scenes.", "A last-in-first-out data structure supporting push and pop operations only at one end."], reveal: "A last-in-first-out data structure that only allows adding or removing elements from one end, through push and pop operations. Every running program relies on one implicitly — the call stack — to track which function called which, and in what order they need to return." },
  { answer: "Nuclear Fusion", discipline: "Nuclear Engineering", accept: ["nuclear fusion", "fusion"], clues: ["A process that joins nuclei together instead of splitting one apart.", "It's the reaction that powers every star, including the sun.", "It requires temperatures and pressures that are almost unimaginably extreme.", "Achieving a sustained, net-positive version of it on Earth remains a formidable engineering challenge.", "The combining of two light atomic nuclei into a heavier one, releasing enormous energy in the process."], reveal: "The combining of two light atomic nuclei — most commonly isotopes of hydrogen — into a single heavier nucleus, releasing enormous energy in the process. It's the reaction that powers every star, including the sun, but replicating it on Earth in a sustained, net-energy-positive way remains one of engineering's most formidable unsolved challenges." },
  { answer: "Annealing", discipline: "Manufacturing", accept: ["annealing", "anneal"], clues: ["A heat treatment, though its goal is the opposite of most.", "Three stages: recovery, recrystallisation, grain growth.", "The cooling rate is deliberately slow.", "It relieves residual stress and restores ductility.", "It undoes the effects of cold working."], reveal: "Heating and slow-cooling a material to relieve internal stresses, soften it and restore ductility. It works through three stages — recovery, recrystallisation and grain growth — essentially undoing whatever work hardening a prior cold-forming step introduced." },
  { answer: "Analog-to-Digital Converter", discipline: "Electronics", accept: ["analog to digital converter", "adc"], clues: ["A translator standing at the border between two very different worlds.", "It converts a continuously varying signal into discrete numbers.", "Its output resolution is set by how many bits it produces per sample.", "Every microphone feeding into a digital recording eventually passes through one.", "A device that converts a continuous analogue signal into a discrete digital representation."], reveal: "A device that samples a continuously varying analogue signal at regular intervals and converts each sample into a discrete digital number, with resolution set by how many bits it produces per sample. It's the essential bridge between the analogue physical world and every digital system that processes, stores or transmits data about it." },
  { answer: "Electrocardiogram", discipline: "Biomedical Engineering", accept: ["electrocardiogram", "ecg", "ekg"], clues: ["A recording of electrical activity, not mechanical motion.", "Electrodes placed on the skin pick up signals generated deep inside the chest.", "Its characteristic waveform is broken into named segments: P, QRS, T.", "An abnormal rhythm shows up as a distortion in that familiar, repeating pattern.", "A recording of the heart's electrical activity over time, measured via electrodes placed on the skin."], reveal: "A recording of the heart's electrical activity over time, picked up through electrodes placed on the skin and traced out as a characteristic repeating waveform broken into named segments — P, QRS and T. An abnormal heart rhythm or damaged tissue shows up as a recognisable distortion in that otherwise consistent pattern." },
  { answer: "Newton's Cradle", discipline: "Dynamics", accept: ["newton's cradle", "newtons cradle"], clues: ["A desk toy that's really a live demonstration of two separate conservation laws at once.", "Lift one ball at the end, release it, and one ball pops out the opposite end.", "The number of balls that swing out matches the number you released, every time.", "It relies on momentum and kinetic energy both being conserved through each collision.", "The desk toy with a row of swinging metal balls that demonstrates conservation of momentum."], reveal: "A desk toy with a row of suspended metal balls that demonstrates conservation of momentum and energy: release one ball and the same number pop out the far end, since both quantities must be conserved through each near-perfectly elastic collision." },
  { answer: "Direct Current", discipline: "Electrical Power", accept: ["direct current", "dc"], clues: ["A form of electrical current that flows in one direction only, and never reverses.", "Every battery, by its very nature, supplies exactly this kind of current.", "Solar panels and most electronic chips also generate or need it internally.", "A wall charger's real job is quietly converting AC from the outlet into this.", "Electric current that flows steadily in a single direction, like the current from a battery."], reveal: "Electric current that flows in a single, unchanging direction, exactly like the output of a battery or a solar panel. Since most electronics run on it internally, a big part of a phone charger's job is converting AC from the wall into it." },
  { answer: "Ground Effect", discipline: "Aerodynamics", accept: ["ground effect"], clues: ["An aerodynamic bonus that only appears very close to a surface.", "It reduces induced drag noticeably once a wing gets within about a wingspan of the ground.", "Pilots feel it as an aircraft seeming to 'float' just before touchdown.", "Wing-in-ground-effect vehicles are built to exploit it constantly, not just briefly.", "The reduction in induced drag and increase in lift a wing experiences when flying close to the ground."], reveal: "The reduction in induced drag and boost in lift a wing experiences once it flies within roughly a wingspan of the ground, as the surface interferes with the wingtip vortices that would otherwise form freely. Pilots feel it as a distinct 'floating' sensation just before touchdown, and some specialised vehicles are designed to exploit it continuously, cruising just above water or ground." },
  { answer: "Standard Penetration Test", discipline: "Geotechnical Engineering", accept: ["standard penetration test", "spt"], clues: ["A field test that's cheap, simple, and remarkably widely used despite both.", "A weighted hammer, dropped from a fixed height, drives a sampler into the ground.", "The result is simply a count of blows needed to drive it a set distance.", "That blow count correlates, roughly, with soil density and strength.", "A field test measuring the number of hammer blows needed to drive a sampler a fixed distance into soil."], reveal: "A field test that drives a standard sampler into the ground using a hammer of fixed weight dropped from a fixed height, recording the number of blows needed to advance it a set distance. That simple blow count correlates, at least roughly, with soil density and strength, which is why it remains one of the most widely used site investigation tests despite its simplicity." },
  { answer: "Zip Tie", discipline: "Manufacturing", accept: ["zip tie", "cable tie", "zip-tie"], clues: ["A one-way fastener with a ratcheting mechanism built right into its own body.", "Pull it tighter and a small internal pawl stops it from ever loosening on its own.", "Electricians reach for it constantly to bundle loose wires together.", "You'll need cutters to remove one — it was never designed to be reused.", "The plastic strap with a ratcheting head, pulled tight to bundle cables or wires."], reveal: "A plastic strap with a built-in ratcheting head: a small pawl catches on ridges along the strap's length, letting it cinch tighter but never loosen on its own. Removing one usually means cutting it off." },
  { answer: "K-Means Clustering", discipline: "Machine Learning", accept: ["k means clustering", "k means"], clues: ["An unsupervised method — it's never told the right answer to learn from.", "You have to decide in advance how many groups you're looking for.", "It alternates between assigning points to the nearest centre and recomputing those centres.", "It keeps repeating that cycle until the centres stop moving.", "An unsupervised algorithm that partitions data into k clusters by iteratively assigning points to the nearest cluster centroid."], reveal: "An unsupervised algorithm that partitions data into a chosen number of clusters, k, by alternating between assigning each point to its nearest cluster centroid and recomputing those centroids from the newly assigned points. It repeats that two-step cycle until the centroids stop moving, with no labelled data guiding it at any point." },
  { answer: "Seebeck Effect", discipline: "Sensors", accept: ["seebeck effect", "seebeck", "thermoelectric effect"], clues: ["It requires a junction of two dissimilar materials.", "The output is only tens of microvolts per degree.", "You need cold junction compensation to make sense of it.", "Type K, type J and type T are the common variants.", "It's the operating principle of the thermocouple."], reveal: "A voltage generated across a junction of two dissimilar conductors held at different temperatures. The output is only tens of microvolts per degree, so practical use — as in a thermocouple — depends on carefully compensating for the reference, or 'cold', junction too." },
  { answer: "Torsional Shear Stress", discipline: "Solid Mechanics", accept: ["torsional shear stress", "torsion", "shaft torsion"], clues: ["The stress a drive shaft feels, not a beam.", "It's zero at the centre and maximum at the outer surface.", "A hollow shaft can carry nearly as much torque as a solid one for far less weight.", "It depends on the polar moment of inertia of the cross-section.", "τ = Tr/J — torque times radius, divided by polar moment of inertia."], reveal: "The shear stress distributed through a shaft's cross-section when it's twisted by an applied torque, rising linearly from zero at the centre to a maximum at the outer surface. Because material near the centre carries almost no stress, hollow shafts are often used to save weight without sacrificing much torque capacity." },
  { answer: "Catalysis", discipline: "Chemical Engineering", accept: ["catalysis", "catalyst"], clues: ["A way to speed up a reaction without becoming part of the outcome.", "The substance responsible emerges from the reaction chemically unchanged.", "It works by opening up a lower-energy pathway to the same product.", "A car's catalytic converter relies on it to clean up exhaust gases.", "The acceleration of a chemical reaction by a substance that is not itself consumed in the process."], reveal: "The acceleration of a chemical reaction through a substance that provides a lower-energy pathway to the same products, without being consumed itself in the process. A car's catalytic converter is a familiar everyday example, using precious-metal catalysts to convert harmful exhaust gases into less harmful ones far faster than they'd react on their own." },
  { answer: "Piston", discipline: "Fluid Machinery", accept: ["piston"], clues: ["A component that moves back and forth in a straight line inside a closely fitting cylinder.", "Pressure from combustion, air or fluid pushes directly against one of its flat faces.", "Rings around its edge seal it tightly against the cylinder wall as it slides.", "In a car engine, its up-and-down motion is what ultimately turns the crankshaft.", "The disk that slides back and forth inside a cylinder, driven by or driving fluid pressure."], reveal: "A close-fitting disk that slides back and forth inside a cylinder, sealed against the wall by surrounding rings. Pressure — from combustion, compressed air, or hydraulic fluid — pushes it, or it pushes the fluid, depending on the machine." },
  { answer: "Aliasing", discipline: "Signal Processing", accept: ["aliasing"], clues: ["A distortion that happens specifically when you don't listen closely enough.", "A spinning wagon wheel appearing to turn backwards in old films is a classic visual example.", "It's the direct consequence of violating the Nyquist-Shannon sampling theorem.", "Once it happens, the original signal can never be recovered from the sampled data.", "High frequencies masquerading as lower, false frequencies after inadequate sampling."], reveal: "The distortion that occurs when a signal is sampled too slowly, causing high frequencies to fold back and masquerade as false, lower frequencies in the sampled data. It's the direct, unavoidable consequence of violating the Nyquist-Shannon sampling theorem, and once it happens the original signal can't be recovered from the corrupted samples alone." },
  { answer: "Statistical Process Control", discipline: "Quality Engineering", accept: ["statistical process control", "spc", "control chart", "control charts"], clues: ["Developed by Walter Shewhart at Bell Labs in the 1920s.", "It distinguishes two fundamentally different sources of variation.", "Those are called common cause and special cause.", "Limits are drawn at three sigma, not at the specification.", "Reacting to common-cause variation is called tampering, and makes things worse."], reveal: "Monitoring a process with control charts to distinguish inherent variation from genuine, assignable disturbances. Control limits sit at three standard deviations from the process's own natural variation, and reacting to ordinary noise as if it were signal — tampering — makes things worse." },
  { answer: "Prestressed Concrete", discipline: "Civil Engineering", accept: ["prestressed concrete", "prestressing", "post tensioning", "pre tensioning"], clues: ["It exploits the fact that one material is far better in one direction than the other.", "You deliberately introduce stress before any service load is applied.", "It comes in pre-tensioned and post-tensioned varieties.", "Losses from creep, shrinkage and relaxation must be accounted for.", "Freyssinet made it practical in the 1920s."], reveal: "Concrete with internal compressive stress deliberately introduced by tensioned tendons, offsetting service tensile stresses. Since concrete is strong in compression but weak in tension, pre-loading it lets the section resist service loads without ever going into net tension." },
  { answer: "Forward Kinematics", discipline: "Robotics", accept: ["forward kinematics"], clues: ["A calculation that goes from the inside out.", "You already know every joint angle; you want to know where that leaves the hand.", "It's a purely geometric problem, with exactly one correct answer.", "Chain together each joint's transformation and you arrive at the end effector's pose.", "Computing the position and orientation of a robot's end effector from its known joint angles."], reveal: "The calculation of a robot's end effector position and orientation directly from its known joint angles, working outward link by link from the base. Because each joint's transformation is fixed and known, this direction of the problem has exactly one correct answer — unlike its far trickier counterpart, inverse kinematics." },
  { answer: "Biot Number", discipline: "Heat Transfer", accept: ["biot number", "biot"], clues: ["A dimensionless number that decides whether a 'lumped' shortcut is allowed.", "It compares resistance inside a solid to resistance at its surface.", "Below about 0.1, you can treat the whole object as one uniform temperature.", "Above that, temperature gradients inside the solid can no longer be ignored.", "Bi = hL/k — surface convection resistance compared with internal conduction resistance."], reveal: "A dimensionless ratio comparing the resistance to heat conduction inside a solid against the resistance to convection at its surface. A small value means the object heats or cools almost uniformly throughout, justifying the simplified lumped-capacitance approach; a large value means internal temperature gradients can't be ignored." },
  { answer: "Resistance Temperature Detector", discipline: "Instrumentation", accept: ["resistance temperature detector", "rtd", "platinum rtd", "pt100"], clues: ["A temperature sensor prized for one quality above all: stability.", "It's built from a pure metal wire, most commonly platinum.", "Its resistance rises smoothly and predictably as temperature increases.", "It's far more linear than a thermistor, though also less sensitive.", "A temperature sensor using a pure metal's predictable resistance-temperature relationship, most commonly platinum."], reveal: "A temperature sensor exploiting the predictable, nearly linear way a pure metal's resistance rises with temperature, most commonly built from platinum wire in the standard Pt100 design. It trades the thermistor's high sensitivity for excellent long-term stability and repeatability, which is why it's the standard choice for precision industrial measurement." },
  { answer: "Von Neumann Architecture", discipline: "Computer Engineering", accept: ["von neumann architecture", "von neumann", "stored program architecture"], clues: ["A structure proposed in a 1945 draft report.", "Its defining feature is treating two things as the same kind of thing.", "Harvard architecture is the usual alternative named alongside it.", "It suffers from a well-known bottleneck between processor and memory.", "Instructions and data share one memory and one bus."], reveal: "A computer design in which program instructions and data occupy the same memory and share one bus. Sharing them keeps the design simple, but it also creates a well-known bottleneck since the processor can't fetch an instruction and a piece of data at once." },
  { answer: "Atom", discipline: "Chemistry", accept: ["atom"], clues: ["The name comes from a Greek word meaning 'indivisible,' which turned out to be wrong.", "It has a dense, positively charged core orbited by much lighter negative particles.", "Split it and you release the energy behind both nuclear power and nuclear weapons.", "It's the smallest unit of an element that still has that element's chemical properties.", "The basic building block of matter, made of protons, neutrons and electrons."], reveal: "The smallest unit of an element that retains that element's chemical properties — a dense nucleus of protons and neutrons surrounded by orbiting electrons. Its name comes from the Greek for 'indivisible,' a description physics eventually proved wrong." },
  { answer: "Heat Shrink Tubing", discipline: "Manufacturing", accept: ["heat shrink tubing", "heat shrink", "shrink wrap tubing"], clues: ["A plastic sleeve manufactured in an expanded state on purpose, so it can do its job later.", "Applying heat doesn't melt it — it returns the material to a smaller shape it 'remembers.'", "Slide it over a wire splice before you ever reach for a heat gun.", "It shrinks tightly around whatever it covers, sealing and insulating in one step.", "The plastic sleeve that shrinks tightly around a wire splice when heated, insulating and protecting it."], reveal: "A polymer sleeve manufactured in an expanded state, then locked there — heating it later lets the material relax back toward its original, smaller molded size, shrinking it tightly around whatever it covers to insulate and seal a splice." },
  { answer: "Electromagnet", discipline: "Electromagnetics", accept: ["electromagnet"], clues: ["A magnet you can switch on and off, unlike the kind stuck to your fridge.", "Wrap wire in a coil, run current through it, and it suddenly behaves like a bar magnet.", "Wrap that coil around an iron core and its strength multiplies dramatically.", "Junkyard cranes use a giant one to lift and then simply drop a car.", "A magnet created by running electric current through a coil of wire, usually around an iron core."], reveal: "A magnet created by passing electric current through a coil of wire, often wound around an iron core to concentrate and strengthen the field. Unlike a permanent magnet, switch off the current and the magnetism disappears too." },
  { answer: "Hinge", discipline: "Mechanical Design", accept: ["hinge"], clues: ["A component that permits rotation around a single fixed axis, and nothing else.", "Two plates, joined by a pin running through interlocking knuckles, define its whole design.", "A door swings open and shut around exactly this kind of joint.", "It constrains every motion except rotation about one line.", "The joint that allows two parts to rotate relative to each other around a fixed axis, as on a door."], reveal: "A joint made of two plates connected by a pin through interlocking knuckles, constraining motion to rotation about a single fixed axis — the mechanism that lets a door swing open and closed." },
  { answer: "Zeroth Law of Thermodynamics", discipline: "Thermodynamics", accept: ["zeroth law", "zeroth law of thermodynamics"], clues: ["It was formalised after the others, hence its odd name.", "It sounds trivially obvious, but nothing else works without it.", "It is a statement about transitivity.", "If A and B each agree with C, then A and B agree with each other.", "It is what makes a thermometer meaningful."], reveal: "Two systems each in thermal equilibrium with a third are in equilibrium with each other — this defines temperature. It sounds too obvious to need stating, but without it there would be no logical basis for comparing a thermometer's reading to anything else." },
  { answer: "Kirchhoff's Voltage Law", discipline: "Electrical Engineering", accept: ["kirchhoffs voltage law", "kvl", "kirchhoffs second law"], clues: ["The partner to a law you may already have seen here.", "It is conservation of energy applied to charge.", "It applies around a closed loop, not at a node.", "Go all the way round and you must end up where you started.", "Abbreviated with three letters, the middle one being V."], reveal: "The sum of voltage rises and drops around any closed loop in a circuit is zero. It's really conservation of energy applied to a charge travelling all the way around a loop back to where it started, with nowhere for net energy to go missing." },
  { answer: "Base Isolation", discipline: "Structural Engineering", accept: ["base isolation", "seismic base isolation"], clues: ["A seismic design strategy that works by decoupling, not by strengthening.", "The building sits on flexible bearings instead of being rigidly fixed to the ground.", "It lets the ground shake while the structure above moves far more gently.", "Lead-rubber bearings are a common way of implementing it.", "A seismic protection technique that decouples a building from ground motion using flexible bearings at its base."], reveal: "A seismic protection technique in which a building is mounted on flexible bearings, decoupling the structure above from the shaking ground below. Rather than trying to resist an earthquake's forces by brute strength, the whole building rides out the shaking while its bearings absorb and dramatically reduce the motion transmitted upward." },
  { answer: "De Morgan's Laws", discipline: "Digital Logic", accept: ["de morgans laws", "demorgans laws", "de morgan", "demorgan"], clues: ["Two identities that come as a matched pair.", "They let you convert between two gate types freely.", "Break the bar and change the sign, as the mnemonic goes.", "NAND and NOR gates are functionally complete because of them.", "Named after a 19th-century British logician."], reveal: "NOT(A AND B) = NOT A OR NOT B, and NOT(A OR B) = NOT A AND NOT B. They let a designer freely trade AND gates for OR gates and back again, which is exactly why NAND and NOR gates alone are enough to build any logic function." },
  { answer: "Charpy Impact Test", discipline: "Materials", accept: ["charpy", "charpy impact test", "charpy test"], clues: ["A swinging pendulum and a notched specimen.", "The result is measured in joules, from the height the pendulum recovers.", "It is comparative rather than a design input.", "Run it at several temperatures and you get a transition curve.", "The notch is a V, and the specimen is 10 mm square."], reveal: "A pendulum impact test measuring the energy absorbed by a notched specimen during fracture. Repeating it across a range of temperatures traces out the transition from tough, ductile fracture to sudden brittle failure as the material cools." },
  { answer: "Protractor", discipline: "Metrology", accept: ["protractor"], clues: ["An instrument shaped like a half-circle, marked entirely in units of rotation.", "It reads out a value in degrees, from zero all the way up to 180.", "Every geometry student eventually needs one to draw or measure an angle precisely.", "Line its base edge up along one side of an angle to read the angle directly off its arc.", "The flat, half-circle instrument marked in degrees, used to measure or draw angles."], reveal: "A flat, semicircular instrument marked in degrees from 0 to 180, used to measure or draw an angle by aligning its base edge with one side of the angle and reading where the other side crosses the arc." },
  { answer: "Integral Windup", discipline: "Control Systems", accept: ["integral windup", "windup", "controller windup"], clues: ["A problem that shows up specifically when an actuator hits its physical limit.", "The integral term keeps accumulating even though the output can't respond any further.", "When the error finally reverses, the response overshoots badly before recovering.", "Clamping or back-calculation are the standard fixes for it.", "The excessive accumulation of integral error when a controller's output saturates, causing large overshoot once it recovers."], reveal: "The excessive buildup of accumulated integral error that occurs when a controller's commanded output saturates at an actuator's physical limit, even though the error hasn't actually been corrected. Once the error finally reverses, that pent-up integral term drives a large, sluggish overshoot before the controller recovers — exactly what anti-windup schemes like clamping exist to prevent." },
  { answer: "Specific Gravity", discipline: "Fluid Mechanics", accept: ["specific gravity", "relative density"], clues: ["A ratio, so it carries no units at all.", "It always compares against the same reference substance.", "That reference is water, at a specified temperature.", "A value below one means it floats; above one, it sinks.", "The ratio of a substance's density to the density of water."], reveal: "The ratio of a substance's density to the density of water at a reference temperature, giving a simple, unitless number for comparison. Anything with a specific gravity below one floats in water; anything above one sinks — mercury, for instance, comes in at roughly 13.6." },
  { answer: "Terminal Block", discipline: "Electronics", accept: ["terminal block", "terminal strip"], clues: ["A component with no active function of its own — it exists purely to connect other things.", "Wires clamp into it from either side, joined without any soldering or twisting.", "Electricians use rows of it inside a panel to organize dozens of connections neatly.", "Loosen its screw, slide a wire in, tighten it back down.", "The connector with screw-clamped terminals used to join wires without soldering."], reveal: "A modular connector with a row of screw-clamped terminals, letting wires be joined or organized without soldering or twisting. Electrical panels use long strips of them to keep dozens of wire connections tidy and serviceable." },
];

/* ---------- Day numbering ----------
   Puzzle #1 was 2026-08-28. Everyone plays the puzzle for their own local
   calendar date, so on any given instant up to three puzzles are "today"
   somewhere in the world. */
const EPOCH_UTC = Date.UTC(2026, 7, 28);
const DAY_MS = 86400000;

export function dayNumber(d = new Date()) {
  // Compare calendar dates in UTC so DST shifts (23/25-hour days) can't skew the count.
  const today = Date.UTC(d.getFullYear(), d.getMonth(), d.getDate());
  return Math.round((today - EPOCH_UTC) / DAY_MS) + 1;
}

export function puzzleForNumber(n) {
  const i = (((n - 1) % PUZZLES.length) + PUZZLES.length) % PUZZLES.length;
  return { ...PUZZLES[i], number: n };
}

// The highest puzzle number whose day is over everywhere on Earth. UTC-12 is the
// last time zone to finish a calendar day, so a puzzle is safe to explain
// publicly once its day has ended there.
export function lastFinishedNumber(now = Date.now()) {
  const d = new Date(now - 12 * 3600000);
  const latest = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
  return Math.round((latest - EPOCH_UTC) / DAY_MS);
}

// Calendar date (as a UTC midnight Date) on which puzzle n was played.
export function dateForNumberUTC(n) {
  return new Date(EPOCH_UTC + (n - 1) * DAY_MS);
}

export function slugify(s) {
  return s
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/['\u2019`]/g, "")
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
